window.QUIZ_CONFIG={"title": "國中會考單字片語｜全部主題綜合", "mode": "mcq", "questions": [{"id": 1, "question": "Jeremy made a great ______ and scored two points for his team.", "options": ["case", "rule", "sound", "shot"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) shot\n【單字】shot (n.)：投籃；射門\n【中譯】Jeremy 漂亮地投籃，為他的隊伍得了兩分。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 2, "question": "Mom left a ______ on the table: \"Your lunch is in the fridge.\"", "options": ["note", "ground", "level", "land"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) note\n【單字】note (n.)：便條\n【中譯】媽媽在桌上留了一張便條：「你的午餐在冰箱裡。」", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 3, "question": "A ______ is a small animal. It sleeps in the day and flies at night.", "options": ["bat", "seal", "sentence", "book"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) bat\n【單字】bat (n.)：蝙蝠\n【中譯】蝙蝠是一種小動物。牠白天睡覺，晚上飛行。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 4, "question": "I tried to fix my bike, but I ______. It is still broken.", "options": ["danced", "smiled", "failed", "stayed"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) failed\n【單字】fail (v.)：失敗\n【中譯】我試著修理我的腳踏車，但是我失敗了。它還是壞的。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 5, "question": "In the movie, the bad man always wears ______ clothes, so it is hard to see him at night.", "options": ["blank", "giant", "black", "present"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) black\n【單字】black (adj.)：黑色的\n【中譯】在電影裡，那個壞人總是穿黑色的衣服，所以晚上很難看見他。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 6, "question": "There is a ______ swimming in the lake. It says, \"Quack, quack.\"", "options": ["paper", "cut", "duck", "bow"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) duck\n【單字】duck (n.)：鴨\n【中譯】湖裡有一隻鴨子在游泳。牠叫著：「呱呱。」", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 7, "question": "I got up at five this morning. It was too ______ for my brother, so he was still sleeping.", "options": ["early", "giant", "pop", "down"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) early\n【單字】early (adj.)：早的\n【中譯】我今天早上五點起床。對我弟弟來說太早了，所以他還在睡覺。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 8, "question": "Don't take out your money. Dinner tonight is my ______.", "options": ["treat", "screen", "gas", "nose"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) treat\n【單字】treat (n.)：請客\n【中譯】別拿出你的錢。今晚的晚餐我請客。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 9, "question": "Mia started to play the piano at three, and she plays beautifully. She is a ______ musician.", "options": ["born", "smooth", "first", "present"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) born\n【單字】born (adj.)：天生的\n【中譯】Mia 三歲就開始彈鋼琴，而且她彈得很美。她是個天生的音樂家。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 10, "question": "Stop! The traffic light is ______. You can't cross the street now.", "options": ["kind", "open", "mean", "red"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) red\n【單字】red (adj.)：紅色的\n【中譯】停！紅綠燈是紅色的。你現在不能過馬路。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 11, "question": "The shoe store is having a big ______ this week. Everything is half price.", "options": ["level", "sale", "screen", "line"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) sale\n【單字】sale (n.)：特賣\n【中譯】那家鞋店這星期在舉行大特賣。所有東西都半價。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 12, "question": "My cousin is a ______. She wears beautiful clothes in fashion shows.", "options": ["model", "patient", "cook", "course"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) model\n【單字】model (n.)：模特兒\n【中譯】我的表姊是模特兒。她在時裝秀中穿漂亮的衣服。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 13, "question": "Ben has no brothers or sisters. He is the ______ child in his family.", "options": ["only", "many", "each", "all"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) only\n【單字】only (adj.)：唯一的\n【中譯】Ben 沒有兄弟姊妹。他是家中唯一的小孩。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 14, "question": "Don't be nervous. Just stay ______ and answer the questions slowly.", "options": ["mad", "fat", "cool", "terrible"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) cool\n【單字】cool (adj.)：冷靜的\n【中譯】別緊張。只要保持冷靜，慢慢回答問題。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 15, "question": "I take piano ______ every Saturday. My teacher is Ms. Wang.", "options": ["times", "lessons", "hands", "answers"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) lessons\n【單字】lesson (n.)：課程\n【中譯】我每個星期六上鋼琴課。我的老師是王老師。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 16, "question": "We took the ______ from Taipei Station to Hsinchu. It was fast and comfortable.", "options": ["nose", "sentence", "level", "train"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) train\n【單字】train (n.)：火車\n【中譯】我們從台北車站搭火車到新竹。又快又舒服。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 17, "question": "My family lived in Hualien in 2015. I was only six years old ______.", "options": ["yet", "far", "then", "hard"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) then\n【單字】then (adv.)：在那時\n【中譯】我家在 2015 年住在花蓮。我那時只有六歲。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 18, "question": "I ______ my English teacher at the supermarket yesterday. She said hi to me.", "options": ["booked", "met", "hunted", "fed"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) met\n【單字】meet (v.)：遇見\n【中譯】我昨天在超市遇見我的英文老師。她跟我打招呼。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 19, "question": "Have you seen my ______ dog? He ran away last night, and I can't find him.", "options": ["hundred", "pop", "lost", "thousand"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) lost\n【單字】lost (adj.)：遺失的\n【中譯】你有看到我走失的狗嗎？牠昨晚跑走了，我找不到牠。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 20, "question": "Ken told a funny ______, and everyone in the class laughed.", "options": ["nose", "dish", "joke", "bank"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) joke\n【單字】joke (n.)：玩笑\n【中譯】Ken 說了一個好笑的笑話，全班都笑了。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 21, "question": "I wrote a ______ to my grandma and sent it to her by mail.", "options": ["party", "ground", "slice", "letter"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) letter\n【單字】letter (n.)：信件\n【中譯】我寫了一封信給我奶奶，並用郵寄寄給她。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 22, "question": "Walk to the ______ of this street, and you will see the post office.", "options": ["answer", "feed", "dish", "end"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) end\n【單字】end (n.)：盡頭\n【中譯】走到這條街的盡頭，你就會看到郵局。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 23, "question": "A: Would you like some more tea?\nB: Yes, ______. Thank you.", "options": ["please", "before", "or", "until"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) please\n【單字】please (int.)：請\n【中譯】A：你想再來點茶嗎？\nB：好的，麻煩你了。謝謝。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 24, "question": "The ______ on my little finger broke when I opened the can.", "options": ["slice", "bow", "sentence", "nail"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) nail\n【單字】nail (n.)：指甲\n【中譯】我打開罐頭時，小指的指甲斷了。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 25, "question": "There was so much ______ last night that the streets were all wet this morning.", "options": ["rain", "feed", "play", "land"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) rain\n【單字】rain (n.)：雨\n【中譯】昨晚下了好多雨，所以今天早上街道都是濕的。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 26, "question": "We are going on a ______ to Japan next week. We will stay there for five days.", "options": ["case", "hand", "trip", "bank"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) trip\n【單字】trip (n.)：旅程\n【中譯】我們下星期要去日本旅行。我們會在那裡待五天。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 27, "question": "Our school basketball team won the ______ last night. The score was 60 to 52.", "options": ["screen", "seal", "book", "game"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) game\n【單字】game (n.)：比賽\n【中譯】我們學校的籃球隊昨晚贏了比賽。比數是 60 比 52。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 28, "question": "Let's go to the ______ and play on the grass under the trees.", "options": ["park", "slice", "answer", "feed"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) park\n【單字】park (n.)：公園\n【中譯】我們去公園，在樹下的草地上玩吧。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 29, "question": "Ms. Lin is very ______. She never gets angry when we ask the same question again and again.", "options": ["patient", "down", "giant", "many"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) patient\n【單字】patient (adj.)：有耐心的\n【中譯】林老師很有耐心。我們一再問同樣的問題時，她從不生氣。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 30, "question": "In spring, the grass and the leaves on the trees are ______.", "options": ["mean", "cross", "present", "green"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) green\n【單字】green (adj.)：綠色的\n【中譯】春天時，草和樹上的葉子是綠色的。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 31, "question": "My sister loves art. She ______ pictures of flowers every weekend.", "options": ["mops", "feeds", "paints", "catches"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) paints\n【單字】paint (v.)：繪畫\n【中譯】我姊姊熱愛藝術。她每個週末都畫花的圖畫。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 32, "question": "Hurry up! The bus is coming. We don't want to be ______ for school.", "options": ["smooth", "late", "light", "giant"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) late\n【單字】late (adj.)：晚的；遲的\n【中譯】快點！公車來了。我們上學可不想遲到。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 33, "question": "Tom looked at his friend's answers during the math test. The teacher said, \"Don't ______!\"", "options": ["land", "fish", "row", "cheat"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) cheat\n【單字】cheat (v.)：作弊\n【中譯】Tom 在數學考試時看他朋友的答案。老師說：「不准作弊！」", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 34, "question": "Put the milk ______ the fridge, or it will go bad.", "options": ["by", "through", "in", "over"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) in\n【單字】in (prep.)：在…裡面\n【中譯】把牛奶放進冰箱裡，否則它會壞掉。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 35, "question": "I have to write a ______ about Taiwan's animals for my science class.", "options": ["report", "gas", "land", "bow"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) report\n【單字】report (n.)：報告\n【中譯】我必須為自然課寫一篇關於台灣動物的報告。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 36, "question": "It takes ______ twenty minutes to walk from my home to school.", "options": ["up", "far", "back", "around"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) around\n【單字】around (adv.)：大約\n【中譯】從我家走路到學校大約要二十分鐘。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 37, "question": "Please ______ my hand when we cross the street.", "options": ["hold", "comb", "save", "mop"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) hold\n【單字】hold (v.)：握\n【中譯】我們過馬路時，請握住我的手。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 38, "question": "The bird flew out of its cage. Now it is ______ and can go anywhere.", "options": ["thousand", "free", "mean", "first"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) free\n【單字】free (adj.)：自由的\n【中譯】那隻鳥飛出了籠子。現在牠自由了，可以去任何地方。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 39, "question": "My brother is a big ______ of that baseball team. He goes to all of their games.", "options": ["time", "fan", "cut", "answer"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) fan\n【單字】fan (n.)：粉絲\n【中譯】我哥哥是那支棒球隊的超級粉絲。他會去看他們所有的比賽。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 40, "question": "Bananas turn ______ when they are ready to eat.", "options": ["present", "kind", "yellow", "thousand"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) yellow\n【單字】yellow (adj.)：黃色的\n【中譯】香蕉可以吃的時候會變成黃色。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 41, "question": "Class starts at eight, and it's a ______ to eight now. We have fifteen minutes.", "options": ["kid", "dish", "nose", "quarter"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) quarter\n【單字】quarter (n.)：一刻鐘\n【中譯】八點上課，現在是七點四十五分（差一刻八點）。我們還有十五分鐘。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 42, "question": "We have studied for two hours. Let's take a ______ and drink some water.", "options": ["ground", "break", "nose", "land"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) break\n【單字】break (n.)：休息\n【中譯】我們已經讀了兩個小時的書。我們休息一下，喝點水吧。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 43, "question": "The singer is singing in the stadium right now, and you can watch the ______ show on TV.", "options": ["mean", "fat", "down", "live"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) live\n【單字】live (adj.)：現場的\n【中譯】那位歌手現在正在體育館唱歌，你可以在電視上看現場節目。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 44, "question": "In the story, an old man gives Jack some ______ beans. They grow into a very tall tree in one night.", "options": ["blank", "first", "magic", "present"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) magic\n【單字】magic (adj.)：神奇的\n【中譯】在故事裡，一位老人給了 Jack 一些神奇的豆子。它們在一夜之間長成一棵非常高的樹。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 45, "question": "The cat is sleeping ______ the roof. I can see it from my window.", "options": ["on", "to", "until", "since"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) on\n【單字】on (prep.)：在…上面\n【中譯】貓正在屋頂上睡覺。我從窗戶就能看到牠。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 46, "question": "Mom wrote a ______ of things to buy before she went to the supermarket.", "options": ["ring", "cover", "list", "pipe"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) list\n【單字】list (n.)：清單\n【中譯】媽媽去超市之前寫了一張要買的東西的清單。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 47, "question": "The basketball game is ______. Our team won 80 to 75!", "options": ["patient", "over", "white", "kind"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) over\n【單字】over (adj.)：結束\n【中譯】籃球比賽結束了。我們隊以80比75獲勝！", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 48, "question": "She has a big smile on her ______.", "options": ["can", "ticket", "stop", "face"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) face\n【單字】face (n.)：臉\n【中譯】她臉上帶著大大的微笑。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 49, "question": "I had two pieces of ______ with butter and jam for breakfast.", "options": ["sight", "fear", "smell", "toast"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) toast\n【單字】toast (n.)：土司\n【中譯】我早餐吃了兩片塗奶油和果醬的土司。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 50, "question": "My sister looks ______ my mom. They both have big eyes and long hair.", "options": ["through", "like", "since", "besides"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) like\n【單字】like (prep.)：像\n【中譯】我姊姊長得像我媽媽。她們都有大眼睛和長頭髮。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 51, "question": "The ______ today is May 5th.", "options": ["date", "view", "salt", "fall"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) date\n【單字】date (n.)：日期\n【中譯】今天的日期是五月五日。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 52, "question": "This park is a nice ______ for a picnic. There are many trees and a lake.", "options": ["letter", "pot", "subject", "place"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) place\n【單字】place (n.)：地方\n【中譯】這座公園是野餐的好地方。那裡有很多樹和一座湖。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 53, "question": "______ I finished my homework, I went out to play with my friends.", "options": ["Or", "Until", "Finally", "After"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) After\n【單字】after (conj.)：在…之後\n【中譯】在我寫完功課之後，我就出去和朋友玩。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 54, "question": "Be careful! Don't play with ______. It's very hot and can burn your house.", "options": ["dip", "fire", "rain", "bow"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) fire\n【單字】fire (n.)：火\n【中譯】小心！不要玩火。火非常燙，而且可能會燒掉你的房子。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 55, "question": "My English teacher gave me a good ______ for learning new words: read them aloud every day.", "options": ["seal", "pay", "tip", "bill"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) tip\n【單字】tip (n.)：秘訣\n【中譯】我的英文老師給了我一個學新單字的好秘訣：每天大聲唸出來。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 56, "question": "I'm thirsty. Can I have ______ water, please?", "options": ["some", "each", "both", "many"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) some\n【單字】some (adj.)：一些（的）\n【中譯】我口渴了。請問我可以喝一些水嗎？", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 57, "question": "I ______ a bakery on my way to school every morning, and it always smells great.", "options": ["fail", "cheat", "pass", "comb"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) pass\n【單字】pass (v.)：路過\n【中譯】我每天早上上學途中都會路過一家麵包店，那裡總是很香。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 58, "question": "A ______ landed on my sandwich, so I didn't eat it.", "options": ["order", "kind", "figure", "fly"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) fly\n【單字】fly (n.)：蒼蠅\n【中譯】一隻蒼蠅停在我的三明治上，所以我沒有吃它。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 59, "question": "Long ago, people ______ deer and rabbits for food.", "options": ["fooled", "bullied", "hunted", "felt"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) hunted\n【單字】hunt (v.)：打獵\n【中譯】很久以前，人們獵捕鹿和兔子當作食物。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 60, "question": "We had a party for Dad's birthday, and he didn't know about it. It was a big ______ for him.", "options": ["yard", "pot", "block", "surprise"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) surprise\n【單字】surprise (n.)：驚喜\n【中譯】我們為爸爸辦了生日派對，而他事先不知道。這對他來說是一個大驚喜。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 61, "question": "Carrots and pumpkins are usually ______.", "options": ["patient", "orange", "pop", "cross"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) orange\n【單字】orange (adj.)：橘色的\n【中譯】紅蘿蔔和南瓜通常是橘色的。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 62, "question": "About two ______ people live in this big city.", "options": ["million", "second", "half", "early"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) million\n【單字】million (adj.)：百萬\n【中譯】大約有兩百萬人住在這座大城市裡。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 63, "question": "Our dance teacher taught us a cool new dance ______ today.", "options": ["comb", "seal", "move", "pipe"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) move\n【單字】move (n.)：舞蹈動作\n【中譯】我們的舞蹈老師今天教我們一個很酷的新舞蹈動作。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 64, "question": "I put a red ______ on the map to show where our school is.", "options": ["mark", "cold", "trouble", "age"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) mark\n【單字】mark (n.)：記號\n【中譯】我在地圖上畫了一個紅色記號，標出我們學校的位置。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 65, "question": "Our class leader always picks up trash first, and the other students follow her ______.", "options": ["lead", "floor", "salt", "nail"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) lead\n【單字】lead (n.)：帶頭；榜樣\n【中譯】我們的班長總是第一個撿垃圾，其他同學都以她為榜樣、跟著她做。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 66, "question": "Bees make ______. It is sweet and good in tea.", "options": ["lead", "rock", "gas", "honey"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) honey\n【單字】honey (n.)：蜂蜜\n【中譯】蜜蜂會製造蜂蜜。它很甜，加在茶裡很好喝。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 67, "question": "I hurt my left ______ when I played soccer, so I can't walk well now.", "options": ["foot", "heat", "nose", "bank"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) foot\n【單字】foot (n.)：腳\n【中譯】我踢足球時傷到了左腳，所以現在不太能好好走路。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 68, "question": "Drink more milk, and you will ______ tall.", "options": ["take", "cheat", "mop", "grow"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) grow\n【單字】grow (v.)：成長\n【中譯】多喝牛奶，你就會長高。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 69, "question": "The ______ on my bag is broken, so I can't close it.", "options": ["burn", "star", "zip", "rule"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) zip\n【單字】zip (n.)：拉鍊\n【中譯】我包包上的拉鍊壞了，所以我關不起來。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 70, "question": "There are many ______ waiting in line at the bus stop.", "options": ["nails", "rules", "pots", "people"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) people\n【單字】people (n.)：人們（複數）\n【中譯】有很多人在公車站排隊等車。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 71, "question": "Dad was ______ because I broke his new phone.", "options": ["close", "mad", "even", "born"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) mad\n【單字】mad (adj.)：生氣的\n【中譯】爸爸很生氣，因為我弄壞了他的新手機。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 72, "question": "Grandma smiled with ______ when she opened our present.", "options": ["pleasure", "quarter", "pipe", "level"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) pleasure\n【單字】pleasure (n.)：愉快\n【中譯】奶奶打開我們的禮物時愉快地笑了。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 73, "question": "The name ______ my dog is Lucky.", "options": ["through", "since", "until", "of"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) of\n【單字】of (prep.)：屬於…的\n【中譯】我的狗的名字是 Lucky。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 74, "question": "The ______ on the door says \"No Smoking.\"", "options": ["smile", "sign", "dish", "shot"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) sign\n【單字】sign (n.)：標誌\n【中譯】門上的標誌寫著「禁止吸菸」。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 75, "question": "My mom keeps a ______ of all the money she spends every day.", "options": ["record", "sale", "bow", "swing"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) record\n【單字】record (n.)：紀錄\n【中譯】我媽媽把她每天花的錢都做了紀錄。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 76, "question": "Don't be ______ to your little brother. Be nice to him.", "options": ["free", "hard", "mean", "still"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) mean\n【單字】mean (adj.)：兇的；刻薄的\n【中譯】不要對你弟弟那麼兇。要對他好一點。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 77, "question": "We went to the bookstore ______ a new dictionary.", "options": ["of", "since", "through", "for"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) for\n【單字】for (prep.)：為了\n【中譯】我們為了買一本新字典去了書店。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 78, "question": "A ______ came off my shirt. Can you sew it back on for me?", "options": ["button", "bat", "table", "bill"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) button\n【單字】button (n.)：鈕扣\n【中譯】我襯衫上的一顆鈕扣掉了。你可以幫我縫回去嗎？", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 79, "question": "In winter, the tops of the mountains are covered with white ______.", "options": ["interest", "trick", "duck", "snow"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) snow\n【單字】snow (n.)：雪\n【中譯】冬天時，山頂被白雪覆蓋。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 80, "question": "This song has a fast ______, so it's great for dancing.", "options": ["beat", "excuse", "trip", "cut"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) beat\n【單字】beat (n.)：節奏；拍子\n【中譯】這首歌節奏很快，所以很適合跳舞。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 81, "question": "The ______ of this tool is to open cans.", "options": ["use", "bet", "row", "stand"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) use\n【單字】use (n.)：用途\n【中譯】這個工具的用途是開罐頭。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 82, "question": "______ it rained a lot, so the ground is still wet today.", "options": ["Too", "Just", "Yesterday", "Tomorrow"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) Yesterday\n【單字】yesterday (adv.)：昨天\n【中譯】昨天下了很多雨，所以今天地面還是濕的。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 83, "question": "Please sit on this ______. It has a soft seat and a back.", "options": ["pot", "fan", "chair", "ring"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) chair\n【單字】chair (n.)：椅子\n【中譯】請坐這張椅子。它有軟軟的座墊和椅背。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 84, "question": "My cat is very fat. It weighs fifteen ______.", "options": ["seconds", "pounds", "grades", "yards"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) pounds\n【單字】pound (n.)：磅\n【中譯】我的貓很胖。牠重十五磅。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 85, "question": "Young kids should sit in the ______ seat of the car, not in the front seat.", "options": ["key", "back", "late", "live"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) back\n【單字】back (adj.)：後面的\n【中譯】年幼的孩子應該坐在汽車的後座，而不是前座。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 86, "question": "Please ______ the sleeping baby on the bed gently.", "options": ["surf", "row", "lay", "cheat"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) lay\n【單字】lay (v.)：放置\n【中譯】請把睡著的寶寶輕輕地放在床上。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 87, "question": "This stone feels ______. There are no rough parts on it.", "options": ["pretty", "lost", "smooth", "present"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) smooth\n【單字】smooth (adj.)：平滑的（觸感）\n【中譯】這塊石頭摸起來很平滑。上面沒有粗糙的地方。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 88, "question": "My grandparents live in the ______. They have a farm and many animals.", "options": ["country", "party", "race", "sentence"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) country\n【單字】country (n.)：鄉下\n【中譯】我的祖父母住在鄉下。他們有一座農場和許多動物。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 89, "question": "The bus is so ______ today. I think we will be late for school.", "options": ["only", "own", "slow", "top"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) slow\n【單字】slow (adj.)：慢的\n【中譯】今天公車好慢。我想我們上學會遲到。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 90, "question": "We heard a loud ______ for help from the river.", "options": ["course", "cry", "comb", "pack"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) cry\n【單字】cry (n.)：呼喊聲；叫聲\n【中譯】我們聽到河邊傳來一聲大聲的呼救聲。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 91, "question": "Good job! All your answers on the test are ______.", "options": ["lost", "right", "mad", "cross"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) right\n【單字】right (adj.)：正確的\n【中譯】做得好！你考試的答案全部都是正確的。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 92, "question": "The little girl sat on the ______, and her dad pushed her high into the air.", "options": ["mop", "swing", "toast", "fan"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) swing\n【單字】swing (n.)：鞦韆\n【中譯】小女孩坐在鞦韆上，她爸爸把她推得高高的。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 93, "question": "Let's get some fresh juice at the juice ______ next to the gym.", "options": ["pipe", "bar", "yard", "nail"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) bar\n【單字】bar (n.)：（賣飲料、點心的）櫃臺；吧\n【中譯】我們去體育館旁邊的果汁吧買些新鮮果汁吧。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 94, "question": "Did the mailman bring any ______ for me? I'm waiting for a letter from Grandma.", "options": ["smoke", "honey", "mail", "rock"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) mail\n【單字】mail (n.)：信件\n【中譯】郵差有送我的信件來嗎？我在等奶奶寄來的信。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 95, "question": "Please don't throw kitchen ______ into the river. It makes the water dirty.", "options": ["fear", "magic", "pop", "waste"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) waste\n【單字】waste (n.)：廢棄物\n【中譯】請不要把廚房廢棄物丟進河裡，它會讓河水變髒。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 96, "question": "Every night, Mom reads me a ______ before I go to sleep.", "options": ["story", "duck", "ring", "comb"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) story\n【單字】story (n.)：故事\n【中譯】每天晚上，媽媽會在我睡覺前唸一個故事給我聽。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 97, "question": "Can you buy a ______ of tissues for me? I have a cold.", "options": ["slice", "pot", "drop", "pack"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) pack\n【單字】pack (n.)：一包\n【中譯】你可以幫我買一包面紙嗎？我感冒了。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 98, "question": "My grandma lives far away in Tainan, so I really ______ her.", "options": ["trick", "miss", "fool", "bully"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) miss\n【單字】miss (v.)：想念\n【中譯】我奶奶住在很遠的台南，所以我真的很想念她。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 99, "question": "What's the ______ with you? You look sad.", "options": ["list", "matter", "dish", "fan"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) matter\n【單字】matter (n.)：事件\n【中譯】你怎麼了（發生什麼事了）？你看起來很難過。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 100, "question": "The weather was ______ yesterday. It rained all day, and we couldn't go out.", "options": ["terrible", "patient", "clear", "free"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) terrible\n【單字】terrible (adj.)：糟糕的\n【中譯】昨天天氣很糟糕。下了一整天的雨，我們都不能出門。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 101, "question": "There is a fruit ______ on the street corner. The old man there sells cheap apples.", "options": ["stand", "cross", "fan", "pipe"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) stand\n【單字】stand (n.)：小攤\n【中譯】街角有一個水果攤，那裡的老先生賣便宜的蘋果。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 102, "question": "Mr. Lin was a great ______ at his party. He gave all his guests food and drinks.", "options": ["giant", "patient", "bully", "host"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) host\n【單字】host (n.)：主人\n【中譯】林先生在他的派對上是個很棒的主人，他給所有客人食物和飲料。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 103, "question": "The soup is ______ hot that I can't eat it now.", "options": ["even", "so", "yet", "still"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) so\n【單字】so (adv.)：如此地\n【中譯】這湯如此燙，所以我現在沒辦法喝。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 104, "question": "The teacher drew a big ______ on the board and said, \"This is the sun.\"", "options": ["cross", "line", "circle", "key"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) circle\n【單字】circle (n.)：圓圈\n【中譯】老師在黑板上畫了一個大圓圈，說：「這是太陽。」", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 105, "question": "Amy wore a long red ______ to her sister's wedding.", "options": ["zip", "pin", "dress", "watch"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) dress\n【單字】dress (n.)：洋裝\n【中譯】艾咪穿了一件紅色長洋裝去參加她姊姊的婚禮。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 106, "question": "December is the ______ month of the year.", "options": ["first", "second", "last", "third"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) last\n【單字】last (adj.)：最後的\n【中譯】十二月是一年中的最後一個月。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 107, "question": "Our neighbor is very ______. She often helps old people carry their bags.", "options": ["mad", "kind", "cross", "mean"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) kind\n【單字】kind (adj.)：仁慈的\n【中譯】我們的鄰居非常仁慈，她常常幫老人家提袋子。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 108, "question": "There may be a ______ this afternoon, so take an umbrella with you.", "options": ["toast", "sale", "smile", "shower"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) shower\n【單字】shower (n.)：陣雨\n【中譯】今天下午可能會有陣雨，所以帶把傘在身上。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 109, "question": "The train went ______ a long tunnel under the mountain.", "options": ["through", "until", "since", "of"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) through\n【單字】through (prep.)：穿越\n【中譯】火車穿越了山底下一條長長的隧道。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 110, "question": "I'll mix red and blue paint to make ______ paint.", "options": ["green", "yellow", "purple", "orange"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) purple\n【單字】purple (adj.)：紫色的\n【中譯】我要把紅色和藍色的顏料混在一起，調出紫色的顏料。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 111, "question": "Don't let the little boy stay ______ at home. He is only five.", "options": ["giant", "present", "key", "alone"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) alone\n【單字】alone (adj.)：獨自的；單獨的\n【中譯】不要讓那個小男孩獨自待在家，他才五歲。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 112, "question": "The workers will ______ next week if they don't get more money.", "options": ["row", "bow", "surf", "strike"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) strike\n【單字】strike (v.)：（v.）罷工\n【中譯】如果工人們沒有拿到更多錢，他們下週就會罷工。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 113, "question": "We finished dinner, and Dad asked the waiter for the ______.", "options": ["rock", "cover", "check", "match"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) check\n【單字】check (n.)：帳單；買單\n【中譯】我們吃完晚餐，爸爸請服務生拿帳單來（買單）。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 114, "question": "With one ______ of the mouse, you can buy the shoes online.", "options": ["beat", "click", "cry", "drop"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) click\n【單字】click (n.)：點擊聲；點擊動作\n【中譯】只要點擊一下滑鼠，你就可以在網路上買到這雙鞋。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 115, "question": "Our cat eats too much and sleeps all day. Now he's very ______.", "options": ["magic", "fat", "blank", "early"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) fat\n【單字】fat (adj.)：胖的\n【中譯】我們的貓吃太多又整天睡覺，現在牠非常胖。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 116, "question": "The sky is ______ today. There isn't a cloud in it.", "options": ["late", "mean", "cross", "clear"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) clear\n【單字】clear (adj.)：晴朗的\n【中譯】今天天空很晴朗，一朵雲都沒有。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 117, "question": "The ______ of this cup is broken, so it's hard to hold.", "options": ["nose", "bill", "handle", "pound"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) handle\n【單字】handle (n.)：把手\n【中譯】這個杯子的把手壞了，所以很難拿。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 118, "question": "My ______ job is to be a pilot. I've wanted it since I was little.", "options": ["dream", "cross", "blank", "giant"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) dream\n【單字】dream (adj.)：理想的、夢想的\n【中譯】我的夢想工作是當飛行員，我從小就想當。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 119, "question": "On a sunny day, the sky is ______ and the clouds are white.", "options": ["brown", "black", "red", "blue"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) blue\n【單字】blue (adj.)：藍色的\n【中譯】在晴朗的日子裡，天空是藍色的，雲是白色的。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 120, "question": "The road is ______, so it's easy to ride a bike on it.", "options": ["mean", "even", "far", "late"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) even\n【單字】even (adj.)：平的；平均的\n【中譯】這條路很平，所以在上面騎腳踏車很容易。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 121, "question": "This cup is dirty. Please give me ______ cup.", "options": ["most", "another", "both", "many"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) another\n【單字】another (adj.)：另一（個）的\n【中譯】這個杯子髒了，請給我另一個杯子。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 122, "question": "I can't sleep because of the summer ______. Please turn on the fan.", "options": ["rock", "snow", "toast", "heat"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) heat\n【單字】heat (n.)：熱\n【中譯】因為夏天的炎熱我睡不著，請打開電風扇。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 123, "question": "Our school team needs one more ______ for the soccer game tomorrow.", "options": ["player", "patient", "host", "honey"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) player\n【單字】player (n.)：運動員\n【中譯】我們校隊明天的足球比賽還需要一名球員。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 124, "question": "My uncle is a ______ at a famous restaurant. His fried rice is the best.", "options": ["player", "model", "cook", "guide"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) cook\n【單字】cook (n.)：廚師\n【中譯】我叔叔是一家有名餐廳的廚師，他的炒飯是最好吃的。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 125, "question": "In cartoons, pigs are usually ______.", "options": ["black", "pink", "blue", "green"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) pink\n【單字】pink (adj.)：粉紅色的\n【中譯】在卡通裡，豬通常是粉紅色的。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 126, "question": "Dad bought me a ______ of colored pencils. There are 24 different colors in it.", "options": ["set", "drop", "yard", "quarter"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) set\n【單字】set (n.)：套；副\n【中譯】爸爸買了一套色鉛筆給我，裡面有24種不同的顏色。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 127, "question": "The temperature will ______ to 35°C this afternoon. It'll be very hot.", "options": ["fail", "rise", "hunt", "cheat"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) rise\n【單字】rise (v.)：提高\n【中譯】今天下午氣溫會提高到攝氏35度，會非常熱。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 128, "question": "I'm not ______ today. I have a headache, so I can't go to school.", "options": ["fat", "magic", "mean", "well"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) well\n【單字】well (adj.)：身體健康的\n【中譯】我今天身體不舒服（不健康），我頭痛，所以不能去上學。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 129, "question": "I have a math test ______, so I need to study tonight.", "options": ["far", "fast", "tomorrow", "yesterday"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) tomorrow\n【單字】tomorrow (adv.)：明天\n【中譯】我明天有數學考試，所以今晚需要讀書。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 130, "question": "You can take ______ book you like from this shelf.", "options": ["any", "both", "half", "many"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) any\n【單字】any (adj.)：任何的\n【中譯】你可以從這個書架上拿任何一本你喜歡的書。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 131, "question": "Tom sits in the first ______ in class, right in front of the teacher.", "options": ["model", "row", "pot", "grade"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) row\n【單字】row (n.)：排；列\n【中譯】湯姆在班上坐第一排，就在老師正前方。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 132, "question": "Dad's black ______ has a jacket and pants. He wears it with a tie to work every day.", "options": ["dress", "seal", "suit", "lead"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) suit\n【單字】suit (n.)：西裝\n【中譯】爸爸的黑色西裝有外套和褲子，他每天搭配領帶穿去上班。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 133, "question": "Visiting Japan was a great ______. I learned a lot there.", "options": ["bill", "experience", "cut", "mop"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) experience\n【單字】experience (n.)：經驗\n【中譯】去日本玩是很棒的經驗，我在那裡學到很多。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 134, "question": "This candy has a strange ______. It's both sweet and salty.", "options": ["fear", "cry", "taste", "shock"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) taste\n【單字】taste (n.)：味道\n【中譯】這顆糖果有種奇怪的味道，又甜又鹹。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 135, "question": "The sunset over the sea was a beautiful ______.", "options": ["trick", "sight", "rule", "sentence"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) sight\n【單字】sight (n.)：景象\n【中譯】海上的夕陽是一幅美麗的景象。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 136, "question": "Chocolate ice cream is ______, and vanilla ice cream is white.", "options": ["brown", "purple", "green", "blue"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) brown\n【單字】brown (adj.)：棕色的\n【中譯】巧克力冰淇淋是棕色的，香草冰淇淋是白色的。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 137, "question": "When you mix black and white paint, you get ______ paint.", "options": ["yellow", "red", "gray", "orange"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) gray\n【單字】gray (adj.)：灰色的\n【中譯】當你把黑色和白色的顏料混在一起，你會得到灰色的顏料。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 138, "question": "The ______ on the school gate says, \"No dogs in the school.\"", "options": ["dream", "plant", "notice", "smile"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) notice\n【單字】notice (n.)：告示\n【中譯】校門上的告示寫著：「學校內禁止帶狗。」", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 139, "question": "Grandma always has a big ______ on her face when she sees us.", "options": ["smile", "cut", "mop", "rock"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) smile\n【單字】smile (n.)：微笑\n【中譯】奶奶看到我們時，臉上總是帶著大大的微笑。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 140, "question": "I read a good ______ of the movie online, so I want to see it.", "options": ["dip", "review", "wish", "shock"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) review\n【單字】review (n.)：評論；回顧\n【中譯】我在網路上讀到這部電影的好評，所以我想去看。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 141, "question": "Mom used a ______ to put the flower on her dress.", "options": ["key", "pin", "bill", "mop"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) pin\n【單字】pin (n.)：別針\n【中譯】媽媽用一根別針把花別在她的洋裝上。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 142, "question": "After the cold winter, flowers come out in ______.", "options": ["block", "spring", "fall", "class"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) spring\n【單字】spring (n.)：春天\n【中譯】寒冷的冬天過後，花朵在春天開放。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 143, "question": "The ______ in our class often hits smaller kids and takes their lunch money.", "options": ["bully", "cook", "guide", "patient"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) bully\n【單字】bully (n.)：惡霸；霸凌者\n【中譯】我們班上的那個惡霸常常打比較小的孩子，還拿走他們的午餐錢。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 144, "question": "Amy drew a ______ of her cat with colored pencils.", "options": ["wish", "excuse", "bet", "picture"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) picture\n【單字】picture (n.)：圖畫\n【中譯】艾咪用色鉛筆畫了一幅她的貓的圖畫。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 145, "question": "The boy threw a ______ into the river, and it went down to the bottom.", "options": ["type", "smile", "mind", "rock"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) rock\n【單字】rock (n.)：石塊；岩石\n【中譯】那個男孩把一顆石頭丟進河裡，它沉到了河底。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 146, "question": "Mom was very ______ because I broke her favorite cup again.", "options": ["open", "cross", "correct", "far"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) cross\n【單字】cross (adj.)：生氣的\n【中譯】媽媽很生氣，因為我又打破了她最喜歡的杯子。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 147, "question": "Do you ______ the answer to this question?", "options": ["dip", "smoke", "mop", "know"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) know\n【單字】know (v.)：知道\n【中譯】你知道這個問題的答案嗎？", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 148, "question": "Don't be a ______! You can't put your hand into the fire!", "options": ["pin", "copy", "plant", "fool"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) fool\n【單字】fool (n.)：傻瓜\n【中譯】別當傻瓜！你不能把手伸進火裡！", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 149, "question": "Please wait here ______ your mom comes to get you.", "options": ["after", "until", "or", "since"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) until\n【單字】until (conj.)：直到\n【中譯】請在這裡等，直到你媽媽來接你。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 150, "question": "Dad cleaned the wet floor with a ______.", "options": ["mop", "bill", "pin", "dip"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) mop\n【單字】mop (n.)：拖把\n【中譯】爸爸用拖把把濕的地板清乾淨。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 151, "question": "The new library is ______ from 9 a.m. to 8 p.m. every day.", "options": ["cross", "brown", "correct", "open"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) open\n【單字】open (adj.)：開放的\n【中譯】新的圖書館每天早上九點到晚上八點開放。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 152, "question": "Jack has lived in Taipei ______ he was five years old.", "options": ["since", "before", "until", "or"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) since\n【單字】since (conj.)：自從…以來\n【中譯】傑克從五歲起就一直住在台北。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 153, "question": "There are ______ thirty students in my class, maybe twenty-nine or thirty-one.", "options": ["still", "about", "just", "over"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) about\n【單字】about (adv.)：大約\n【中譯】我們班上大約有三十個學生，可能是二十九或三十一個。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 154, "question": "Our team played badly, so we ______ the game 2 to 5.", "options": ["lost", "mopped", "crossed", "planted"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) lost\n【單字】lose (v.)：輸\n【中譯】我們隊打得很差，所以我們以二比五輸了比賽。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 155, "question": "Sleep is ______ to good health. You can't be healthy without it.", "options": ["cross", "key", "far", "brown"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) key\n【單字】key (adj.)：關鍵的\n【中譯】睡眠是健康的關鍵。沒有它你就無法健康。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 156, "question": "I made a ______ with Tom: if I lose the race, I will buy him lunch.", "options": ["bet", "rock", "pin", "dip"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) bet\n【單字】bet (n.)：打賭；賭注\n【中譯】我和湯姆打了個賭：如果我賽跑輸了，我就請他吃午餐。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 157, "question": "After dinner, Dad asked the waiter for the ______ and paid for the meal.", "options": ["rock", "block", "bill", "race"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) bill\n【單字】bill (n.)：帳單\n【中譯】晚餐後，爸爸向服務生要帳單並付了餐費。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 158, "question": "Reading books is good for your ______; it helps you think better.", "options": ["bill", "mind", "stop", "rock"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) mind\n【單字】mind (n.)：心智\n【中譯】讀書對你的心智有益；它幫助你思考得更好。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 159, "question": "Close your eyes and make a ______ before you blow out the candles.", "options": ["pipe", "mop", "wish", "block"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) wish\n【單字】wish (n.)：願望\n【中譯】在你吹熄蠟燭之前，閉上眼睛許個願望。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 160, "question": "I have two brothers, and ______ brothers are taller than me.", "options": ["all", "most", "both", "many"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) both\n【單字】both (adj.)：兩者的\n【中譯】我有兩個哥哥，兩個哥哥都比我高。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 161, "question": "The news of the big earthquake was a ______ to everyone.", "options": ["shock", "plant", "type", "pin"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) shock\n【單字】shock (n.)：震驚；驚訝\n【中譯】大地震的消息讓每個人都很震驚。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 162, "question": "There is black ______ coming out of the kitchen. Is something burning?", "options": ["rain", "smoke", "salt", "rock"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) smoke\n【單字】smoke (n.)：煙\n【中譯】有黑煙從廚房冒出來。是有東西燒焦了嗎？", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 163, "question": "I waited for the bus for ______ an hour. That's thirty minutes!", "options": ["about", "half", "just", "over"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) half\n【單字】half (adj.)：一半的\n【中譯】我等公車等了半小時。那可是三十分鐘！", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 164, "question": "Get off the bus at the next ______; the museum is right there.", "options": ["bet", "mind", "stop", "mop"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) stop\n【單字】stop (n.)：車站\n【中譯】在下一站下公車；博物館就在那裡。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 165, "question": "Tina ran very fast and won the 100-meter ______.", "options": ["pipe", "dip", "bill", "race"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) race\n【單字】race (n.)：競賽\n【中譯】蒂娜跑得非常快，贏得了一百公尺賽跑比賽。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 166, "question": "The station is too ______ to walk to. Let's take a bus.", "options": ["correct", "far", "key", "brown"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) far\n【單字】far (adj.)：遠的\n【中譯】車站太遠了，走不到。我們搭公車吧。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 167, "question": "There isn't a ______ of water in the bottle. It's empty.", "options": ["bet", "pin", "drop", "block"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) drop\n【單字】drop (n.)：滴\n【中譯】瓶子裡一滴水也沒有。它是空的。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 168, "question": "What ______ of music do you like? I like pop music.", "options": ["wish", "bill", "type", "stop"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) type\n【單字】type (n.)：類型\n【中譯】你喜歡哪一種類型的音樂？我喜歡流行音樂。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 169, "question": "The teacher made thirty ______ of the test, one for each student.", "options": ["races", "rocks", "wishes", "copies"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) copies\n【單字】copy (n.)：拷貝；副本\n【中譯】老師把考卷印了三十份，每個學生一份。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 170, "question": "Your answer is ______. You get ten points!", "options": ["correct", "gray", "cross", "far"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) correct\n【單字】correct (adj.)：正確的\n【中譯】你的答案是正確的。你得到十分！", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 171, "question": "Jeremy is the ______ player on our basketball team; he gets the most points in every game.", "options": ["cross", "gray", "open", "star"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) star\n【單字】star (adj.)：傑出的；明星級的\n【中譯】傑瑞米是我們籃球隊的明星球員；他每場比賽都得最多分。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 172, "question": "Don't forget to water the ______ by the window, or they will die.", "options": ["bills", "rocks", "plants", "pins"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) plants\n【單字】plant (n.)：植物\n【中譯】別忘了給窗邊的植物澆水，不然它們會死掉。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 173, "question": "The bookstore is two ______ away from my house, so I can walk there in five minutes.", "options": ["minds", "blocks", "drops", "wishes"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) blocks\n【單字】block (n.)：街區\n【中譯】書店離我家兩個街區遠，所以我五分鐘就能走到那裡。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 174, "question": "Ben didn't do his homework, and his ______ was \"My dog ate it.\"", "options": ["stop", "mop", "bill", "excuse"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) excuse\n【單字】excuse (n.)：藉口\n【中譯】班沒有寫作業，而他的藉口是「我的狗把它吃掉了。」", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 175, "question": "Mr. Lee is always kind ______ his students.", "options": ["through", "until", "to", "since"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) to\n【單字】to (prep.)：對\n【中譯】李老師對他的學生總是很親切。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 176, "question": "Please stand ______ and don't move while I take your picture.", "options": ["key", "brown", "cross", "still"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) still\n【單字】still (adj.)：靜止的\n【中譯】我幫你拍照時，請站著別動。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 177, "question": "My aunt exercises every day, so she has a nice ______.", "options": ["drop", "bill", "notice", "figure"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) figure\n【單字】figure (n.)：（n.）身材\n【中譯】我阿姨每天運動，所以她身材很好。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 178, "question": "Grandpa likes to smoke a ______ after dinner.", "options": ["pipe", "pin", "mop", "rock"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) pipe\n【單字】pipe (n.)：菸斗\n【中譯】爺爺喜歡在晚餐後抽菸斗。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 179, "question": "In Taiwan, children start elementary school at the ______ of six.", "options": ["age", "stop", "block", "bill"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) age\n【單字】age (n.)：年齡\n【中譯】在台灣，孩子在六歲的年齡開始上小學。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 180, "question": "We ate the chips with a cheese ______.", "options": ["dip", "rock", "pin", "mop"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) dip\n【單字】dip (n.)：沾醬\n【中譯】我們用起司沾醬配洋芋片吃。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 181, "question": "Mom washed my white shirt, so it is ______ now.", "options": ["clean", "patient", "early", "slow"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) clean\n【單字】clean (adj.)：乾淨的\n【中譯】媽媽洗了我的白襯衫，所以它現在是乾淨的。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 182, "question": "We watched a magic ______ at the night market last night.", "options": ["nail", "show", "bill", "pipe"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) show\n【單字】show (n.)：表演\n【中譯】我們昨晚在夜市看了一場魔術表演。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 183, "question": "My brother and I don't share a bedroom; I have my ______ room.", "options": ["patient", "born", "mean", "own"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) own\n【單字】own (adj.)：自己的\n【中譯】我和哥哥沒有共用臥室；我有自己的房間。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 184, "question": "Tom has a great ______ in baseball, and he watches every game on TV.", "options": ["block", "seal", "excuse", "interest"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) interest\n【單字】interest (n.)：興趣\n【中譯】湯姆對棒球很有興趣，他在電視上看每一場比賽。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 185, "question": "My sister is wearing a suit because she has a job ______ this afternoon.", "options": ["comb", "interview", "yard", "bat"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) interview\n【單字】interview (n.)：面試\n【中譯】我姊姊穿著西裝，因為她今天下午有一場工作面試。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 186, "question": "Dad gave Mom a red ______, and she put the flower in water.", "options": ["pipe", "mop", "rose", "bat"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) rose\n【單字】rose (n.)：玫瑰\n【中譯】爸爸送給媽媽一朵紅玫瑰，她把這朵花插在水裡。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 187, "question": "Mary wears a gold ______ on her finger.", "options": ["toast", "fan", "seal", "ring"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) ring\n【單字】ring (n.)：戒指\n【中譯】瑪莉的手指上戴著一枚金戒指。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 188, "question": "We have an English ______ every Monday morning.", "options": ["stop", "class", "sight", "bill"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) class\n【單字】class (n.)：課\n【中譯】我們每週一早上有一堂英文課。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 189, "question": "The tour ______ showed us around the old town.", "options": ["bully", "guide", "patient", "fool"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) guide\n【單字】guide (n.)：導遊；指引\n【中譯】導遊帶我們參觀了老城區。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 190, "question": "The girl ______ long hair is my cousin.", "options": ["for", "until", "to", "with"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) with\n【單字】with (prep.)：有…\n【中譯】那個有長頭髮的女孩是我的表妹。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 191, "question": "Amy studied hard and got a good ______ on her math test.", "options": ["grade", "nose", "pin", "rock"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) grade\n【單字】grade (n.)：成績\n【中譯】艾咪努力讀書，數學考試得到好成績。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 192, "question": "The ______ of this pencil is very sharp.", "options": ["rule", "sight", "excuse", "point"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) point\n【單字】point (n.)：點\n【中譯】這支鉛筆的尖端（筆尖）很尖。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 193, "question": "My cat loves to eat ______.", "options": ["lead", "rock", "fish", "gas"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) fish\n【單字】fish (n.)：魚；魚肉\n【中譯】我的貓很愛吃魚。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 194, "question": "My father works for a computer ______ in Taipei.", "options": ["kind", "company", "story", "party"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) company\n【單字】company (n.)：公司\n【中譯】我爸爸在台北的一家電腦公司工作。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 195, "question": "This soup is not salty enough, so please add some ______.", "options": ["rain", "salt", "smoke", "gas"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) salt\n【單字】salt (n.)：鹽\n【中譯】這碗湯不夠鹹，所以請加一些鹽。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 196, "question": "March is the ______ month of the year.", "options": ["third", "second", "first", "last"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) third\n【單字】third (adj.)：第三的\n【中譯】三月是一年中的第三個月。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 197, "question": "New York and Los Angeles are two big ______ cities.", "options": ["mean", "American", "patient", "born"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) American\n【單字】American (adj.)：美國的\n【中譯】紐約和洛杉磯是兩座美國大城市。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 198, "question": "______ students in my class like P.E., but a few don't.", "options": ["Both", "Another", "All", "Most"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) Most\n【單字】most (adj.)：大部分的\n【中譯】我們班大部分的學生喜歡體育課，但有少數人不喜歡。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 199, "question": "From the top of Taipei 101, you can enjoy a great ______ of the city.", "options": ["cost", "excuse", "bill", "view"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) view\n【單字】view (n.)：景色；視野\n【中譯】從台北101的頂端，你可以欣賞城市的美麗景色。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 200, "question": "Mom is cooking beef soup in a big ______.", "options": ["bat", "bill", "pot", "fan"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) pot\n【單字】pot (n.)：鍋\n【中譯】媽媽正在用一個大鍋煮牛肉湯。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 201, "question": "I bought a train ______ to Kaohsiung at the station.", "options": ["fear", "ticket", "nose", "smile"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) ticket\n【單字】ticket (n.)：票；券\n【中譯】我在車站買了一張去高雄的火車票。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 202, "question": "It's very ______ today, so put on your coat.", "options": ["smooth", "pretty", "cold", "free"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) cold\n【單字】cold (adj.)：寒冷的\n【中譯】今天很冷，所以穿上你的外套。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 203, "question": "Ben always tells the truth, and he never tells a ______.", "options": ["wish", "bill", "lie", "ring"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) lie\n【單字】lie (n.)：謊話\n【中譯】班總是說實話，他從不說謊。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 204, "question": "Helping the old man cross the street was a kind ______.", "options": ["act", "floor", "bill", "nose"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) act\n【單字】act (n.)：行為\n【中譯】幫助那位老先生過馬路是一個善良的行為。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 205, "question": "It's 6 p.m. now, and the fireworks show will start at 8 ______.", "options": ["down", "far", "yesterday", "tonight"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) tonight\n【單字】tonight (adv.)：今晚\n【中譯】現在是下午六點，煙火秀將在今晚八點開始。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 206, "question": "My hair is messy, so I need a ______.", "options": ["seal", "bat", "bill", "comb"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) comb\n【單字】comb (n.)：梳子\n【中譯】我的頭髮很亂，所以我需要一把梳子。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 207, "question": "Please ______ carefully before you answer the question.", "options": ["swing", "think", "duck", "fish"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) think\n【單字】think (v.)：思考\n【中譯】回答問題之前請仔細思考。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 208, "question": "My little brother has a ______ of dogs, so he never goes near them.", "options": ["fear", "nail", "slice", "ring"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) fear\n【單字】fear (n.)：恐懼；害怕\n【中譯】我弟弟很怕狗，所以他從不靠近牠們。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 209, "question": "What is the best ______ to learn English words?", "options": ["gas", "floor", "way", "fan"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) way\n【單字】way (n.)：方法\n【中譯】學英文單字最好的方法是什麼？", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 210, "question": "Dad is reading in his ______; it has a big desk and many books.", "options": ["block", "case", "study", "yard"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) study\n【單字】study (n.)：書房\n【中譯】爸爸正在他的書房看書；書房裡有一張大書桌和很多書。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 211, "question": "I was sick yesterday, but I feel much better ______.", "options": ["today", "down", "tomorrow", "yesterday"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) today\n【單字】today (adv.)：今天\n【中譯】我昨天生病了，但我今天感覺好多了。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 212, "question": "This train is very ______; it can go 300 kilometers an hour.", "options": ["late", "clean", "fast", "slow"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) fast\n【單字】fast (adj.)：快的\n【中譯】這班火車非常快；它每小時可以行駛三百公里。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 213, "question": "Our school team won the basketball ______ last Saturday.", "options": ["bat", "match", "sale", "dream"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) match\n【單字】match (n.)：比賽\n【中譯】我們學校的球隊上週六贏了籃球比賽。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 214, "question": "Look at your ______ and tell me what time it is.", "options": ["nose", "comb", "watch", "toast"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) watch\n【單字】watch (n.)：錶；手錶\n【中譯】看看你的手錶，告訴我現在幾點。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 215, "question": "For homework, please do the ______ on page 25 of your English book.", "options": ["rings", "exercises", "seals", "matches"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) exercises\n【單字】exercise (n.)：習題\n【中譯】回家作業請做英文課本第25頁的習題。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 216, "question": "Please ______ the classroom clean.", "options": ["fall", "keep", "rise", "lie"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) keep\n【單字】keep (v.)：保持\n【中譯】請保持教室乾淨。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 217, "question": "The students did a beautiful ______ to the music at the school party.", "options": ["lie", "bill", "pot", "dance"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) dance\n【單字】dance (n.)：舞蹈；一支舞\n【中譯】學生們在學校派對上隨著音樂跳了一支優美的舞。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 218, "question": "I haven't finished my homework ______, so I can't go out to play.", "options": ["yet", "far", "just", "even"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) yet\n【單字】yet (adv.)：尚（未）\n【中譯】我還沒寫完功課，所以我不能出去玩。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 219, "question": "Do you have any ______ for this weekend, like going hiking or seeing a movie?", "options": ["plans", "nails", "rocks", "stops"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) plans\n【單字】plan (n.)：計畫\n【中譯】你這個週末有什麼計畫嗎，像是去健行或看電影？", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 220, "question": "The ______ of the trip to Japan is about 30,000 dollars.", "options": ["rule", "smell", "cost", "nose"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) cost\n【單字】cost (n.)：成本；費用\n【中譯】去日本旅行的費用大約三萬元。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 221, "question": "Only Tom came to school by bike; all the ______ students took the bus.", "options": ["other", "another", "each", "both"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) other\n【單字】other (adj.)：其他的\n【中譯】只有湯姆騎腳踏車上學；其他所有的學生都搭公車。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 222, "question": "On April Fools' Day, my brother played a ______ on me.", "options": ["fan", "wish", "bill", "trick"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) trick\n【單字】trick (n.)：惡作劇\n【中譯】在愚人節那天，我哥哥對我惡作劇。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 223, "question": "My favorite TV ______ is on at eight o'clock every Friday.", "options": ["comb", "program", "table", "pipe"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) program\n【單字】program (n.)：節目\n【中譯】我最喜歡的電視節目每週五晚上八點播出。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 224, "question": "My uncle ______ a big house with a beautiful garden.", "options": ["swings", "drops", "cuts", "has"], "answer": 3, "answerLabel": "D", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(D) has\n【單字】have (v.)：擁有\n【中譯】我叔叔擁有一棟有漂亮花園的大房子。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 225, "question": "I ate only a small ______ of the cake because I was full.", "options": ["rule", "part", "nose", "fear"], "answer": 1, "answerLabel": "B", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(B) part\n【單字】part (n.)：部分\n【中譯】因為我吃飽了，所以我只吃了蛋糕的一小部分。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 226, "question": "The phone rang ______ I was taking a shower.", "options": ["as", "so", "until", "or"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) as\n【單字】as (conj.)：當⋯時\n【中譯】當我在淋浴時，電話響了。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 227, "question": "The book was 80 dollars. I paid with 100 dollars, so the clerk gave me 20 dollars in ______.", "options": ["interest", "tip", "change", "cost"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) change\n【單字】change (n.)：零錢\n【中譯】這本書八十元。我付了一百元，所以店員找我二十元零錢。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 228, "question": "I'm thirsty. Can I have a cold ______, please?", "options": ["drink", "ticket", "watch", "comb"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) drink\n【單字】drink (n.)：飲料\n【中譯】我口渴了。請給我一杯冷飲好嗎？", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 229, "question": "My father works very hard, so his boss gave him a ______ this year. Now he makes more money.", "options": ["raise", "break", "lesson", "bill"], "answer": 0, "answerLabel": "A", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(A) raise\n【單字】raise (n.)：加薪\n【中譯】我爸爸工作很努力，所以他的老闆今年幫他加薪。現在他賺更多錢了。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 230, "question": "The waves are big today, so my brother is going to ______ at the beach.", "options": ["cheat", "mop", "surf", "type"], "answer": 2, "answerLabel": "C", "source": "一字多義 Polysemy｜一字多義 Polysemy", "explanation": "【答案】(C) surf\n【單字】surf (v.)：衝浪\n【中譯】今天浪很大，所以我哥哥要去海邊衝浪。", "explanationSource": "supplemental", "section": "一字多義 Polysemy"}, {"id": 231, "question": "Don't be sad, Tom. ______! You can win the game next time.", "options": ["Cheer up", "Get the flu", "Call back", "Line up"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) Cheer up\n【用語】cheer up (+ 人) (v.phr.)：振作；使……振作\n【中譯】別難過，Tom。振作起來！你下次可以贏得比賽。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 232, "question": "Please move your big box. It ______, and I can't get to my desk.", "options": ["gets in my way", "places an order", "sets a record", "kicks off"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) gets in my way\n【用語】get in one's way (v.phr.)：妨礙（某人）\n【中譯】請移開你的大箱子。它擋到我的路，我走不到我的書桌。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 233, "question": "People who hurt animals really ______.", "options": ["agree on it", "keep in shape", "make me sick", "love me deeply"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) make me sick\n【用語】make + 人 + sick (v.phr.)：讓人作噁；令人反感\n【中譯】傷害動物的人真的讓我很反感。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 234, "question": "Ben didn't steal the watch. Someone put it in his bag to ______.", "options": ["call him back", "show him around", "set him up", "pull out a tooth"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) set him up\n【用語】set up + 人 (v.phr.)：陷害\n【中譯】Ben沒有偷那支手錶。有人把它放進他的包包裡來陷害他。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 235, "question": "In 2015, Mr. Wang ______. It started with only three workers, and now it has 200.", "options": ["minded his manners", "set up a company", "arrived in Taipei", "took a nap"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) set up a company\n【用語】set up + N (v.phr.)：建立、設立\n【中譯】王先生在2015年成立了一家公司。它一開始只有三名員工，現在有200名。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 236, "question": "Tim said he was sick, so he could ______ cleaning his room.", "options": ["go on", "take up", "get out of", "keep"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) get out of\n【用語】get out of + V-ing (v.phr.)：逃避（做某事）\n【中譯】Tim說他生病了，這樣他就可以逃避打掃房間。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 237, "question": "It's cold outside. ______ your coat before you go out.", "options": ["Put on", "Take off", "Turn to", "Throw out"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) Put on\n【用語】put on + N (v.phr.)：穿上、戴上\n【中譯】外面很冷。出門前穿上你的外套。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 238, "question": "My dad needs to send an email, so he wants to ______ for a few minutes.", "options": ["elbow his way to the door", "use the computer", "pay a heavy price", "take a shower"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) use the computer\n【用語】use the computer (v.phr.)：用電腦\n【中譯】我爸爸需要寄一封電子郵件，所以他想用一下電腦幾分鐘。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 239, "question": "This math problem was really hard, but after an hour Amy finally ______.", "options": ["worked it out", "went sightseeing", "took our order", "made a cake"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) worked it out\n【用語】work out + N (v.phr.)：解決、想出（辦法）\n【中譯】這道數學題真的很難，但一小時後Amy終於把它解出來了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 240, "question": "We have a long holiday next week, so my family will ______ to Japan.", "options": ["take it out", "string me along", "make a wish", "take a trip"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) take a trip\n【用語】take a trip (v.phr.)：去旅行\n【中譯】我們下週有長假，所以我的家人會去日本旅行。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 241, "question": "Ben has a big cake. He wants to ______ with his classmates.", "options": ["fly a plane", "share it", "make a promise", "turn left"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) share it\n【用語】share + N + with + 人 (v.phr.)：與……分享\n【中譯】Ben有一個大蛋糕。他想和同學們分享。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 242, "question": "The boy fell into the river and began to ______.", "options": ["take notes", "come around", "cry for help", "get off the bus"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) cry for help\n【用語】cry for help (v.phr.)：呼救；求救\n【中譯】那個男孩掉進河裡，開始大聲呼救。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 243, "question": "The dog ran fast and ______ to get out of the yard.", "options": ["took a photo", "made cookies", "jumped over the wall", "put together a puzzle"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) jumped over the wall\n【用語】jump over + N (v.phr.)：跳過\n【中譯】那隻狗跑得很快，跳過牆逃出了院子。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 244, "question": "In Japan, students stand up and ______ the teacher at the start of every class.", "options": ["run after", "bow to", "look up", "talk about"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) bow to\n【用語】bow to + 人 (v.phr.)：對……鞠躬\n【中譯】在日本，每堂課開始時學生都會站起來向老師鞠躬。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 245, "question": "There is a problem with our class trip, and the teacher is trying to ______ now.", "options": ["make up her face", "make it a habit", "deal with it", "show it off"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) deal with it\n【用語】deal with + N (v.phr.)：處理（問題）\n【中譯】我們的校外教學出了一個問題，老師現在正試著處理它。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 246, "question": "Mr. Lee's family is poor. They don't have much money, but they can still ______.", "options": ["set the clock", "change the view of it", "get by", "turn left"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) get by\n【用語】get by (v.phr.)：勉強過活，湊合\n【中譯】李先生家很窮。他們沒有很多錢，但仍然可以勉強過活。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 247, "question": "When Lily heard the sad news, she ______.", "options": ["burst into tears", "made a wish", "helped herself to the cake", "brushed her teeth"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) burst into tears\n【用語】burst into + N (v.phr.)：突然……（大哭、大笑）\n【中譯】Lily聽到這個悲傷的消息時，突然大哭起來。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 248, "question": "Tom played games in class, so the teacher ______.", "options": ["messed around", "ran through the park", "gave away his phone", "took away his phone"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) took away his phone\n【用語】take away + N (v.phr.)：拿走\n【中譯】Tom在課堂上玩遊戲，所以老師把他的手機拿走了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 249, "question": "After I read this book about sharks, I ______. Now I think they are cute, not scary.", "options": ["did my best", "put up with them", "changed my view of them", "jumped over them"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) changed my view of them\n【用語】change one's view of + N (v.phr.)：改變對……的看法\n【中譯】讀了這本關於鯊魚的書之後，我改變了對牠們的看法。現在我覺得牠們很可愛，不可怕。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 250, "question": "Mr. Lin is kind and funny. Many students ______ the best teacher in our school.", "options": ["ask him to be", "get him to be", "tell him to be", "consider him to be"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) consider him to be\n【用語】consider + N + to be + adj./N (v.phr.)：認為…是…\n【中譯】林老師親切又風趣。許多學生認為他是我們學校最好的老師。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 251, "question": "This soup has no meat in it, but it ______.", "options": ["lets go of the spoon", "makes ends meet", "turns right", "tastes like chicken"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) tastes like chicken\n【用語】taste like + N (v.phr.)：嘗起來像⋯⋯\n【中譯】這碗湯裡沒有肉，但它嘗起來像雞肉。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 252, "question": "Some money in the office is missing. The police will ______ it to find out who took it.", "options": ["pay a visit to", "look into", "laugh at", "go ahead with"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) look into\n【用語】look into + N (v.phr.)：調查\n【中譯】辦公室裡有一些錢不見了。警方會調查這件事，查出是誰拿走的。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 253, "question": "Sadly, many fish in the river ______.", "options": ["had a sale", "lived on", "played a game", "died from the dirty water"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) died from the dirty water\n【用語】die from + N (v.phr.)：死於（外因、受傷、意外）\n【中譯】令人難過的是，河裡很多魚因為髒水而死。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 254, "question": "My uncle is a pilot. His job is to ______.", "options": ["make tea", "spend money on clothes", "fly a plane", "kick off the game"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) fly a plane\n【用語】fly a plane (v.phr.)：開飛機\n【中譯】我叔叔是飛行員。他的工作是開飛機。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 255, "question": "Mia was very sad when her dog died. It took her a year to ______.", "options": ["give it back", "make a phone call", "fall asleep", "get over it"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) get over it\n【用語】get over + N (v.phr.)：忘懷、走出（傷痛、陰影）\n【中譯】Mia的狗死掉時她非常難過。她花了一年才走出傷痛。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 256, "question": "We ______, so Mom went to the store to buy some.", "options": ["dealt with the boy", "ran out of milk", "kept pets", "found it easy to cook"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) ran out of milk\n【用語】run out of + N (v.phr.)：用光；缺乏\n【中譯】我們的牛奶用光了，所以媽媽去商店買一些。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 257, "question": "Mrs. Wu ______ last night, so Mom made tea for her.", "options": ["got to sleep early", "came around", "invited me to the zoo", "had interest in cooking"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) came around\n【用語】come around (v.phr.)：拜訪\n【中譯】吳太太昨晚來拜訪，所以媽媽為她泡了茶。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 258, "question": "Mom, my friend Jack wants to ______ and play video games after school. Is that OK?", "options": ["get out of our house", "overlook our house", "come over to our house", "move away from our house"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) come over to our house\n【用語】come over (v.phr.)：過來\n【中譯】媽，我朋友Jack放學後想到我們家來打電動。可以嗎？", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 259, "question": "The other kids ______ because Ben's shoes were old and dirty, and he felt very sad.", "options": ["laughed at him", "took turns playing", "cheered for him", "cut him short"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) laughed at him\n【用語】laugh at + 人 (v.phr.)：嘲笑\n【中譯】其他孩子因為Ben的鞋子又舊又髒而嘲笑他，他覺得很難過。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 260, "question": "Grandpa is never in a hurry. At breakfast, he always ______.", "options": ["runs out of time", "takes his time over his food", "tends to eat very fast", "gets out of the car"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) takes his time over his food\n【用語】take one's time over + N (v.phr.)：從容地做…\n【中譯】爺爺從不匆忙。吃早餐時，他總是從容地慢慢吃。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 261, "question": "Grandma boiled some water to ______ for her guests.", "options": ["make tea", "take a long time", "lie down", "walk up the stairs"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) make tea\n【用語】make tea (v.phr.)：泡茶\n【中譯】奶奶燒了一些水，要為客人泡茶。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 262, "question": "The light is green now. We can ______ safely.", "options": ["walk across the street", "get it even", "give it back", "stay in bed"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) walk across the street\n【用語】walk across the street (v.phr.)：走過馬路\n【中譯】現在是綠燈了。我們可以安全地走過馬路。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 263, "question": "You failed the test because you didn't study. You need to ______.", "options": ["face the truth", "wipe it out", "tell a lie", "make trouble"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) face the truth\n【用語】face the truth (v.phr.)：面對真相\n【中譯】你考試不及格是因為你沒讀書。你必須面對真相。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 264, "question": "Last night, a thief ______ and stole our TV.", "options": ["left the door locked", "turned down my offer", "kept pets", "broke in"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) broke in\n【用語】break in (v.phr.)：闖入、強行進入\n【中譯】昨晚有個小偷闖進來，偷走了我們的電視。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 265, "question": "Amy and I both love music and dogs. We ______.", "options": ["set aside some money", "win the bet", "have many things in common", "stay calm"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) have many things in common\n【用語】have + N + in common (v.phr.)：有……共同點\n【中譯】Amy和我都喜歡音樂和狗。我們有很多共同點。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 266, "question": "Ben played in the snow without a coat, so he ______ and stayed in bed for three days.", "options": ["showed off his new coat", "used to be strong", "looked like a snowman", "ended up sick"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) ended up sick\n【用語】end up + adj. (v.phr.)：最終變得……\n【中譯】Ben沒穿外套在雪地裡玩，所以他最後生病了，在床上躺了三天。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 267, "question": "When I ______, I saw a bird in the tree.", "options": ["couldn't help but laugh", "cut it out", "looked up", "held on"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) looked up\n【用語】look up (v.phr.)：仰視、抬頭\n【中譯】當我抬起頭時，看到樹上有一隻鳥。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 268, "question": "Taipei has the MRT, so it's easy to ______.", "options": ["get around the city", "take the picture down", "have a cold", "put the book aside"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) get around the city\n【用語】get around + 地方 (v.phr.)：四處走動；到處旅行\n【中譯】台北有捷運，所以在城市裡四處走動很容易。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 269, "question": "A: The answer is B because \"yesterday\" means the past.\nB: Oh, I ______ now. Thank you!", "options": ["get it", "lose my way", "take a break", "see it as a game"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) get it\n【用語】get it (v.phr.)：懂了；理解了\n【中譯】A：答案是B，因為「yesterday」表示過去。B：喔，我現在懂了。謝謝你！", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 270, "question": "Jack works at a restaurant on weekends to ______.", "options": ["earn money", "make a guess", "have the upper hand", "have a hard time"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) earn money\n【用語】earn money (v.phr.)：賺錢\n【中譯】Jack週末在一家餐廳工作來賺錢。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 271, "question": "There is a lot of trash in the river, but the city ______. The river is still dirty.", "options": ["got out of my way", "took off", "did nothing about it", "kept in touch"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) did nothing about it\n【用語】do nothing about + N (v.phr.)：對…無作為；什麼也不做\n【中譯】河裡有很多垃圾，但市政府對此什麼也沒做。這條河還是很髒。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 272, "question": "Drinking a cup of coffee in the morning can ______.", "options": ["go out", "kick-start my day", "put down the cup", "tell a lie"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) kick-start my day\n【用語】kick-start + N (v.phr.)：啟動；加速（比喻用法）\n【中譯】早上喝一杯咖啡可以啟動我的一天。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 273, "question": "The road is bumpy, so the bus driver told the kids to ______.", "options": ["stand up", "jump over the seats", "sit tight", "cut in the line"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) sit tight\n【用語】sit tight (v.phr.)：穩穩坐好\n【中譯】路面很顛簸，所以公車司機叫孩子們穩穩坐好。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 274, "question": "The market is very crowded. You should ______ so you won't get lost.", "options": ["run away from me", "stay close to me", "spend the vacation", "make a mess"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) stay close to me\n【用語】stay close to + 人/物 (v.phr.)：靠近；接近\n【中譯】市場非常擁擠。你應該靠近我，這樣你就不會走丟。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 275, "question": "The news about the new teacher ______ quickly. Soon everyone in school knew.", "options": ["slipped my mind", "died out", "took place", "got around"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) got around\n【用語】get around (v.phr.)：傳開\n【中譯】關於新老師的消息很快就傳開了。很快全校都知道了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 276, "question": "Ben's eyes are not good, so he ______ reading small words in books.", "options": ["has problems", "has fun", "gives me a hand", "does a good job"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) has problems\n【用語】have problems + V-ing (v.phr.)：在…方面有問題\n【中譯】班的眼睛不好，所以他在閱讀書中的小字方面有問題。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 277, "question": "Everyone said 'Great idea!' when Tina ______ for our class party.", "options": ["smelled like a cake", "fell asleep", "paid the bills", "came up with a fun plan"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) came up with a fun plan\n【用語】come up with + N (v.phr.)：想出\n【中譯】當蒂娜為我們的班級派對想出一個好玩的計畫時，大家都說：「好主意！」", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 278, "question": "Tom's teeth got better after he ______ and stopped eating candy.", "options": ["listened to his dentist's advice", "walked past the dentist's office", "consisted of three parts", "stayed up late"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) listened to his dentist's advice\n【用語】listen to one's advice (v.phr.)：聽從某人的建議\n【中譯】湯姆聽從牙醫的建議、不再吃糖果之後，他的牙齒變好了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 279, "question": "Mr. Chen is sick today, so Ms. Lin will ______ and teach our math class.", "options": ["take notes in class", "get on the bus", "do the dishes", "take the place of Mr. Chen"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) take the place of Mr. Chen\n【用語】take the place of + 人/物 (v.phr.)：取代、代理…某人地位\n【中譯】陳老師今天生病，所以林老師會代替陳老師教我們的數學課。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 280, "question": "The plan to clean the beach was hard, but the students ______ in the end, and the beach was clean again.", "options": ["took a break", "reached for the stars", "did the cooking", "carried it through"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) carried it through\n【用語】carry through + N (v.phr.)：完成；貫徹\n【中譯】淨灘計畫很困難，但學生們最後貫徹完成了，海灘又變乾淨了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 281, "question": "Amy missed two weeks of school, so she ______ and had to study hard to catch up with her classmates.", "options": ["made friends", "fell behind", "lost touch with her old friend", "burned down her house"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) fell behind\n【用語】fall behind (v.phr.)：落後\n【中譯】艾咪兩週沒上學，所以她落後了，必須努力讀書才能趕上同學。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 282, "question": "The new park ______ a lot of changes in our town.", "options": ["referred to", "threw away", "brought about", "noted down"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) brought about\n【用語】bring about + N (v.phr.)：引起；導致\n【中譯】新公園為我們鎮上帶來了許多改變。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 283, "question": "You look great today! Your red skirt ______.", "options": ["stops by the store", "goes with your white shirt", "wakes up early", "answers the door"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) goes with your white shirt\n【用語】go with + N (v.phr.)：與……相配\n【中譯】你今天看起來很棒！你的紅裙子和你的白襯衫很相配。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 284, "question": "When Mr. Lee got too old to work, his son ______, so the shop is still open today.", "options": ["fed on the noodles", "did his homework", "took over the noodle shop", "took in the information"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) took over the noodle shop\n【用語】take over + N (v.phr.)：接管\n【中譯】當李先生年紀太大無法工作時，他的兒子接管了麵店，所以這家店今天仍然營業。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 285, "question": "Before you blow out the candles on your birthday cake, close your eyes and ______.", "options": ["take a shortcut", "pay off", "make a wish", "take a shower"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) make a wish\n【用語】make a wish (v.phr.)：許願\n【中譯】在你吹熄生日蛋糕上的蠟燭之前，閉上眼睛許個願。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 286, "question": "Uncle Tom was flying to Japan, so we went to the airport to ______.", "options": ["see him off", "make a plan for dinner", "bring out the best in him", "do the dishes"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) see him off\n【用語】see sb off (v.phr.)：送行\n【中譯】湯姆叔叔要搭飛機去日本，所以我們去機場為他送行。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 287, "question": "The firefighters ran into the burning building to ______.", "options": ["save lives", "take a nap", "save energy", "hand in their homework"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) save lives\n【用語】save lives (v.phr.)：挽救生命\n【中譯】消防員衝進燃燒中的大樓去挽救生命。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 288, "question": "Kevin wants to work at the coffee shop this summer, so he ______ yesterday.", "options": ["set up a tent", "took a bath", "treated the cat gently", "applied for a job there"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) applied for a job there\n【用語】apply for + N (v.phr.)：申請、應徵\n【中譯】凱文今年夏天想在咖啡店工作，所以他昨天去應徵了那裡的工作。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 289, "question": "My dad ______ last year, and now he is much healthier.", "options": ["gave up smoking", "went on smoking", "told me to go to bed", "lost his way"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) gave up smoking\n【用語】give up + N/V-ing (v.phr.)：戒除\n【中譯】我爸爸去年戒了菸，現在他健康多了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 290, "question": "Lisa ran 100 meters faster than any student before and ______ for our school.", "options": ["had a fever", "set the record", "had a good sleep", "missed the train"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) set the record\n【用語】set the record (v.phr.)：創下紀錄\n【中譯】麗莎跑一百公尺比以前任何學生都快，為我們學校創下了紀錄。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 291, "question": "That dog looks angry, so you should ______ and not try to touch it.", "options": ["pick it up", "stay away from it", "come back to play with it", "exercise your right to vote"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) stay away from it\n【用語】stay away from + N/人 (v.phr.)：遠離\n【中譯】那隻狗看起來很生氣，所以你應該遠離牠，不要試著摸牠。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 292, "question": "Grandpa said, 'You can't go back and ______, but you can learn from them.'", "options": ["catch a cold", "make sure the door is closed", "fix past mistakes", "give me a ring"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) fix past mistakes\n【用語】fix past mistakes (v.phr.)：修正過去的錯誤\n【中譯】爺爺說：「你無法回到過去修正過去的錯誤，但你可以從中學習。」", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 293, "question": "I'm always late for school, so I need to ______ and go to bed earlier.", "options": ["make a change", "think of my birthday", "eat out", "play the piano"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) make a change\n【用語】make a change (v.phr.)：做出改變\n【中譯】我上學總是遲到，所以我需要做出改變，早點睡覺。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 294, "question": "After thinking about it for a long time, Mia ______ next year.", "options": ["decided to study in Japan", "came down with a cold", "got in touch with her teacher", "lost weight"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) decided to study in Japan\n【用語】decide to + VR (v.phr.)：決定去做⋯⋯\n【中譯】經過長時間的思考後，米亞決定明年去日本讀書。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 295, "question": "Mom wants to learn to cook Japanese food, so she ______ at a cooking school last summer.", "options": ["took a course", "went ahead", "took a walk", "cheered for her friend"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) took a course\n【用語】take a course (v.phr.)：修課\n【中譯】媽媽想學做日本料理，所以她去年夏天在一所烹飪學校修了一門課。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 296, "question": "Even though some people didn't like the plan, the mayor ______, and the new park opened last month.", "options": ["got up", "pushed it through", "stayed up", "broke up"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) pushed it through\n【用語】push through + N (v.phr.)：推動；強行通過（計畫、法案）\n【中譯】雖然有些人不喜歡這個計畫，市長還是強力推動通過了，新公園上個月開放了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 297, "question": "These flowers ______ a sweet smell in the evening.", "options": ["save up", "make up", "give off", "throw away"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) give off\n【用語】give off + N (v.phr.)：散發出（氣味、光、熱）\n【中譯】這些花在傍晚散發出甜甜的香味。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 298, "question": "Can you buy some milk on your way home? That will ______ to the store.", "options": ["push through", "wake me up", "save me a trip", "set the clock"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) save me a trip\n【用語】save + 人 + a trip (v.phr.)：省去某人跑一趟\n【中譯】你回家的路上可以幫我買些牛奶嗎？那會省得我跑一趟商店。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 299, "question": "I missed Grandma, so I ______ last night and asked how she was.", "options": ["took a shower", "called her up", "used to visit her", "turned in early"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) called her up\n【用語】call up + 人 (v.phr.)：打電話\n【中譯】我很想念奶奶，所以我昨晚打電話給她，問她過得好不好。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 300, "question": "The last bus leaves at nine, so I ______ now, or I'll miss it.", "options": ["have to leave", "appeal to the driver", "eat out", "turn down the volume"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) have to leave\n【用語】have to + VR (v.phr.)：必須\n【中譯】最後一班公車九點開，所以我現在必須離開，不然會錯過它。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 301, "question": "While I was cleaning my room yesterday, I ______ and showed it to my mom.", "options": ["carried on singing", "made noise", "came across an old photo", "kept it simple"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) came across an old photo\n【用語】come across + 物 (v.phr.)：碰巧發現（某物）\n【中譯】我昨天打掃房間時，碰巧發現一張舊照片，並拿給我媽媽看。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 302, "question": "The bus was very slow in the rain, so we didn't ______ until ten o'clock at night.", "options": ["keep healthy", "make friends", "get home", "rule out"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) get home\n【用語】get home/there/here (v.phr.)：回家／到那裡／到這裡\n【中譯】公車在雨中開得很慢，所以我們直到晚上十點才到家。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 303, "question": "When I met my new teacher, I ______ and said, 'Nice to meet you.'", "options": ["laughed at her", "shook hands with her", "gave away her secret", "came out of the trash can"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) shook hands with her\n【用語】shake hands with + 人 (v.phr.)：和…握手\n【中譯】我遇見新老師時，和她握手並說：「很高興認識您。」", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 304, "question": "We had to build our sand castle again because the big waves ______.", "options": ["brushed their hair", "washed it away", "took a walk", "told the boys from the girls"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) washed it away\n【用語】wash away + N (v.phr.)：沖走\n【中譯】我們必須重新堆沙堡，因為大浪把它沖走了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 305, "question": "Jenny's dream ______ when she became a doctor.", "options": ["recorded the sound", "came true", "smiled at her", "grew up"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) came true\n【用語】come true (v.phr.)：實現\n【中譯】珍妮成為醫生時，她的夢想實現了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 306, "question": "It's very hot in here. Please ______ when you go out.", "options": ["take up the pen", "turn on the heater", "leave the window open", "know your way around the city"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) leave the window open\n【用語】leave the window open (v.phr.)：讓窗戶開著\n【中譯】這裡很熱，你出去的時候請讓窗戶開著。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 307, "question": "I lost my keys. Can you help me ______?", "options": ["save money", "throw them away", "make way for the bus", "look for them"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) look for them\n【用語】look for + N (v.phr.)：尋找\n【中譯】我把鑰匙弄丟了，你能幫我找它們嗎？", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 308, "question": "My grandpa can't hear well, so he ______.", "options": ["has fun listening to music", "goes picnicking every day", "has difficulty talking on the phone", "makes believe he is a king"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) has difficulty talking on the phone\n【用語】have difficulty + V-ing (v.phr.)：做某事有困難\n【中譯】我爺爺聽力不好，所以他講電話有困難。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 309, "question": "This movie ______, so my brother, who loves animals, wants to see it.", "options": ["makes a decision to go", "has to do with wild animals", "lives from hand to mouth", "looks after the animals"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) has to do with wild animals\n【用語】have to do with + N (v.phr.)：與……有關\n【中譯】這部電影和野生動物有關，所以我那喜愛動物的弟弟想看。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 310, "question": "The wind was so strong that it ______.", "options": ["put on my coat", "blew my hat away", "tried it my way", "took pictures"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) blew my hat away\n【用語】blow + 物 + away (v.phr.)：吹走\n【中譯】風太強了，把我的帽子吹走了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 311, "question": "The kids played with flour and eggs and ______ in the kitchen, so Mom had to clean it for an hour.", "options": ["took a nap", "looked forward to cooking", "made a mess", "raised pets"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) made a mess\n【用語】make a mess (v.phr.)：弄得一團亂\n【中譯】孩子們玩麵粉和蛋，在廚房裡弄得一團亂，所以媽媽得清理一個小時。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 312, "question": "Amy wants to buy a new bike, so she ______ every week.", "options": ["puts aside some money", "pushes her way through the crowd", "eats out", "goes crazy"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) puts aside some money\n【用語】put aside + N (v.phr.)：保留；儲蓄\n【中譯】艾咪想買一台新腳踏車，所以她每週都存一些錢。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 313, "question": "Lily has the same name as her grandma because her parents ______.", "options": ["took a nap", "named her after her grandma", "lent money to her", "got even with her"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) named her after her grandma\n【用語】name + N + after + N (v.phr.)：以……命名\n【中譯】莉莉和她奶奶同名，因為她的父母以奶奶的名字為她命名。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 314, "question": "A message ______ on my phone screen while I was doing homework.", "options": ["took off", "got along", "hung up", "popped up"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) popped up\n【用語】pop up (v.phr.)：突然發生或出現\n【中譯】我在寫作業時，一則訊息突然出現在我的手機螢幕上。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 315, "question": "Mr. Wang has taken care of me since I was a baby, so I ______ even though he is my uncle.", "options": ["laugh at him", "take the initiative to talk", "go to the park", "view him as my father"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) view him as my father\n【用語】view + N + as + N (v.phr.)：將…視為…\n【中譯】王先生從我還是嬰兒時就照顧我，所以即使他是我的叔叔，我仍將他視為我的父親。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 316, "question": "A: We lost the game again.\nB: Don't be sad. Try to ______; we learned a lot today.", "options": ["stand up against the team", "get out of the car", "look at the bright side", "take a shower"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) look at the bright side\n【用語】look at the bright side (v.phr.)：看光明面；往好處想\n【中譯】A：我們又輸了比賽。\nB：別難過，試著往好處想，我們今天學到了很多。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 317, "question": "Don't worry about the dinner party; I'll ______.", "options": ["see through you", "see to everything", "agree with you", "raise children"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) see to everything\n【用語】see to + N (v.phr.)：辦理、照料、負責處理\n【中譯】別擔心晚宴的事，我會處理好一切。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 318, "question": "My little sister said she was a queen, so I ______ and bowed to her.", "options": ["returned the book", "did homework", "played the music", "played along"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) played along\n【用語】play along (v.phr.)：假裝配合；順著演\n【中譯】我妹妹說她是女王，所以我就順著演，向她鞠躬。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 319, "question": "We went to a farm and ______. Now we have a big bag of apples.", "options": ["picked fruit", "cut down trees", "hurried up", "kept him busy"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) picked fruit\n【用語】pick fruit (v.phr.)：摘水果\n【中譯】我們去了一個農場摘水果。現在我們有一大袋蘋果。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 320, "question": "When the bus stopped, the kids ______ and ran to the park.", "options": ["dropped me a line", "hopped off the bus", "got on the bus", "turned down the heater"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) hopped off the bus\n【用語】hop off + N (v.phr.)：跳下（車等）\n【中譯】公車停下來時，孩子們跳下公車，跑向公園。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 321, "question": "All my cousins ______ at Grandma's house every Chinese New Year to eat and play games.", "options": ["dream of", "fall asleep", "work as", "get together"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) get together\n【用語】get together (v.phr.)：聚在一起\n【中譯】每年農曆新年，我所有的表兄弟姊妹都會在奶奶家聚在一起吃東西、玩遊戲。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 322, "question": "Children need to ______ every day, so they should drink milk and eat fruit.", "options": ["cut the paper", "take in enough vitamins", "make a noise", "keep their desks in order"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) take in enough vitamins\n【用語】take in + N (v.phr.)：攝取（營養、食物等）\n【中譯】孩子們每天需要攝取足夠的維生素，所以他們應該喝牛奶、吃水果。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 323, "question": "The sudden rain ______. None of us had an umbrella with us.", "options": ["won the bet", "lit up the candles", "took us by surprise", "bridged the gap"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) took us by surprise\n【用語】take sb. by surprise (v.phr.)：讓某人吃一驚\n【中譯】這場突如其來的雨讓我們措手不及。我們都沒有帶傘。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 324, "question": "Amy and Ben had a fight yesterday, but they ______ this morning and are good friends again.", "options": ["heard of it", "broke the record", "made up", "carried it through"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) made up\n【用語】make up (with sb.) (v.phr.)：（和某人）和好\n【中譯】Amy和Ben昨天吵了一架，但他們今天早上和好了，又是好朋友了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 325, "question": "Mom is working late tonight, so I have to stay home and ______.", "options": ["get a ticket", "hang up the phone", "look after my little sister", "go whale-watching"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) look after my little sister\n【用語】look after + 人 (v.phr.)：照顧\n【中譯】媽媽今晚要加班，所以我必須待在家照顧我的妹妹。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 326, "question": "Mr. Lin helped Lisa a lot with math, so she wrote him a card to ______.", "options": ["check out his new car", "thank him for his help", "consider him to be lazy", "take a shortcut"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) thank him for his help\n【用語】thank + 人 + for + N/V-ing (v.phr.)：為了某事感謝某人\n【中譯】林老師在數學上幫了Lisa很多，所以她寫了一張卡片給他，感謝他的幫忙。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 327, "question": "Thanks to a kind farmer who ______, we found our way back to the village.", "options": ["smelled sweet", "pointed the way", "caught up with an old friend", "took a nap"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) pointed the way\n【用語】point the way (v.phr.)：指引方向\n【中譯】多虧一位為我們指引方向的好心農夫，我們找到了回村莊的路。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 328, "question": "My big brother is good at math, so he often ______ my math homework, and now I understand math better.", "options": ["returns to", "helps me with", "drops out of", "complains about"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) helps me with\n【用語】help + 人 + with + N (v.phr.)：幫忙（某人做）…\n【中譯】我哥哥數學很好，所以他常常幫我做數學作業，現在我更懂數學了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 329, "question": "A: Can I stay at your house tonight? I hope I won't ______.\nB: Not at all. You're always welcome here!", "options": ["get the whole picture", "keep my word", "put you out", "happen to see you"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) put you out\n【用語】put out + 人 (v.phr.)：給（某人）添麻煩、造成不便\n【中譯】A：我今晚可以住你家嗎？希望不會給你添麻煩。\nB：一點也不會。這裡永遠歡迎你！", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 330, "question": "In this story, the word \"he\" ______.", "options": ["treats the dog as a friend", "picks up a skill", "refers to the old farmer", "takes a nap"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) refers to the old farmer\n【用語】refer to + N (v.phr.)：意指\n【中譯】在這個故事裡，「he」這個字指的是那位老農夫。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 331, "question": "Mary's parents give her everything she asks for, so she always ______.", "options": ["gets in", "gets her own way", "gives in", "passes on the message"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) gets her own way\n【用語】get one's (own) way (v.phr.)：為所欲為、隨心所欲\n【中譯】瑪麗的父母她要什麼就給什麼，所以她總是為所欲為。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 332, "question": "A: Sorry, Tom. I have to ______. My mom needs my help in the kitchen.\nB: OK. Let's talk later.", "options": ["line up", "pull away", "let it go", "cut the conversation short"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) cut the conversation short\n【用語】cut the conversation short (v.phr.)：中斷對話\n【中譯】A：抱歉，Tom。我得中斷我們的對話了，我媽媽需要我在廚房幫忙。\nB：好，我們晚點再聊。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 333, "question": "The taxi is waiting outside, so please ______ quickly before you get wet in the rain.", "options": ["hang up", "copy the answer", "try it on", "get in"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) get in\n【用語】get in (v.phr.)：進入（車輛）\n【中譯】計程車在外面等，所以請快點上車，免得被雨淋濕。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 334, "question": "The little mouse was scared, so it ran as fast as it could to ______ the hungry cat.", "options": ["play a trick on", "get away from", "take a bus to", "look after"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) get away from\n【用語】get away from + N (v.phr.)：從……逃脫、遠離\n【中譯】那隻小老鼠很害怕，所以牠拚命地跑，想逃離那隻飢餓的貓。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 335, "question": "You studied very hard, so don't ______; I'm sure you'll do well tomorrow.", "options": ["hang out with your friends", "watch a show", "worry about the test", "make a noise"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) worry about the test\n【用語】worry about + N/V-ing (v.phr.)：為…擔心\n【中譯】你讀書非常用功，所以別擔心考試；我相信你明天會考得很好。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 336, "question": "I had only five minutes before the test, so I quickly ______.", "options": ["took a bath", "ran through my notes", "did a lot of good", "booked a room"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) ran through my notes\n【用語】run through + N (v.phr.)：瀏覽\n【中譯】考試前我只剩五分鐘，所以我快速地瀏覽了一下我的筆記。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 337, "question": "On the map, the small red star ______.", "options": ["leaves behind a bag", "makes a noise", "stands for the capital city", "takes a joke"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) stands for the capital city\n【用語】stand for + N (v.phr.)：代表、象徵\n【中譯】在地圖上，那顆小紅星代表首都。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 338, "question": "Dad finally ______, so we can go camping this weekend.", "options": ["took the box away from the shelf", "agreed to our plan", "lost his way", "asked for help"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) agreed to our plan\n【用語】agree to + N/VR (v.phr.)：同意（某事、提議）\n【中譯】爸爸終於同意了我們的計畫，所以我們這個週末可以去露營了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 339, "question": "When Amy first visited Tainan, she ______ at once and wanted to live there.", "options": ["fell in love with the city", "tasted sweet", "got the big picture", "took a nap"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) fell in love with the city\n【用語】fall in love with + 人 (v.phr.)：和某人談戀愛；愛上某人\n【中譯】Amy第一次造訪台南時，立刻就愛上了這座城市，並想住在那裡。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 340, "question": "On the test paper, please ______ with the right words.", "options": ["fill in the blanks", "give out a loud sound", "turn off the lights", "prepare for the trip"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) fill in the blanks\n【用語】fill in + N (v.phr.)：填寫（空格）\n【中譯】在考卷上，請用正確的字填寫空格。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 341, "question": "The doctor told the boy to ______ while she checked his ears.", "options": ["keep in mind that she was busy", "go for a swim", "agree with her on the plan", "stay still"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) stay still\n【用語】stay still (v.phr.)：保持靜止\n【中譯】醫生在檢查男孩的耳朵時，叫他保持不動。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 342, "question": "Let's go to the theater and ______ tonight because I hear \"Super Cat\" is very funny.", "options": ["take off our shoes", "see a movie", "do the dishes", "take a wild guess"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) see a movie\n【用語】see a movie (v.phr.)：看電影\n【中譯】我們今晚去電影院看電影吧，因為我聽說《超級貓》很好笑。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 343, "question": "The restaurant is always full on weekends, so we should ______ before we go.", "options": ["make reservations", "look around", "catch the train", "do the laundry"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) make reservations\n【用語】make reservations (v.phr.)：預約\n【中譯】那家餐廳週末總是客滿，所以我們去之前應該先預約。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 344, "question": "The runner was very tired, but she ______ and finally reached the finish line.", "options": ["checked out", "kept running", "reminded me of my sister", "fell asleep"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) kept running\n【用語】keep + V-ing (v.phr.)：繼續做……\n【中譯】那位跑者非常累，但她繼續跑，終於到達了終點線。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 345, "question": "At the school party, Tom ______ by walking and talking just like him, and everyone laughed.", "options": ["made up stories", "waved at our principal", "took off our principal", "bought a cake for our principal"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) took off our principal\n【用語】take off + 人 (v.phr.)：模仿（某人）\n【中譯】在學校派對上，Tom模仿我們的校長，走路和說話都跟他一模一樣，大家都笑了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 346, "question": "Before the trip, we sat down together to ______ for each day.", "options": ["occur to us", "break out", "make a plan", "pick fruit"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) make a plan\n【用語】make a plan (v.phr.)：訂計畫\n【中譯】旅行之前，我們一起坐下來為每一天訂計畫。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 347, "question": "I have a math test tomorrow, so tonight I will ______ carefully.", "options": ["go over well", "turn my head", "take out the garbage", "go over my notes"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) go over my notes\n【用語】go over + N (v.phr.)：查看、複習、重溫\n【中譯】我明天有數學考試，所以今晚我會仔細地複習我的筆記。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 348, "question": "Put on your jacket, or you'll ______ in this cold weather.", "options": ["work out", "lose weight", "make a habit of running", "catch a cold"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) catch a cold\n【用語】catch a cold (v.phr.)：感冒\n【中譯】穿上你的外套，不然在這麼冷的天氣裡你會感冒。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 349, "question": "If you swim in the sea alone at night, you're just ______.", "options": ["making your friends smile", "asking for trouble", "doing the dishes", "getting out of the car"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) asking for trouble\n【用語】ask for trouble (v.phr.)：自找麻煩；自找苦吃\n【中譯】如果你晚上獨自在海裡游泳，那根本就是自找麻煩。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 350, "question": "The hikers ______ at 6 a.m., so they reached the top of the mountain before noon.", "options": ["took a nap", "broke up", "set out", "had trouble waking up"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) set out\n【用語】set out (v.phr.)：出發、開始\n【中譯】健行者們早上六點出發，所以他們在中午前到達了山頂。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 351, "question": "Your test is tomorrow, so stop ______ and start studying!", "options": ["getting full marks", "telling the truth", "fooling around", "falling apart"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) fooling around\n【用語】fool around (v.phr.)：鬼混、遊手好閒\n【中譯】你明天就要考試了，所以別再鬼混，開始讀書吧！", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 352, "question": "Mr. Chen told us to ______ by Friday because he wants to grade them over the weekend.", "options": ["turn over our desks", "borrow pens from him", "turn in our reports", "make faces at him"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) turn in our reports\n【用語】turn in + N (v.phr.)：繳交、交回\n【中譯】陳老師叫我們星期五前交報告，因為他想在週末批改。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 353, "question": "We thought the new student would be shy, but she ______.", "options": ["commented on the weather", "took a nap", "focused on her phone", "turned out to be very outgoing"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) turned out to be very outgoing\n【用語】turn out + to + VR / that 子句 (v.phr.)：結果（是）\n【中譯】我們以為新同學會很害羞，結果她非常外向。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 354, "question": "The dance was very difficult, but after practicing for months, the students ______ on stage.", "options": ["lost their way", "fell short of the goal", "pulled it off", "made certain that the door was locked"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) pulled it off\n【用語】pull off + N (v.phr.)：成功完成（困難的事，如一場表演）\n【中譯】這支舞非常難，但經過幾個月的練習，學生們在台上成功完成了演出。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 355, "question": "Last Sunday, I ______ and had tea with her at her home.", "options": ["called on my grandma", "made up an excuse", "broke up with my best friend", "got a haircut"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) called on my grandma\n【用語】call on + 人 (v.phr.)：拜訪\n【中譯】上週日，我去拜訪了奶奶，並在她家和她一起喝茶。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 356, "question": "It might rain this afternoon, so you'd better ______ when you go out.", "options": ["make a list", "take up swimming", "keep me company", "take an umbrella along"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) take an umbrella along\n【用語】take + 物 + along (v.phr.)：隨身攜帶\n【中譯】今天下午可能會下雨，所以你出門時最好隨身帶把傘。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 357, "question": "Lily ______ for three months, so it won first prize in the art contest.", "options": ["put her heart into the painting", "served as a class leader", "took a break", "made her mom happy"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) put her heart into the painting\n【用語】put one's heart into + N/V-ing (v.phr.)：全心投入\n【中譯】Lily花了三個月全心投入那幅畫，所以它在美術比賽中得了首獎。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 358, "question": "Because of the heavy rain, we had to ______ and go home early.", "options": ["cut our trip short", "push open the window", "look forward to our trip", "refer to the dictionary"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) cut our trip short\n【用語】cut short + N (v.phr.)：縮短\n【中譯】因為下大雨，我們不得不縮短旅程，提早回家。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 359, "question": "If someone is bullying you, don't be afraid to ______ and tell a teacher.", "options": ["take a nap", "turn up the radio", "speak up", "make a difference"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) speak up\n【用語】speak up (v.phr.)：勇敢表達\n【中譯】如果有人霸凌你，不要害怕勇敢說出來，並告訴老師。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 360, "question": "The delicious food at the night market ______ every weekend.", "options": ["draws in many tourists", "does exercise", "takes out the garbage", "tells a lie"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) draws in many tourists\n【用語】draw in + 人 (v.phr.)：吸引（人群）；把⋯⋯拉進\n【中譯】夜市的美食每個週末都吸引許多觀光客。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 361, "question": "The little girl cried and cried, but she didn't ______; her mom still said no to the candy.", "options": ["take a shower", "appeal to the court", "get her way", "fasten the seatbelt"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) get her way\n【用語】get/have one's way (v.phr.)：如願\n【中譯】小女孩一直哭，但她沒能如願；她媽媽還是不讓她吃糖果。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 362, "question": "The strong wind made the old tree ______ last night.", "options": ["look at the bright side of things", "fall down", "win back the game", "grow up"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) fall down\n【用語】fall down (v.phr.)：倒下來\n【中譯】昨晚的強風讓那棵老樹倒了下來。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 363, "question": "The twins look exactly the same, so I can't ______.", "options": ["stay out of trouble", "cut down on sugar", "tell them apart", "make the bed"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) tell them apart\n【用語】tell A and B apart (v.phr.)：分辨 A 和 B\n【中譯】那對雙胞胎長得一模一樣，所以我分辨不出他們誰是誰。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 364, "question": "On our way to Taichung, we ______ for an hour to buy some fruit.", "options": ["looked up the word in the dictionary", "reported the latest news", "called at a small town", "cleaned up the kitchen"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) called at a small town\n【用語】call at + 地方 (v.phr.)：造訪某地\n【中譯】在前往台中的路上，我們在一個小鎮停留了一個小時，買了一些水果。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 365, "question": "Before you buy a new phone, you should ______ to see which one is cheaper.", "options": ["compare this phone with that one", "move on to the next lesson", "play a role", "make a wish"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) compare this phone with that one\n【用語】compare + N + with + N (v.phr.)：與……相比、比較……和……\n【中譯】在你買新手機之前，你應該把這支手機和那支比較一下，看看哪一支比較便宜。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 366, "question": "A: When can I see the doctor?\nB: He is busy now, but he will see you in ten minutes. Please ______.", "options": ["get in trouble", "cut in the line", "sit tight", "feel sad"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) sit tight\n【用語】sit tight (v.phr.)：耐心等候\n【中譯】A：我什麼時候可以看醫生？\nB：他現在很忙，但十分鐘後就會看你。請耐心等候。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 367, "question": "Mr. Wang said to the class, \"______, everyone! I have something important to tell you.\"", "options": ["Make a wish", "Do the laundry", "Listen up", "Go away"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) Listen up\n【用語】listen up (v.phr.)：注意聽了\n【中譯】王老師對全班說：「大家注意聽了！我有重要的事要告訴你們。」", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 368, "question": "The workers ______ for two hours this morning, so we couldn't take a shower.", "options": ["cut off the water", "took it personally", "put up a tent", "reached a conclusion"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) cut off the water\n【用語】cut off + N (v.phr.)：切除、切斷\n【中譯】工人們今天早上把水切斷了兩個小時，所以我們沒辦法洗澡。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 369, "question": "My grandfather was very sick, and he ______ last winter. We all miss him.", "options": ["blew down a tree", "passed on", "told a lie", "did me a favor"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) passed on\n【用語】pass on (v.phr.)：死亡、過世\n【中譯】我爺爺病得很重，他在去年冬天過世了。我們都很想念他。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 370, "question": "It's so hot today. Let's go to the beach and ______.", "options": ["lend our books to Amy", "have a swim", "do the dishes", "make a copy"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) have a swim\n【用語】have a swim (v.phr.)：去游泳\n【中譯】今天好熱。我們去海邊游泳吧。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 371, "question": "I didn't see the mistakes in my essay, but my teacher ______. Now I can fix them.", "options": ["went by", "threw them away", "fell apart", "pointed them out"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) pointed them out\n【用語】point out + N/that 子句 (v.phr.)：指出\n【中譯】我沒看到作文裡的錯誤，但老師把它們指出來了。現在我可以改正了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 372, "question": "Before we left for our trip, Dad ______ to keep the house safe.", "options": ["tried out a new phone", "made the bed", "reached the point", "locked up all the doors"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) locked up all the doors\n【用語】lock up + N (v.phr.)：鎖上\n【中譯】我們出發去旅行前，爸爸把所有的門都鎖上，讓房子保持安全。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 373, "question": "Kevin is rich, but he never ______. He thinks everyone is equal.", "options": ["takes his car for example", "introduces his friends to his parents", "looks down upon poor people", "brushes his teeth"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) looks down upon poor people\n【用語】look down upon + 人 (v.phr.)：輕視\n【中譯】Kevin很有錢，但他從不輕視窮人。他認為人人平等。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 374, "question": "The math problem was very hard, but Amy didn't ______. She kept trying until she found the answer.", "options": ["go abroad", "blow over the tree", "use up her paper", "give up"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) give up\n【用語】give up + N/V-ing (v.phr.)：放棄\n【中譯】這道數學題很難，但Amy沒有放棄。她一直嘗試，直到找到答案。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 375, "question": "A: ______! We're going to be late for the movie!\nB: OK, I'm coming.", "options": ["Let it go", "Lie down", "Take your time", "Come on"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) Come on\n【用語】come on (v.phr.)：趕快；拜託；加油\n【中譯】A：快點！我們看電影要遲到了！\nB：好，我來了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 376, "question": "This shop has twenty kinds of cakes. You can ______ them, but you can only buy one.", "options": ["wait for", "listen to", "laugh at", "choose from"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) choose from\n【用語】choose from + N (v.phr.)：（從…中）選擇\n【中譯】這家店有二十種蛋糕。你可以從中挑選，但只能買一個。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 377, "question": "The teacher only has one worksheet. Can you go to the office and ______ for each student?", "options": ["pick fruit", "face the problem", "grow flowers", "make a copy"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) make a copy\n【用語】make a copy (v.phr.)：製作副本\n【中譯】老師只有一張學習單。你可以去辦公室幫每位學生影印一份嗎？", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 378, "question": "The police officer told the driver to ______ because he was driving too fast.", "options": ["pull over", "adapt to the new school", "hold on to his car", "turn left"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) pull over\n【用語】pull over (v.phr.)：把車開到路邊停下\n【中譯】警察因為駕駛開得太快，叫他把車開到路邊停下。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 379, "question": "It took us two hours to ______ by bus.", "options": ["take a walk", "push the chair over", "get to Taipei", "do our hair"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) get to Taipei\n【用語】get to + 地方 (v.phr.)：到達某地\n【中譯】我們搭公車花了兩個小時才到達台北。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 380, "question": "To protect the earth, we should ______ and take buses more often.", "options": ["go green", "cover the bill", "cut down trees", "fail the test"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) go green\n【用語】go green (v.phr.)：採取環保行動\n【中譯】為了保護地球，我們應該採取環保行動，並且更常搭公車。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 381, "question": "The students sold cookies to ______ for the sick children.", "options": ["cover the news", "have a seat", "take a nap", "raise money"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) raise money\n【用語】raise money (v.phr.)：募款\n【中譯】學生們賣餅乾為生病的孩子們募款。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 382, "question": "A: Can you ______?\nB: Sure. What do you need?", "options": ["take a nap", "do me a favor", "have pizza for dinner", "come on"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) do me a favor\n【用語】do + 人 + a favor (v.phr.)：幫……一個忙\n【中譯】A：你可以幫我一個忙嗎？\nB：當然。你需要什麼？", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 383, "question": "Ben ______ again. He said he finished his homework, but he didn't even start it.", "options": ["told a lie", "cared for spicy food", "asked his friends out for lunch", "couldn't take a joke"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) told a lie\n【用語】tell a lie (v.phr.)：說謊\n【中譯】Ben又說謊了。他說他寫完功課了，但他根本還沒開始寫。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 384, "question": "My dad loves the sea. On weekends, he often takes his boat and ______.", "options": ["dies of boredom", "goes fishing", "makes a cake for me", "does the dishes"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) goes fishing\n【用語】go + V-ing (v.phr.)：從事某種休閒活動\n【中譯】我爸爸熱愛大海。週末他常常開著他的船去釣魚。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 385, "question": "I'm cooking now. Can you ______? It's ringing.", "options": ["answer the phone", "set aside some money", "take down the thief", "wait for the bus"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) answer the phone\n【用語】answer the phone (v.phr.)：接電話\n【中譯】我正在煮飯。你可以接一下電話嗎？它在響。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 386, "question": "When she was little, my sister ______, so she was afraid to sleep alone at night.", "options": ["grew flowers", "believed in ghosts", "checked in at a hotel", "stood her friend up"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) believed in ghosts\n【用語】believe in + N (v.phr.)：相信…存在\n【中譯】我妹妹小時候相信有鬼，所以她晚上很怕一個人睡。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 387, "question": "The princess kissed the frog, and suddenly it ______ a handsome prince. It was not a frog anymore.", "options": ["ran away from", "waved at", "looked at", "changed into"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) changed into\n【用語】change (+ N) into + N (v.phr.)：（將……）變成……\n【中譯】公主親了青蛙，牠突然變成一位英俊的王子。牠不再是青蛙了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 388, "question": "Many people ______ the new plan, so they voted for it.", "options": ["handed back", "laughed at", "threw away", "stood for"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) stood for\n【用語】stand for + N (v.phr.)：支持\n【中譯】很多人支持這個新計畫，所以他們投票贊成。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 389, "question": "Lisa ______ last year, but now she is happy again.", "options": ["thought the plan through", "went through a hard time", "had a good time", "did sports"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) went through a hard time\n【用語】go through + N (v.phr.)：經歷\n【中譯】Lisa去年經歷了一段艱難的時期，但現在她又快樂起來了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 390, "question": "As people ______, their hair often turns white.", "options": ["grow old", "move along", "consider moving", "end up crying"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) grow old\n【用語】grow old (v.phr.)：變老\n【中譯】隨著人們變老，他們的頭髮常常會變白。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 391, "question": "Don't ______ when you leave the room. It wastes electricity.", "options": ["listen to my advice", "leave the a/c on", "turn off the lights", "make noise"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) leave the a/c on\n【用語】leave the a/c on (v.phr.)：讓冷氣開著\n【中譯】離開房間時不要讓冷氣開著。那很浪費電。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 392, "question": "You should ______ your free time and read more books.", "options": ["cover", "make good use of", "succeed in", "make friends with"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) make good use of\n【用語】make good/full use of + N (v.phr.)：善加利用\n【中譯】你應該善加利用你的空閒時間，多讀一些書。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 393, "question": "The thief felt sorry for what he did. He went to the police and ______.", "options": ["turned himself in", "brought up his kids", "took a bath", "went sightseeing"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) turned himself in\n【用語】turn in + 人 (v.phr.)：（向警方）告發、自首\n【中譯】小偷對自己做的事感到後悔。他去找警察自首了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 394, "question": "You can't have ice cream until you ______ your vegetables.", "options": ["eat up", "write down", "put out", "cut the use of"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) eat up\n【用語】eat up + N (v.phr.)：吃完\n【中譯】你要把蔬菜吃完才能吃冰淇淋。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 395, "question": "This rule is very important. Please ______.", "options": ["throw it away", "cut down trees", "keep it in mind", "break down"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) keep it in mind\n【用語】keep/bear + N + in mind (v.phr.)：記住、記得\n【中譯】這條規則非常重要。請記住它。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 396, "question": "It rained all day during our trip, but we ______ and played cards in the hotel.", "options": ["made the best of it", "brought it back", "turned it down", "clung to it"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) made the best of it\n【用語】make the best of + N (v.phr.)：充分利用\n【中譯】我們旅行時下了一整天的雨，但我們充分利用這個情況，在飯店裡玩牌。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 397, "question": "Your story is too long for the school paper. Can you ______?", "options": ["get up", "kill time", "cut it down", "turn up the volume"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) cut it down\n【用語】cut down + N (v.phr.)：減短、縮減\n【中譯】你的故事對校刊來說太長了。你可以把它縮短嗎？", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 398, "question": "When we arrived at Grandma's house, she ______ and said, \"Welcome!\"", "options": ["watched out for cars", "cut the paper", "picked up English", "greeted us with a big hug"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) greeted us with a big hug\n【用語】greet + 人 + with + N (v.phr.)：以…迎接\n【中譯】我們到奶奶家時，她給我們一個大大的擁抱迎接我們，並說：「歡迎！」", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 399, "question": "I ______, so I had to go back home to get it.", "options": ["lent my pen to Amy", "left my book at home", "turned the box into a car", "cared for my sick grandma"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) left my book at home\n【用語】leave + 物 + 地方 (v.phr.)：把某物留在某處\n【中譯】我把書留在家裡了，所以我必須回家拿。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 400, "question": "This soup is not salty enough. Please ______.", "options": ["add some salt to it", "do the dishes", "meet with Mr. Lin", "run through the park"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) add some salt to it\n【用語】add + N + to + N (v.phr.)：把……加到……\n【中譯】這碗湯不夠鹹。請在裡面加一些鹽。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 401, "question": "Time ______ so fast! It's already the end of the year.", "options": ["clings to my hand", "works on the project", "goes by", "goes abroad"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) goes by\n【用語】go by (v.phr.)：（時間）消逝\n【中譯】時間過得真快！已經是年底了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 402, "question": "Don't be sad about losing the game. Try to ______. You learned a lot from it.", "options": ["take a shower", "fail the test", "see the bright side of it", "make up a story about it"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) see the bright side of it\n【用語】see the bright side of + N (v.phr.)：樂觀看待…\n【中譯】別為輸了比賽難過。試著樂觀看待這件事。你從中學到了很多。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 403, "question": "The students were too noisy, so Mr. Lin ______ stop talking and open their books.", "options": ["asked them to", "used to", "wanted to", "would like to"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) asked them to\n【用語】ask + 人 + to + VR (v.phr.)：要求某人做……\n【中譯】學生們太吵了，所以林老師要求他們停止講話，並打開課本。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 404, "question": "Traveling is a good way to ______. Kids can learn a lot from it.", "options": ["break the world record", "care about money", "expose kids to new things", "take their parents for granted"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) expose kids to new things\n【用語】expose + N + to + N (v.phr.)：使……暴露於、使……接觸到\n【中譯】旅行是讓孩子接觸新事物的好方法。孩子們可以從中學到很多。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 405, "question": "The snow was not deep. It only ______.", "options": ["went viral", "reached my ankles", "turned back", "made it"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) reached my ankles\n【用語】reach the ankles (v.phr.)：到腳踝（的高度）\n【中譯】雪不深，只到我的腳踝。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 406, "question": "Tom had a high fever, so he had to ______ for three days.", "options": ["make a list", "stay in bed", "pull up", "dig out his old toys"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) stay in bed\n【用語】stay in bed (v.phr.)：生病臥床\n【中譯】Tom發高燒，所以他必須臥床休息三天。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 407, "question": "Dad was very angry because I broke his favorite cup. He ______.", "options": ["looked out", "yelled at me", "let me down", "heard about me"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) yelled at me\n【用語】yell at + 人 (v.phr.)：對……大叫；吼叫\n【中譯】爸爸非常生氣，因為我打破了他最喜歡的杯子。他對我大吼。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 408, "question": "Lily played in the rain without a coat, so she ______ and had to stay home.", "options": ["went whale-watching", "took part in a race", "gave me a ride", "got a cold"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) got a cold\n【用語】get a cold (v.phr.)：感冒\n【中譯】Lily沒穿外套就在雨中玩，所以她感冒了，必須待在家裡。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 409, "question": "A: I'm so nervous about the test tomorrow.\nB: ______. You studied hard, so you'll do fine.", "options": ["Take it easy", "Serves you right", "Count me in", "Keep the change"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) Take it easy\n【用語】take it easy (v.phr.)：放輕鬆；別緊張\n【中譯】A：我對明天的考試好緊張。\nB：放輕鬆。你很用功，所以會考得很好的。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 410, "question": "My tooth hurt badly, so the dentist ______. Now I have one less tooth.", "options": ["pushed me around", "looked at it", "pulled it out", "dated back to 1900"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) pulled it out\n【用語】pull out + N (v.phr.)：拔出\n【中譯】我的牙齒痛得很厲害，所以牙醫把它拔掉了。現在我少了一顆牙。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 411, "question": "A: Where were you yesterday?\nB: I was sick, so I ______ all day. I didn't go out.", "options": ["stayed at home", "went on vacation", "went for a walk", "took a trip to Tainan"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) stayed at home\n【用語】stay at home (v.phr.)：待在家裡\n【中譯】A：你昨天在哪裡？\nB：我生病了，所以整天待在家裡。我沒有出門。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 412, "question": "The strong typhoon ______ many houses in our town.", "options": ["belonged to", "did damage to", "threw away", "did well in"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) did damage to\n【用語】do damage to + N (v.phr.)：對……造成傷害\n【中譯】強烈颱風對我們鎮上的許多房子造成了損害。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 413, "question": "It's so hot today. Let's ______ in the swimming pool. The water is nice and cool.", "options": ["take a while", "go for a swim", "give him a big hand", "go whale-watching"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) go for a swim\n【用語】go for a swim (v.phr.)：去游泳\n【中譯】今天好熱。我們去游泳池游泳吧。水很涼快。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 414, "question": "Ben plays basketball very well. Next week he will ______ the school team. He hopes the coach will choose him.", "options": ["try out for", "make fun of", "look down on", "run across"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) try out for\n【用語】try out for + N (v.phr.)：參加選拔\n【中譯】Ben 籃球打得很好。下週他要參加校隊選拔。他希望教練會選他。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 415, "question": "Don't leave your coat on the sofa. Please ______ on the hook behind the door.", "options": ["solve the case", "feel like dancing", "take a bath", "hang up your coat"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) hang up your coat\n【用語】hang up + N (v.phr.)：掛起\n【中譯】不要把外套丟在沙發上。請把你的外套掛在門後的掛鉤上。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 416, "question": "Good teachers ______ our lives. They help us learn and grow.", "options": ["carry out", "do damage to", "play an important role in", "look down on"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) play an important role in\n【用語】play an important role in + N/V-ing (v.phr.)：扮演重要角色\n【中譯】好老師在我們的生命中扮演重要的角色。他們幫助我們學習和成長。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 417, "question": "This old watch was my grandpa's. I ______ because it reminds me of him.", "options": ["put it into words", "make a wild guess", "hold it dear", "bring it in"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) hold it dear\n【用語】hold + N + dear (v.phr.)：珍視；深愛\n【中譯】這支舊手錶是我爺爺的。我很珍惜它，因為它讓我想起他。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 418, "question": "I was too busy to go to the store, so I ______ last night. It will arrive tomorrow.", "options": ["took a bath", "stood by my sister", "belonged to my sister", "ordered a new bag online"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) ordered a new bag online\n【用語】order + 物 + online (v.phr.)：在網路上訂購\n【中譯】我太忙了沒辦法去商店，所以昨晚在網路上訂了一個新包包。它明天會送到。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 419, "question": "When we got to the campsite, Dad ______, and we slept in it that night.", "options": ["used a knife to cut the bread", "put up a tent", "did us good", "let us swim"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) put up a tent\n【用語】put up a tent (v.phr.)：搭起帳篷\n【中譯】我們到達露營區時，爸爸搭起了帳篷，那天晚上我們就睡在裡面。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 420, "question": "If you know the answer, please ______, and I will call on you.", "options": ["make a living by teaching", "go straight for two blocks", "roll your eyes", "put up your hand"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) put up your hand\n【用語】put up one's hand (v.phr.)：舉手\n【中譯】如果你知道答案，請舉手，我就會點你回答。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 421, "question": "Everyone in our class ______ cleaning the park last Sunday. We picked up a lot of trash together.", "options": ["put off", "made fun of", "played a part in", "did without"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) played a part in\n【用語】play a part in + N/V-ing (v.phr.)：參與；起某種作用\n【中譯】上週日我們班每個人都參與了打掃公園。我們一起撿了很多垃圾。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 422, "question": "A typhoon is coming, so the school ______ until next week.", "options": ["put off the sports day", "kept the students from eating lunch", "did English exercises", "had a sale"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) put off the sports day\n【用語】put off + N/V-ing (v.phr.)：拖延、延期\n【中譯】颱風要來了，所以學校把運動會延到下週。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 423, "question": "The music is too loud. Could you ______ the radio, please?", "options": ["run across", "turn down", "turn up", "hang up on"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) turn down\n【用語】turn down + N (v.phr.)：調降、關小（音量）\n【中譯】音樂太大聲了。可以請你把收音機關小聲一點嗎？", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 424, "question": "Kevin isn't good at English, but he ______ every day. Now his grades are getting better.", "options": ["makes an effort", "prefers comics to books", "would rather sleep than study", "has nothing to do"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) makes an effort\n【用語】make an effort (v.phr.)：努力\n【中譯】Kevin 英文不好，但他每天都很努力。現在他的成績越來越好了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 425, "question": "At first, Amy didn't like her new school, but slowly she ______ love it.", "options": ["had to", "came to", "used to", "failed to"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) came to\n【用語】come to + VR (v.phr.)：漸漸……（come to + V）\n【中譯】一開始 Amy 不喜歡她的新學校，但她漸漸地愛上了它。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 426, "question": "My brother always ______. He says I'm stupid and ugly.", "options": ["concentrates on his homework", "makes up for his mistakes", "stands up for me", "puts me down"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) puts me down\n【用語】put + 人 + down (v.phr.)：貶低某人\n【中譯】我哥哥總是貶低我。他說我又笨又醜。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 427, "question": "In English class, Jenny always ______ what the teacher says in her notebook.", "options": ["takes down", "looks on the bright side of", "turns down", "hangs up on"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) takes down\n【用語】take down + N (v.phr.)：記下；做筆記\n【中譯】在英文課上，Jenny 總是把老師說的話記在筆記本裡。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 428, "question": "A: Knock, knock. May I ______?\nB: Sure. Please sit down.", "options": ["come in", "hang on", "stand by", "record the voice"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) come in\n【用語】come in (v.phr.)：進來\n【中譯】A：叩叩。我可以進來嗎？\nB：當然。請坐。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 429, "question": "Winning the singing contest ______ at our school. Now everyone knows her.", "options": ["went whale-watching", "put Lisa down", "spent the holiday", "made Lisa a star"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) made Lisa a star\n【用語】make + 人 + N (v.phr.)：使某人成為……（名詞）\n【中譯】贏得歌唱比賽讓 Lisa 成為我們學校的明星。現在大家都認識她。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 430, "question": "This road ______. Just walk along it for five minutes.", "options": ["puts it into words", "leads to the train station", "meets the need for water", "takes a bow"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) leads to the train station\n【用語】lead to + 地方 (v.phr.)：通往\n【中譯】這條路通往火車站。只要沿著它走五分鐘就到了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 431, "question": "Before Dad went into the store, he ______ to a tree so it wouldn't run away.", "options": ["got his work out of the way", "tied up the dog", "lit a match", "kept it in mind"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) tied up the dog\n【用語】tie up + N (v.phr.)：繫住、綁住\n【中譯】爸爸進商店前，把狗綁在樹上，這樣牠就不會跑掉。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 432, "question": "The taxi ride was 300 dollars. Dad ______ and got out of the car.", "options": ["got off the bus", "made a wild guess", "went along", "paid the driver for the ride"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) paid the driver for the ride\n【用語】pay + N + for + N (v.phr.)：付錢購買（服務、物品）\n【中譯】計程車車資是三百元。爸爸付了車資給司機，然後下了車。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 433, "question": "Ms. Smith ______. She was born there and moved to Taiwan five years ago.", "options": ["stays high", "solves the case", "stays in touch with her mom", "comes from Canada"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) comes from Canada\n【用語】come from + 地方 (v.phr.)：來自\n【中譯】Smith 老師來自加拿大。她在那裡出生，五年前搬到台灣。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 434, "question": "It's Halloween! The kids ______ as ghosts and monsters.", "options": ["showed their mom they cared", "took a bath", "dressed up", "passed the test"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) dressed up\n【用語】dress up (v.phr.)：盛裝打扮；裝扮\n【中譯】萬聖節到了！孩子們打扮成鬼和怪物。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 435, "question": "After dinner, I help Mom ______. I wash all the bowls and plates.", "options": ["do the dishes", "have nothing to do", "put on a show", "push over the table"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) do the dishes\n【用語】do the dishes (v.phr.)：洗碗\n【中譯】晚餐後，我幫媽媽洗碗。我把所有的碗盤都洗乾淨。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 436, "question": "Mr. Lin parked his car in the wrong place, so he ______. He had to pay 600 dollars.", "options": ["got full marks", "got a fine", "changed his way of driving", "knew of the place"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) got a fine\n【用語】get a fine (v.phr.)：收到罰款\n【中譯】林先生把車停錯地方，所以他被罰款了。他必須付六百元。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 437, "question": "A: Did you understand the English movie?\nB: I didn't know every word, but I ______.", "options": ["made a decision", "couldn't believe it", "got the idea", "sounded like a cat"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) got the idea\n【用語】get the idea (v.phr.)：理解大意\n【中譯】A：你看得懂那部英文電影嗎？\nB：我不是每個字都懂，但我理解了大意。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 438, "question": "Are you ______? You want to swim in the river in winter? It's too cold!", "options": ["losing your mind", "taking a trip to Japan", "running into your friend", "having a stomachache"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) losing your mind\n【用語】lose one's mind (v.phr.)：發瘋；失去理智\n【中譯】你瘋了嗎？你想在冬天去河裡游泳？太冷了！", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 439, "question": "The big boys always ______ Tim. They take his lunch money and laugh at him.", "options": ["take care of", "pick on", "run out of", "get along with"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) pick on\n【用語】pick on + 人 (v.phr.)：找……的麻煩、挑……的毛病\n【中譯】那些大男孩總是找 Tim 的麻煩。他們拿走他的午餐錢，還嘲笑他。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 440, "question": "______! There's a car coming!", "options": ["Go off", "Watch out", "Go wild", "Face the music"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) Watch out\n【用語】watch out (for + N) (v.phr.)：小心\n【中譯】小心！有車子來了！", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 441, "question": "Tom ______. He has a lot of friends, and he never fights with anyone.", "options": ["watches a game", "has a sore throat", "has a good command of English", "gets along with everyone"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) gets along with everyone\n【用語】get along with + 人 (v.phr.)：與……相處融洽\n【中譯】Tom 和每個人都相處融洽。他有很多朋友，而且從不和任何人吵架。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 442, "question": "My parents hoped I would do well on the test. I studied hard and ______. They were very happy.", "options": ["met their expectation", "did nothing", "died out", "failed the test"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) met their expectation\n【用語】meet the expectation (v.phr.)：符合期待；達到期望\n【中譯】我爸媽希望我考試考好。我努力讀書，達到了他們的期望。他們非常高興。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 443, "question": "Lily wanted to be a singer. She practiced every day, and finally she ______.", "options": ["rolled her eyes", "went on vacation", "lost her way", "made her dream come true"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) made her dream come true\n【用語】make one's dream come true (v.phr.)：讓夢想成真\n【中譯】Lily 想當歌手。她每天練習，最後終於讓夢想成真。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 444, "question": "Tom ate too much ice cream last night, and now he ______. He needs to see a doctor.", "options": ["has a stomachache", "reaches the top of the hill", "goes whale-watching", "sees a doctor"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) has a stomachache\n【用語】have a stomachache (v.phr.)：胃痛\n【中譯】Tom 昨晚吃了太多冰淇淋，現在他胃痛。他需要去看醫生。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 445, "question": "Ben's toy plane ______ from the playground and flew high into the sky.", "options": ["fell asleep", "covered its eyes", "went off", "took off"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) took off\n【用語】take off (v.phr.)：（飛機）起飛\n【中譯】Ben 的玩具飛機從操場起飛，飛上了高空。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 446, "question": "It was dark. Grandpa ______ and used it to light a candle.", "options": ["passed the salt to me", "lit a match", "blew out the candle", "broke a bad habit"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) lit a match\n【用語】light a match (v.phr.)：點燃火柴\n【中譯】天很暗。爺爺點燃一根火柴，用它來點蠟燭。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 447, "question": "I'm sorry I forgot your birthday. Let me ______. I'll buy you a nice dinner.", "options": ["roll my eyes", "stay friends", "pass the test", "make it up to you"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) make it up to you\n【用語】make it up to + 人 (v.phr.)：補償（某人）\n【中譯】很抱歉我忘了你的生日。讓我補償你。我會請你吃一頓好吃的晚餐。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 448, "question": "At the hair salon, Mom ______ my haircut.", "options": ["clicked on", "blew out", "looked down on", "paid 300 dollars for"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) paid 300 dollars for\n【用語】pay + 錢 + for + N (v.phr.)：為⋯⋯付錢（如服務）\n【中譯】在髮廊，媽媽為我的剪髮付了三百元。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 449, "question": "Tonight Jack ______ his grandma. He will take her to a nice restaurant and a movie.", "options": ["has a date with", "runs out of", "shouts at", "copies the behavior of"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) has a date with\n【用語】have a date with + 人 (v.phr.)：與某人約會\n【中譯】今晚 Jack 和他奶奶有約。他會帶她去一家不錯的餐廳，然後去看電影。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 450, "question": "In fall, the leaves ______ yellow and red.", "options": ["shout at", "see", "turn", "smell"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) turn\n【用語】turn + 顏色 (v.phr.)：變成某種顏色\n【中譯】秋天時，樹葉會變成黃色和紅色。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 451, "question": "Please ______ with your name and phone number.", "options": ["fill out this form", "keep off the grass", "hang up your coat", "find the book interesting"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) fill out this form\n【用語】fill out + N (v.phr.)：填寫（表格）\n【中譯】請在這張表格上填寫你的姓名和電話號碼。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 452, "question": "It rained all morning, but the weather ______ in the afternoon, so we went to the park.", "options": ["lit up the room", "cleared up", "spoke up", "got over the cold"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) cleared up\n【用語】clear up (v.phr.)：放晴\n【中譯】整個早上都在下雨，但下午天氣放晴了，所以我們去了公園。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 453, "question": "Tom and Ben didn't agree on many things, but they ______ and worked together to win the game.", "options": ["broke up", "paid attention to their phones", "made fools of each other", "put aside their differences"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) put aside their differences\n【用語】put aside one's differences (v.phr.)：擱置分歧\n【中譯】Tom 和 Ben 在很多事情上意見不同，但他們擱置分歧，一起合作贏得比賽。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 454, "question": "There were four of us at dinner, so each person ______.", "options": ["clicked on the photo", "paid 25% of the bill", "blew out the candles", "cut in the line"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) paid 25% of the bill\n【用語】pay + 百分比 + of the bill (v.phr.)：支付帳單的…%（用於分帳）\n【中譯】我們四個人一起吃晚餐，所以每個人各付帳單的百分之二十五。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 455, "question": "When Ken moved to Taipei, he didn't like the hot weather. After a year, he ______, and now the heat doesn't bother him.", "options": ["got used to it", "turned to his friends for help", "made a face", "surfed the Net"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) got used to it\n【用語】get used to + N/V-ing (v.phr.)：漸漸習慣（做）某事\n【中譯】Ken 剛搬到台北時，不喜歡炎熱的天氣。一年後，他漸漸習慣了，現在炎熱已經不會困擾他了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 456, "question": "A: I've never eaten stinky tofu. Is it good?\nB: Many people love it. Why don't you ______?", "options": ["give it a try", "break the record", "meet new friends", "make a wish"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) give it a try\n【用語】give it a try (v.phr.)：試一試\n【中譯】A：我從沒吃過臭豆腐，好吃嗎？\nB：很多人都很愛。你何不試一試？", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 457, "question": "The movie tickets were sold out, so we ______.", "options": ["asked for directions", "still had a long way to go", "ended up staying home", "took a shortcut"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) ended up staying home\n【用語】end up + V-ing (v.phr.)：最後……（做了某事）\n【中譯】電影票賣完了，所以我們最後待在家裡。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 458, "question": "I thought the test was on Friday, but I ______; it was on Thursday!", "options": ["got it wrong", "fell asleep", "went viral", "made a face"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) got it wrong\n【用語】get it wrong (v.phr.)：搞錯；弄錯\n【中譯】我以為考試在星期五，但我搞錯了；考試是在星期四！", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 459, "question": "Nobody knows how the fight ______; the two boys were good friends before.", "options": ["got up", "hung around", "nodded off", "came about"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) came about\n【用語】come about (v.phr.)：發生\n【中譯】沒有人知道這場打架是怎麼發生的；這兩個男孩以前是好朋友。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 460, "question": "Many people are waiting for the bus, so please go to the end and don't ______.", "options": ["take a nap", "make up your mind", "cut the line", "reach a goal"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) cut the line\n【用語】cut the line (v.phr.)：插隊\n【中譯】很多人在等公車，所以請排到最後面，不要插隊。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 461, "question": "Before you say something mean, you should ______.", "options": ["go sightseeing", "play a role", "consider others' feelings", "go your separate ways"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) consider others' feelings\n【用語】consider others' feelings (v.phr.)：考慮別人的感受\n【中譯】在你說出刻薄的話之前，你應該考慮別人的感受。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 462, "question": "Losing the final game was hard for our team, but we ______ and started practicing again.", "options": ["lost our way", "went past the gym", "took the blow", "followed the rules"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) took the blow\n【用語】take the blow (v.phr.)：承受打擊\n【中譯】輸掉決賽對我們隊來說很難受，但我們承受了打擊，又開始練習了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 463, "question": "My watch stopped working, so I ______, and now it works well again.", "options": ["took a nap", "heard from my aunt", "made a down payment", "had it repaired"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) had it repaired\n【用語】have + 物 + p.p. (v.phr.)：請人處理某事（使役被動）\n【中譯】我的手錶壞了，所以我請人把它修好，現在它又能正常運作了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 464, "question": "Ben's little sister was hungry, so he went to the kitchen and ______.", "options": ["got her a sandwich", "set off", "fell asleep", "knocked down a chair"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) got her a sandwich\n【用語】get + 人 + 物 (v.phr.)：給某人某物\n【中譯】班的妹妹肚子餓了，所以他去廚房拿了一個三明治給她。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 465, "question": "Amy ______ because she lost her favorite necklace.", "options": ["made it", "took it easy", "felt down", "dressed up as a princess"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) felt down\n【用語】feel down/blue (v.phr.)：感到沮喪\n【中譯】艾咪因為弄丟了她最喜歡的項鍊而感到沮喪。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 466, "question": "It may rain this afternoon, so you should ______.", "options": ["stay fresh", "bring your umbrella along", "make the bed", "get rid of your umbrella"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) bring your umbrella along\n【用語】bring + 物 + along (v.phr.)：帶著……一起\n【中譯】今天下午可能會下雨，所以你應該把雨傘帶著。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 467, "question": "I ______ at the night market last night. I didn't know he would be there!", "options": ["showed my cousin around", "bumped into my old teacher", "thought twice", "brushed my teeth"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) bumped into my old teacher\n【用語】bump into + 人 (v.phr.)：撞見；巧遇\n【中譯】我昨晚在夜市巧遇我以前的老師。我不知道他會在那裡！", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 468, "question": "My brother and I ______: I wash the dishes, and he does the laundry.", "options": ["made a deal", "pulled the plug on the plan", "took a walk", "touched the ground"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) made a deal\n【用語】make a deal (v.phr.)：達成協議或交易\n【中譯】我哥哥和我達成了協議：我洗碗，他洗衣服。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 469, "question": "Some students ______ that school should start later in the morning.", "options": ["sound", "make believe", "show up", "argue"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) argue\n【用語】argue + that 子句 (v.phr.)：主張；認為\n【中譯】有些學生主張學校早上應該晚一點開始上課。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 470, "question": "The doctor says I should ______ three times a day, after meals.", "options": ["take the toys away from my brother", "pay the bill", "result from the cold", "take the medicine"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) take the medicine\n【用語】take the medicine (v.phr.)：吃藥\n【中譯】醫生說我應該一天吃三次藥，在飯後吃。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 471, "question": "Dad started the engine and told us to ______ quickly because we were late for school.", "options": ["root around for candy", "do the dishes", "get in the car", "find out the answer"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) get in the car\n【用語】get in the car/taxi/cable car (v.phr.)：上車／上計程車／上纜車（不可站立）\n【中譯】爸爸發動了引擎，叫我們快點上車，因為我們上學要遲到了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 472, "question": "Our school ______ from Japan, so now every classroom has a robot.", "options": ["went back", "gave it a shot", "brought in robots", "took a break"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) brought in robots\n【用語】bring in + N (v.phr.)：引進\n【中譯】我們學校從日本引進了機器人，所以現在每間教室都有一台機器人。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 473, "question": "Mia feels homesick in Canada, so she ______.", "options": ["goes to the gym", "draws a crowd", "longs for her mom's cooking", "has online classes"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) longs for her mom's cooking\n【用語】long for + N (v.phr.)：渴望\n【中譯】米亞在加拿大很想家，所以她很渴望吃到媽媽煮的菜。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 474, "question": "My brother tried swimming last summer and ______ right away; now he swims every weekend.", "options": ["helped me out", "kept the change", "took to it", "gave it up"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) took to it\n【用語】take to + N/V-ing (v.phr.)：開始喜歡、迷上\n【中譯】我弟弟去年夏天試了游泳，馬上就迷上了；現在他每個週末都去游泳。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 475, "question": "Grandpa and Grandma have been married for fifty years. Grandpa has never ______ Grandma; he loves only her.", "options": ["taken in", "kept in touch with", "cheered for", "cheated on"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) cheated on\n【用語】cheat on + 人 (v.phr.)：對（人）不忠\n【中譯】爺爺和奶奶已經結婚五十年了。爺爺從來沒有對奶奶不忠；他只愛她一個人。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 476, "question": "Mom was too tired to cook, so we ______ at a restaurant near our home.", "options": ["took care of the baby", "ate out", "made a sound", "went whale-watching"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) ate out\n【用語】eat out (v.phr.)：在外面吃\n【中譯】媽媽太累了沒辦法煮飯，所以我們在家附近的餐廳外食。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 477, "question": "Don't blame Jack for the broken window; he was at home all day, so he ______.", "options": ["asked his dad for help", "had nothing to do with it", "gave way to it", "made a mess"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) had nothing to do with it\n【用語】have nothing to do with + N (v.phr.)：與…毫無關係\n【中譯】別為了破掉的窗戶責怪傑克；他整天都在家，所以這件事跟他毫無關係。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 478, "question": "Your hair is too long, so you should ______ before school photo day.", "options": ["look at it from another angle", "do the laundry", "get a haircut", "set out the chairs"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) get a haircut\n【用語】get a haircut (v.phr.)：剪頭髮\n【中譯】你的頭髮太長了，所以你應該在學校拍照日之前去剪頭髮。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 479, "question": "Babies cannot do anything by themselves, so they ______ for everything.", "options": ["make an excuse", "laugh at their parents", "can't help laughing", "depend on their parents"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) depend on their parents\n【用語】depend on + 人/物 (v.phr.)：依賴\n【中譯】嬰兒自己什麼都不會做，所以他們凡事都依賴父母。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 480, "question": "We have to move this big sofa because it ______ in our small living room.", "options": ["has a fever", "plays a game", "watches us closely", "takes up too much space"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) takes up too much space\n【用語】take up + N (v.phr.)：佔據（空間、時間）\n【中譯】我們得把這張大沙發搬走，因為它在我們的小客廳裡佔了太多空間。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 481, "question": "After the party, we ______ the messy living room together.", "options": ["jumped over", "had experience in", "put away", "cleared up"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) cleared up\n【用語】clear up + N (v.phr.)：清理\n【中譯】派對結束後，我們一起把凌亂的客廳清理乾淨。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 482, "question": "My brother is sixteen, but he still ______ a little kid.", "options": ["time goes by", "lives on", "acts like", "figures out"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) acts like\n【用語】act like + N (v.phr.)：表現得像……\n【中譯】我哥哥十六歲了，但他還是表現得像個小孩子。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 483, "question": "Taking the MRT can help you ______ because there are no traffic jams.", "options": ["push yourself", "run after the bus", "catch a cold", "save time"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) save time\n【用語】save time (v.phr.)：省時間\n【中譯】搭捷運可以幫你省時間，因為沒有塞車。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 484, "question": "Grandpa is very sick in the hospital, so every night we ______.", "options": ["laugh at him", "pray for him", "keep pace with him", "hold a party"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) pray for him\n【用語】pray for + 人 (v.phr.)：為…祈禱\n【中譯】爺爺病得很重住在醫院，所以我們每天晚上都為他祈禱。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 485, "question": "During lunch break, I like to ______ about our favorite movies.", "options": ["keep up with my classmates", "chat with my classmates", "fall asleep", "cut costs"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) chat with my classmates\n【用語】chat with + 人 (v.phr.)：和…聊天\n【中譯】午休時間，我喜歡和同學聊我們最喜歡的電影。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 486, "question": "In front of the whole team, the coach ______, saying Leo was lazy and slow.", "options": ["took a pop at Leo", "shut up", "shook hands with Leo", "cheered for Leo"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) took a pop at Leo\n【用語】take a pop at sb (v.phr.)：當眾批評某人\n【中譯】教練在全隊面前當眾批評里歐，說他又懶又慢。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 487, "question": "Mr. Lin explained the math problem twice, but I still didn't ______.", "options": ["take my time", "get his point", "stay with him", "pay the bill"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) get his point\n【用語】get + N (v.phr.)：理解某事\n【中譯】林老師把這道數學題解釋了兩次，但我還是不懂他的意思。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 488, "question": "After school, my little sister likes to ______ in the yard.", "options": ["put on weight", "go from bad to worse", "pull out a tooth", "play with our puppy"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) play with our puppy\n【用語】play with + 人 (v.phr.)：和…一起玩\n【中譯】放學後，我妹妹喜歡在院子裡和我們的小狗一起玩。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 489, "question": "The bus is shaking a lot, so please ______.", "options": ["hold on to the handle", "turn to the police", "devote your life to music", "make a wish"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) hold on to the handle\n【用語】hold on to + N (v.phr.)：緊抓住、堅持\n【中譯】公車晃得很厲害，所以請緊抓住把手。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 490, "question": "On her first day at the new school, Kelly ______, and they had lunch together.", "options": ["stayed up", "made friends with a girl in her class", "went abroad", "took a shower"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) made friends with a girl in her class\n【用語】make friends with + 人 (v.phr.)：和…交朋友\n【中譯】凱莉在新學校的第一天就和班上一個女生交了朋友，她們還一起吃午餐。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 491, "question": "Mr. Wang's family is poor, so he works two jobs to ______.", "options": ["kill time", "give out candy", "share a lot in common", "make ends meet"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) make ends meet\n【用語】make ends meet (v.phr.)：維持生計；勉強維生\n【中譯】王先生家裡很窮，所以他做兩份工作來維持生計。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 492, "question": "Tim couldn't open the box with his hands, so in the end he ______ using a hammer.", "options": ["complained about", "backed up", "resorted to", "barked at"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) resorted to\n【用語】resort to + N/V-ing (v.phr.)：訴諸於\n【中譯】提姆用手打不開盒子，所以最後只好訴諸於用鐵鎚。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 493, "question": "Ken promised to help me move, and he ______ by coming on time.", "options": ["kept his word", "called me names", "made a speech", "let me down"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) kept his word\n【用語】keep one's word (v.phr.)：遵守諾言\n【中譯】肯答應要幫我搬家，而他準時來了，遵守了他的諾言。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 494, "question": "The police asked the thief to ______ the stolen money.", "options": ["bring up", "show off", "hand over", "knock down"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) hand over\n【用語】hand over + N (v.phr.)：交出、移交\n【中譯】警察要求小偷交出偷來的錢。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 495, "question": "It's too dark in the room, so could you please ______?", "options": ["turn on the light", "ask the teacher for advice", "turn down the volume", "take the lead"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) turn on the light\n【用語】turn on + N (v.phr.)：打開（電器、開關）\n【中譯】房間裡太暗了，可以請你把燈打開嗎？", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 496, "question": "To improve her English, Amy ______ every day.", "options": ["stands up", "takes a nap", "makes up excuses", "makes efforts to read English books"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) makes efforts to read English books\n【用語】make efforts to + VR (v.phr.)：努力（做…）；辛勞\n【中譯】為了提升英文能力，艾咪每天都努力閱讀英文書。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 497, "question": "Can I ______ your new phone? It looks so cool!", "options": ["reach", "throw away", "take a look at", "think through"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) take a look at\n【用語】take a look at + N (v.phr.)：看一下，瞧一瞧\n【中譯】我可以看一下你的新手機嗎？它看起來好酷！", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 498, "question": "I ______ in the third question, so I got only 95 on the math test.", "options": ["lived with my grandma", "took a bath", "made a mistake", "listened to music"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) made a mistake\n【用語】make a mistake (v.phr.)：犯錯\n【中譯】我在第三題犯了錯，所以數學考試只拿到95分。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 499, "question": "My dad ______ every morning, so he is very healthy.", "options": ["catches a cold", "makes it a rule to jog", "stays up late", "enjoys himself"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) makes it a rule to jog\n【用語】make it a rule to + VR (v.phr.)：習慣做…\n【中譯】我爸爸習慣每天早上慢跑，所以他非常健康。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 500, "question": "I'm in a bad mood, so please ______ for a while.", "options": ["leave me alone", "communicate with me", "go through my notes", "cut it off"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) leave me alone\n【用語】leave + 人 + alone (v.phr.)：讓某人一個人靜一靜；別煩某人\n【中譯】我心情不好，所以請讓我一個人靜一靜。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 501, "question": "This small island ______ thousands of sea birds.", "options": ["is home to", "cuts down", "makes fun of", "complains about"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) is home to\n【用語】be home to + N (v.phr.)：是……的家園、……的大本營\n【中譯】這座小島是數千隻海鳥的家園。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 502, "question": "Sorry, I can't ______ at your party. My mom wants me home by eight.", "options": ["go to the gym", "take notes", "do business", "stay long"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) stay long\n【用語】stay long (v.phr.)：停留很久\n【中譯】抱歉，我不能在你的派對停留很久。我媽媽要我八點前到家。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 503, "question": "We waited for Tom at the station for an hour, but he never ______.", "options": ["pulled together", "went on", "felt sleepy", "turned up"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) turned up\n【用語】turn up (v.phr.)：出現\n【中譯】我們在車站等了湯姆一個小時，但他始終沒有出現。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 504, "question": "After school, the students ______ the library to study.", "options": ["made up", "headed for", "got over", "turned off"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) headed for\n【用語】head for + 地方 (v.phr.)：前往\n【中譯】放學後，學生們前往圖書館讀書。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 505, "question": "If you get lost in the mall, just ______ and wait for me.", "options": ["stay put", "pick up the room", "fall over", "make faces"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) stay put\n【用語】stay put (v.phr.)：原地不動\n【中譯】如果你在購物中心迷路了，就待在原地不要動，等我。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 506, "question": "Grandpa learned to use a smartphone because he wants to ______.", "options": ["break in", "miss the train", "die out", "catch up with the times"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) catch up with the times\n【用語】catch up with the times (v.phr.)：跟上時代\n【中譯】爺爺學用智慧型手機，因為他想跟上時代。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 507, "question": "My brother works at a fast-food restaurant after school to ______.", "options": ["cut the paper", "make money", "lose his way", "have a headache"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) make money\n【用語】make money (v.phr.)：賺錢\n【中譯】我哥哥放學後在速食店打工賺錢。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 508, "question": "Eggs are more expensive now. The price of eggs ______ last month.", "options": ["went up", "took place", "broke up", "slowed down"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) went up\n【用語】go up (v.phr.)：上升、上漲\n【中譯】現在蛋比較貴了。蛋價上個月上漲了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 509, "question": "To get money for a new phone, my brother ______.", "options": ["took a day off", "replaced his old bike with a new one", "minded his behavior", "sold his old bike for NT$3,000"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) sold his old bike for NT$3,000\n【用語】buy/sell + N + for + 錢 (v.phr.)：用多少錢買／賣某物\n【中譯】為了籌錢買新手機，我哥哥用新台幣三千元賣掉了他的舊腳踏車。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 510, "question": "The question was so hard that everyone in the class ______ it, so the teacher told us the answer.", "options": ["lived on", "led to", "had no answer to", "graduated from"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) had no answer to\n【用語】have no answer to + N (v.phr.)：對⋯⋯沒有答案；答不出\n【中譯】這個問題太難了，全班都答不出來，所以老師告訴我們答案。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 511, "question": "I can't hear the music. Can you ______ the radio, please?", "options": ["begin with", "go along with", "turn up", "account for"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) turn up\n【用語】turn up + N (v.phr.)：開大（聲音）\n【中譯】我聽不到音樂。可以請你把收音機開大聲一點嗎？", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 512, "question": "The big red sign on the door ______, so I stopped to read it.", "options": ["caught up with me", "came across me", "made faces at me", "drew my attention"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) drew my attention\n【用語】draw one's attention (v.phr.)：吸引某人的注意\n【中譯】門上那個大紅色的告示吸引了我的注意，所以我停下來看。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 513, "question": "We are so excited. We are ______ visiting the zoo on the school trip next Friday.", "options": ["catching up with", "coming across", "contributing to", "looking forward to"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) looking forward to\n【用語】look forward to + N (v.phr.)：期待……（名詞）\n【中譯】我們好興奮。我們很期待下週五校外教學去參觀動物園。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 514, "question": "It's very hot in here. Please ______.", "options": ["lose weight", "settle down", "cut in the line", "leave the window open"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) leave the window open\n【用語】leave + 物 + adj. (v.phr.)：讓某物保持某狀態（形容詞）\n【中譯】這裡面好熱。請讓窗戶開著。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 515, "question": "Even when the kids were very noisy, the teacher ______ and spoke softly.", "options": ["took medicine", "took her chance", "walked up the stairs", "kept her cool"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) kept her cool\n【用語】keep one's cool (v.phr.)：保持冷靜\n【中譯】即使孩子們很吵，老師仍保持冷靜，輕聲說話。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 516, "question": "Mom gets up at six every morning to ______ for us. Today we are having eggs and toast.", "options": ["go to the gym", "face the difficulty", "make breakfast", "cross the street"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) make breakfast\n【用語】make breakfast/lunch/dinner (v.phr.)：做早餐／午餐／晚餐\n【中譯】媽媽每天早上六點起床為我們做早餐。今天我們吃蛋和吐司。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 517, "question": "A: We're going to play basketball after school. Do you want to join us?\nB: ______! I love basketball.", "options": ["Take care", "Line up", "Take a seat", "Count me in"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) Count me in\n【用語】count me in (v.phr.)：算我一份\n【中譯】A：我們放學後要去打籃球。你要加入嗎？\nB：算我一份！我很愛打籃球。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 518, "question": "Amy ______ her father because he is kind and always helps others.", "options": ["results in", "dies of", "pushes up", "looks up to"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) looks up to\n【用語】look up to + 人 (v.phr.)：尊敬，仰慕\n【中譯】艾咪很尊敬她的父親，因為他很善良，而且總是幫助別人。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 519, "question": "Hurry up! We need to ______ now, or it will leave without us.", "options": ["look happy", "return the favor", "get on the bus", "take a chance"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) get on the bus\n【用語】get on the bus/train/plane/MRT/gondola (v.phr.)：上公車／火車／飛機／捷運／纜車（可站立）\n【中譯】快一點！我們現在得上公車，不然它會丟下我們開走。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 520, "question": "Grandpa has a small farm in the countryside. He grows vegetables and ______ there.", "options": ["comes to his mind", "pulls out", "gets out of the way", "lives a simple life"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) lives a simple life\n【用語】live a + adj. + life (v.phr.)：過著⋯⋯的生活\n【中譯】爺爺在鄉下有一座小農場。他在那裡種菜，過著簡單的生活。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 521, "question": "I was all sweaty after the basketball game, so I ______ right away.", "options": ["gave directions", "took notes", "had a picnic", "took a shower"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) took a shower\n【用語】take a shower (v.phr.)：淋浴\n【中譯】籃球比賽後我全身是汗，所以我馬上去淋浴。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 522, "question": "You feel very hot. Let me ______ to see if you have a fever.", "options": ["take your temperature", "surf the Internet", "go down", "take it seriously"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) take your temperature\n【用語】take temperature (v.phr.)：量體溫\n【中譯】你摸起來很燙。讓我幫你量體溫，看看你是不是發燒了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 523, "question": "We didn't know the new word \"cozy,\" so Ms. Lin ______.", "options": ["defined it as \"warm and comfortable\"", "put the plan into practice", "made a good shot", "took a holiday"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) defined it as \"warm and comfortable\"\n【用語】define + N + as + N (v.phr.)：將……定義為\n【中譯】我們不認識新單字「cozy」，所以林老師把它定義為「溫暖又舒適」。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 524, "question": "It's sunny today. Let's ______ in the park and eat sandwiches on the grass.", "options": ["fall over", "go on a picnic", "cross the street", "make up our minds"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) go on a picnic\n【用語】go on a picnic (v.phr.)：去野餐\n【中譯】今天天氣晴朗。我們去公園野餐，在草地上吃三明治吧。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 525, "question": "On New Year's Eve, people ______ fireworks by the river.", "options": ["graduate from", "depend on", "make fun of", "set off"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) set off\n【用語】set off + N (v.phr.)：使爆炸、燃放（煙火）\n【中譯】跨年夜時，人們在河邊施放煙火。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 526, "question": "After years of hard work, Lisa finally ______. She is a doctor now.", "options": ["made a U-turn", "woke up", "realized her dream", "took a walk"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) realized her dream\n【用語】realize one's dream (v.phr.)：實現夢想\n【中譯】經過多年的努力，麗莎終於實現了夢想。她現在是一名醫生。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 527, "question": "I have to finish this report by Friday, so I'm working hard to ______.", "options": ["meet the deadline", "nod off", "die out", "have a lot in common"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) meet the deadline\n【用語】meet the deadline (v.phr.)：趕上期限；趕上截止日期\n【中譯】我必須在星期五前完成這份報告，所以我正努力趕上截止日期。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 528, "question": "Everyone in our class ______ because she always helps others.", "options": ["regards Amy as a good friend", "leaves Amy's books behind", "breaks up", "feels sleepy"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) regards Amy as a good friend\n【用語】regard + N + as + N (v.phr.)：認為……是……\n【中譯】我們班上每個人都把艾咪當作好朋友，因為她總是幫助別人。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 529, "question": "Playing with three little kids all day really ______ Grandma.", "options": ["thought about", "wore out", "made use of", "had beef with"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) wore out\n【用語】wear out + 人 (v.phr.)：使筋疲力盡、累垮\n【中譯】和三個小孩玩了一整天，真的把奶奶累壞了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 530, "question": "I was near your house this afternoon, so I ______ to say hi.", "options": ["pulled out", "lost weight", "had a headache", "dropped by"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) dropped by\n【用語】drop by (v.phr.)：順便來訪\n【中譯】我今天下午在你家附近，所以順道過來打聲招呼。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 531, "question": "I ______ late last night to watch the baseball game, so I'm very tired now.", "options": ["made faces", "got out of the way", "took place", "stayed up"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) stayed up\n【用語】stay up (v.phr.)：熬夜\n【中譯】我昨晚熬夜看棒球比賽，所以現在很累。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 532, "question": "Go straight two blocks and ______ at the bookstore. The bank is next to it.", "options": ["take medicine", "make a good shot", "turn right", "nod off"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) turn right\n【用語】turn right (v.phr.)：向右轉\n【中譯】直走兩個路口，在書店那裡右轉。銀行就在書店旁邊。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 533, "question": "My new shoes were on sale. I only ______.", "options": ["paid NT$500 for them", "let my voice be heard", "came along", "showed my true colors"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) paid NT$500 for them\n【用語】pay + 錢 + for + N (v.phr.)：付多少錢買…\n【中譯】我的新鞋在特價。我只花了新台幣五百元買它們。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 534, "question": "Everyone should ______. For example, never drive after drinking.", "options": ["have a dream", "take a holiday", "fit in", "follow the law"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) follow the law\n【用語】follow the law (v.phr.)：遵守法律\n【中譯】每個人都應該遵守法律。例如，絕對不要酒後開車。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 535, "question": "We finished dinner at the restaurant, and Dad ______ with his credit card.", "options": ["cut the paper", "paid the bill", "walked up the stairs", "got out of the way"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) paid the bill\n【用語】pay the bill (v.phr.)：付帳\n【中譯】我們在餐廳吃完晚餐，爸爸用信用卡付了帳。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 536, "question": "I want to ______ my bad habit of eating too much candy.", "options": ["hand out", "get rid of", "leave for", "live on"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) get rid of\n【用語】get rid of + N (v.phr.)：擺脫\n【中譯】我想擺脫吃太多糖果的壞習慣。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 537, "question": "Our river is getting dirty. We must ______ to clean it before it's too late.", "options": ["come along", "take pictures of it", "turn up the heater", "take action"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) take action\n【用語】take action (v.phr.)：採取行動\n【中譯】我們的河川越來越髒了。我們必須在太遲之前採取行動把它清乾淨。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 538, "question": "Mom ______ and gave one to each of us.", "options": ["lived on the cookie", "broke the cookie into four pieces", "pulled our leg", "gave directions"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) broke the cookie into four pieces\n【用語】break + N + into + N (v.phr.)：破成…；分成…\n【中譯】媽媽把餅乾分成四塊，給我們每人一塊。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 539, "question": "In the last second of the game, Kevin ______, and our team won 21 to 20.", "options": ["scored a point", "broke in", "took a seat", "made up his mind"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) scored a point\n【用語】score a point (v.phr.)：得一分\n【中譯】在比賽最後一秒，凱文得了一分，我們隊以21比20獲勝。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 540, "question": "When I called her name, Mary ______ and smiled at me.", "options": ["turned around", "broke up", "surfed the Internet", "did her best"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) turned around\n【用語】turn around (v.phr.)：轉身\n【中譯】我叫瑪莉的名字時，她轉過身來對我微笑。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 541, "question": "The soup is cold. Let me ______ the soup for you in the microwave.", "options": ["lead to", "heat up", "account for", "figure out"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) heat up\n【用語】heat up + N (v.phr.)：加熱\n【中譯】湯冷掉了。讓我用微波爐幫你把湯加熱。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 542, "question": "This restaurant changed its menu to ______ young people's tastes.", "options": ["cut down", "cater to", "graduate from", "die of"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) cater to\n【用語】cater to + N (v.phr.)：迎合\n【中譯】這家餐廳改了菜單來迎合年輕人的口味。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 543, "question": "Wear a raincoat. It will ______.", "options": ["wake up", "take a seat", "prevent you from getting wet", "subject you to danger"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) prevent you from getting wet\n【用語】prevent + N + from + V-ing (v.phr.)：阻止……、避免\n【中譯】穿上雨衣。它可以防止你被淋濕。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 544, "question": "The forest was dark, but we used a map to ______ it.", "options": ["find the way through", "result in", "live on", "complain about"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) find the way through\n【用語】find the way through + N (v.phr.)：找到出路\n【中譯】森林裡很暗，但我們用地圖找到了穿越森林的路。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 545, "question": "I want to be a pilot when I ______.", "options": ["fall over", "grow up", "don't get my way", "have a headache"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) grow up\n【用語】grow up (v.phr.)：長大、成長\n【中譯】我長大後想當飛行員。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 546, "question": "I can't watch TV now. I need to ______. Ms. Lin will check our workbooks tomorrow.", "options": ["put on a play", "go for a ride", "report bullying to the teacher", "do homework"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) do homework\n【用語】do homework (v.phr.)：做作業\n【中譯】我現在不能看電視。我需要做作業。林老師明天會檢查我們的作業簿。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 547, "question": "The sea was so blue and beautiful that we sat on the beach for an hour to ______.", "options": ["take in the view", "take her place", "pick up Amy", "do our shopping"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) take in the view\n【用語】take in the view (v.phr.)：欣賞風景\n【中譯】海又藍又美，所以我們在沙灘上坐了一個小時欣賞風景。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 548, "question": "Tim saw a cup of water on the table. He ______ and drank it.", "options": ["stood in my way", "reached out for it", "took off", "pulled away"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) reached out for it\n【用語】reach out for + 物 (v.phr.)：伸手拿…\n【中譯】提姆看到桌上有一杯水。他伸手拿起它並喝掉了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 549, "question": "Mom ______ to make my birthday cake perfect. She worked on it all afternoon.", "options": ["kept fit", "took a rest", "took pains", "wore out her shoes"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) took pains\n【用語】take pains to + VR (v.phr.)：費盡心力（做…）；辛苦\n【中譯】媽媽費盡心力把我的生日蛋糕做得很完美。她做了一整個下午。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 550, "question": "What ______ your bike? The front wheel is broken.", "options": ["listened to", "belonged to", "looked like", "happened to"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) happened to\n【用語】happen to + 人/物 (v.phr.)：發生\n【中譯】你的腳踏車發生了什麼事？前輪壞了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 551, "question": "It's sunny today, so Mom wants to ______ outside to dry.", "options": ["hang the clothes", "clean out the closet", "brush her teeth", "give me an angry look"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) hang the clothes\n【用語】hang the clothes (v.phr.)：掛衣服\n【中譯】今天天氣晴朗，所以媽媽想把衣服掛在外面晾乾。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 552, "question": "There are glass cups in this box. Please ______.", "options": ["tell the truth", "kill time", "have fun", "handle it with care"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) handle it with care\n【用語】handle + N + with care (v.phr.)：小心處理（常見於包裹標示）\n【中譯】這個箱子裡有玻璃杯。請小心處理。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 553, "question": "Bye, Amy! I hope you ______ at the party tonight. There will be lots of games and food!", "options": ["pick up your bag", "have a good time", "make a choice", "dream about it"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) have a good time\n【用語】have a good time (v.phr.)：玩得愉快\n【中譯】再見，艾咪！希望你今晚在派對上玩得愉快。會有很多遊戲和食物！", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 554, "question": "I didn't want to join the basketball team at first, but my friends ______. Now I play every day.", "options": ["turned down the radio", "took off", "pulled away", "talked me into it"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) talked me into it\n【用語】talk + 人 + into + V-ing (v.phr.)：說服（某人做…）\n【中譯】我一開始不想加入籃球隊，但我的朋友們說服了我。現在我每天都打球。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 555, "question": "My little brother hates carrots, but Mom can always ______. She is really good at it.", "options": ["get him to eat them", "check up", "have fun", "keep in touch"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) get him to eat them\n【用語】get + 人 + to + VR (v.phr.)：使某人去做……\n【中譯】我弟弟討厭紅蘿蔔，但媽媽總是能讓他吃下去。她真的很擅長這件事。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 556, "question": "The twin sisters look the same. I can't ______ between them.", "options": ["make coffee", "record my life", "tell the difference", "have fun"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) tell the difference\n【用語】tell the difference (v.phr.)：分辨差異\n【中譯】那對雙胞胎姊妹長得一模一樣。我分辨不出她們之間的差異。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 557, "question": "The police officer said, \"Catching thieves is not easy, but I must ______.\"", "options": ["do my job", "go off", "think of a song", "take a picture"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) do my job\n【用語】do one's job (v.phr.)：做工作；盡本分\n【中譯】警察說：「抓小偷並不容易，但我必須盡我的本分。」", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 558, "question": "Grandpa lives alone in the country, but he can ______ without our help.", "options": ["get along", "come on in", "pull away", "go off"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) get along\n【用語】get along (v.phr.)：生活過得去；應付\n【中譯】爺爺獨自住在鄉下，但他不需要我們的幫忙也能過得去。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 559, "question": "Don't leave yet! ______ for a while, and we can eat some cake together.", "options": ["Stick around", "Keep away from us", "Have a pen", "Pull yourself together"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) Stick around\n【用語】stick around (v.phr.)：待在附近；留下來\n【中譯】先別走！留下來一會兒，我們可以一起吃點蛋糕。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 560, "question": "Can I ______? I need some help with my math homework.", "options": ["have a great time", "ask you a favor", "pull up my socks", "kill time"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) ask you a favor\n【用語】ask + 人 + a favor (v.phr.)：請……幫個忙\n【中譯】我可以請你幫個忙嗎？我的數學作業需要一些幫助。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 561, "question": "Ben thinks math is not important, so he doesn't ______.", "options": ["take math seriously", "keep a diary", "beat the clock", "make up"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) take math seriously\n【用語】take + N + seriously (v.phr.)：認真看待\n【中譯】班認為數學不重要，所以他不認真看待數學。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 562, "question": "At first Dad said no to a new phone, but after I asked him ten times, he finally ______.", "options": ["passed by", "gave in", "took a picture", "took my breath away"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) gave in\n【用語】give in (to + N) (v.phr.)：讓步、屈服\n【中譯】一開始爸爸不答應買新手機，但在我問了他十次之後，他終於讓步了。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 563, "question": "Before you go to bed, don't forget to ______.", "options": ["brush your teeth", "range from one to ten", "give up your seat", "order your sister to sit down"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) brush your teeth\n【用語】brush one's teeth (v.phr.)：刷牙\n【中譯】睡覺前，別忘了刷牙。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 564, "question": "Thousands of fans came to the stadium to ______. They shouted, \"Go, Brothers, go!\"", "options": ["point at the sky", "celebrate the holiday with cake", "pack up", "root for their team"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) root for their team\n【用語】root for + 人 (v.phr.)：為……聲援、加油\n【中譯】成千上萬的球迷來到球場為他們的球隊加油。他們大喊：「兄弟，加油！」", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 565, "question": "I'm sorry I called you stupid. I want to ______.", "options": ["keep fit", "take back my words", "have fun", "come on in"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) take back my words\n【用語】take back + N (v.phr.)：取回、收回\n【中譯】對不起我說你很笨。我想收回我的話。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 566, "question": "There are so many cakes in the shop, and they all look good. I can't ______.", "options": ["run over them", "run a food stand", "make a choice", "send for the doctor"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) make a choice\n【用語】make a choice (v.phr.)：做選擇\n【中譯】店裡有好多蛋糕，而且看起來都很好吃。我沒辦法做選擇。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 567, "question": "Our car ______ on the highway, so we had to call for help.", "options": ["paid off the money", "did its shopping", "passed away", "broke down"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) broke down\n【用語】break down (v.phr.)：（機器）故障、失靈\n【中譯】我們的車在高速公路上故障了，所以我們必須打電話求救。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 568, "question": "I forgot to bring my pen to the test, so I ______.", "options": ["pulled away", "asked Amy for one", "turned fifteen", "took a look at the clock"], "answer": 1, "answerLabel": "B", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(B) asked Amy for one\n【用語】ask + 人 + for + N (v.phr.)：向某人要某物\n【中譯】我忘了帶筆來考試，所以我向艾咪要了一支。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 569, "question": "The little boy ______ and said, \"Look! There's a big bird up there!\"", "options": ["cared for his mom", "learned English from his dad", "kept fit", "pointed at the tree"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) pointed at the tree\n【用語】point at + 人/物 (v.phr.)：指著\n【中譯】小男孩指著那棵樹說：「看！上面有一隻大鳥！」", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 570, "question": "Your room is so dirty! Please ______ before dinner.", "options": ["clean it up", "protect it from the rain", "take a guess", "make up a team"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) clean it up\n【用語】clean up + N (v.phr.)：打掃、整理\n【中譯】你的房間好髒！請在晚餐前把它打掃乾淨。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 571, "question": "The heavy rain ______, so we played board games at home all day.", "options": ["turned fifteen", "kept fit", "kept us from going out", "beat the clock"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) kept us from going out\n【用語】keep (+ 人) from + V-ing (v.phr.)：使不能、避免\n【中譯】大雨讓我們無法出門，所以我們整天在家玩桌遊。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 572, "question": "Dad is very sleepy this morning, so I'll ______ for him. He likes it with milk.", "options": ["take a guess", "change my mind", "get back", "make coffee"], "answer": 3, "answerLabel": "D", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(D) make coffee\n【用語】make coffee (v.phr.)：泡咖啡\n【中譯】爸爸今天早上很睏，所以我會幫他泡咖啡。他喜歡加牛奶。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 573, "question": "The bus was late, so I read a comic book to ______.", "options": ["kill time", "appeal to people to save water", "keep a diary", "make up"], "answer": 0, "answerLabel": "A", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(A) kill time\n【用語】kill time (v.phr.)：消磨時間\n【中譯】公車誤點了，所以我看漫畫來消磨時間。", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 574, "question": "Dad just bought a new car. Let's ______ around the lake this afternoon!", "options": ["pop the question", "get into bed", "go for a ride", "clean up the kitchen"], "answer": 2, "answerLabel": "C", "source": "動詞片語 Verb Phrases｜動詞片語 Verb Phrases", "explanation": "【答案】(C) go for a ride\n【用語】go for a ride (v.phr.)：去兜風\n【中譯】爸爸剛買了一輛新車。我們今天下午去湖邊兜風吧！", "explanationSource": "supplemental", "section": "動詞片語 Verb Phrases"}, {"id": 575, "question": "We ______ the news that our favorite shop closed so suddenly.", "options": ["were surprised at", "were rich in", "were in the shape of", "were proud of"], "answer": 0, "answerLabel": "A", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(A) were surprised at\n【用語】be surprised at + N (adj.phr.)：對……感到驚訝\n【中譯】我們對我們最喜歡的店突然關門的消息感到驚訝。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 576, "question": "Mike was very tired, but he ______ help me carry the heavy boxes because he is a kind boy.", "options": ["was willing to", "was supposed to", "was used to", "was about to"], "answer": 0, "answerLabel": "A", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(A) was willing to\n【用語】be willing to + VR (adj.phr.)：願意\n【中譯】Mike很累，但因為他是個善良的男孩，他願意幫我搬重箱子。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 577, "question": "We didn't have a map, so we ______ in the big city.", "options": ["were wild", "got better", "got lost", "were in good order"], "answer": 2, "answerLabel": "C", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(C) got lost\n【用語】get lost (adj.phr.)：迷路\n【中譯】我們沒有地圖，所以我們在大城市裡迷路了。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 578, "question": "This big knife ______ cutting bread, not meat.", "options": ["is bored with", "is used for", "gets excited about", "is scared of"], "answer": 1, "answerLabel": "B", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(B) is used for\n【用語】物 + be used for + N/V-ing (adj.phr.)：某物被用來做…\n【中譯】這把大刀是用來切麵包的，不是用來切肉的。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 579, "question": "We ______ when the magician pulled a rabbit out of his empty hat.", "options": ["were under pressure", "were amazed", "were broke", "were grounded"], "answer": 1, "answerLabel": "B", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(B) were amazed\n【用語】be amazed (adj.phr.)：感到驚奇、驚訝\n【中譯】當魔術師從他的空帽子裡拉出一隻兔子時，我們感到很驚奇。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 580, "question": "You are still in your pajamas, so hurry up and ______ for school.", "options": ["get dressed", "get worse", "get hurt", "get better"], "answer": 0, "answerLabel": "A", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(A) get dressed\n【用語】get dressed (adj.phr.)：穿好衣服\n【中譯】你還穿著睡衣，所以快點穿好衣服準備上學。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 581, "question": "My brother ______ space, so he reads books about stars and planets every night.", "options": ["is full of", "is frightened of", "is interested in", "is different from"], "answer": 2, "answerLabel": "C", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(C) is interested in\n【用語】be interested in + N/V-ing (adj.phr.)：對……感興趣\n【中譯】我哥哥對太空很感興趣，所以他每天晚上都讀有關星星和行星的書。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 582, "question": "The students ______ the good news that there is no homework this weekend.", "options": ["were happy about", "were absent from", "were used to", "were made of"], "answer": 0, "answerLabel": "A", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(A) were happy about\n【用語】be happy/glad about + N (adj.phr.)：為…高興\n【中譯】學生們為這個週末沒有作業的好消息感到高興。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 583, "question": "Grandpa ______ gardening, so he works in his garden every day.", "options": ["is fond of", "is absent from", "is short of", "is called"], "answer": 0, "answerLabel": "A", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(A) is fond of\n【用語】be fond of + N/V-ing (adj.phr.)：喜愛、喜歡\n【中譯】爺爺很喜愛園藝，所以他每天都在花園裡工作。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 584, "question": "Lisa ______ school activities; she joins the music club, the art club, and the basketball team.", "options": ["is junior to", "is made in", "is active in", "is free of"], "answer": 2, "answerLabel": "C", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(C) is active in\n【用語】be active in + N/V-ing (adj.phr.)：在…很積極主動\n【中譯】Lisa在學校活動中很積極主動；她參加了音樂社、美術社和籃球隊。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 585, "question": "My twin sister and I look alike, but her hobbies ______ mine.", "options": ["are made from", "are sorry about", "are popular with", "are different from"], "answer": 3, "answerLabel": "D", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(D) are different from\n【用語】be different from + N (adj.phr.)：和……不同\n【中譯】我和我的雙胞胎姊姊長得很像，但她的嗜好和我的不同。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 586, "question": "Many people cried because they ______ the sad story of the old dog.", "options": ["were moved by", "were made in", "were serious about", "were seen as"], "answer": 0, "answerLabel": "A", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(A) were moved by\n【用語】be moved by + N (adj.phr.)：被……感動\n【中譯】許多人哭了，因為他們被那隻老狗的悲傷故事感動了。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 587, "question": "Our school ______ the MRT station, so we can walk there in two minutes.", "options": ["is angry with", "is proud of", "is sure of", "is close to"], "answer": 3, "answerLabel": "D", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(D) is close to\n【用語】be close to + N (adj.phr.)：接近…\n【中譯】我們學校很接近捷運站，所以我們走兩分鐘就能到那裡。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 588, "question": "The singer's voice was so beautiful that everyone in the hall ______.", "options": ["was embarrassed", "was in danger", "was blown away", "was on a diet"], "answer": 2, "answerLabel": "C", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(C) was blown away\n【用語】be blown away (adj.phr.)：驚訝不已；大為震撼\n【中譯】那位歌手的歌聲如此美妙，以至於大廳裡的每個人都大為震撼。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 589, "question": "The heavy rain ______ the car accident on the highway this morning.", "options": ["was fond of", "was aware of", "was satisfied with", "was responsible for"], "answer": 3, "answerLabel": "D", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(D) was responsible for\n【用語】be responsible for + N (adj.phr.)：造成……的原因\n【中譯】大雨是今天早上高速公路上那場車禍的原因。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 590, "question": "Little Tommy ______ everything around him, so he always asks, \"Why?\"", "options": ["is made of", "is late for", "is popular with", "is curious about"], "answer": 3, "answerLabel": "D", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(D) is curious about\n【用語】be curious about + N (adj.phr.)：對……感到好奇\n【中譯】小Tommy對他周圍的一切都感到好奇，所以他總是問：「為什麼？」", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 591, "question": "I have eaten noodles every day for a month, and I ______ them now.", "options": ["am tired of", "am famous for", "am nervous about", "am junior to"], "answer": 0, "answerLabel": "A", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(A) am tired of\n【用語】be tired of + N/V-ing (adj.phr.)：對……感到厭倦\n【中譯】我已經連續一個月每天吃麵，現在我對麵感到厭倦了。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 592, "question": "I ______ my teacher for her help with my English.", "options": ["am similar to", "am junior to", "am thankful to", "am late for"], "answer": 2, "answerLabel": "C", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(C) am thankful to\n【用語】be thankful to + 人 + for + N (adj.phr.)：為了某事感謝某人\n【中譯】我為了老師在英文上給我的幫助而感謝她。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 593, "question": "Kevin played the same video game every day for months, and finally he ______ it and stopped playing.", "options": ["got married to", "got tired of", "was covered with", "was rich in"], "answer": 1, "answerLabel": "B", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(B) got tired of\n【用語】get tired of + N/V-ing (adj.phr.)：對…感到厭倦\n【中譯】Kevin好幾個月每天都玩同一款電玩，最後他對它感到厭倦，不再玩了。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 594, "question": "Ms. Wang ______ a doctor, and they have two children.", "options": ["is superior to", "is new to", "is tired from", "is married to"], "answer": 3, "answerLabel": "D", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(D) is married to\n【用語】be married to + 人 (adj.phr.)：嫁給…、和…結婚\n【中譯】王小姐嫁給了一位醫生，他們有兩個孩子。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 595, "question": "Ben had a bad cold, so he ______ school yesterday.", "options": ["was dressed in", "was absent from", "was known to", "was aware of"], "answer": 1, "answerLabel": "B", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(B) was absent from\n【用語】be absent from + N (adj.phr.)：缺席\n【中譯】Ben得了重感冒，所以他昨天沒去上學（缺席）。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 596, "question": "My new backpack ______ yours, so I put my name on it to tell them apart.", "options": ["is busy with", "is the same as", "is angry with", "is afraid of"], "answer": 1, "answerLabel": "B", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(B) is the same as\n【用語】be the same as + N (adj.phr.)：和……一樣\n【中譯】我的新背包和你的一樣，所以我在上面寫了名字來區分它們。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 597, "question": "The waiter asked us, \"Are you ______ order now, or do you need more time?\"", "options": ["sure to", "ready to", "likely to", "used to"], "answer": 1, "answerLabel": "B", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(B) ready to\n【用語】be ready to + VR (adj.phr.)：準備好做某事\n【中譯】服務生問我們：「你們準備好要點餐了嗎，還是需要多一點時間？」", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 598, "question": "Jack just moved here last week, so he ______ this town and often asks for directions.", "options": ["is covered with", "is good at", "is new to", "is junior to"], "answer": 2, "answerLabel": "C", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(C) is new to\n【用語】be new to + N (adj.phr.)：對…不熟、沒經驗\n【中譯】Jack上週才搬來這裡，所以他對這個城鎮不熟，常常問路。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 599, "question": "The judges ______ Amy's beautiful singing and gave her first prize.", "options": ["were free of", "were impressed by", "were short of", "were rich in"], "answer": 1, "answerLabel": "B", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(B) were impressed by\n【用語】be impressed by + N (adj.phr.)：對……印象深刻\n【中譯】評審們對Amy美妙的歌聲印象深刻，給了她第一名。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 600, "question": "Mr. Chen has worked at this school for twenty years, so he ______ most of the other teachers.", "options": ["is late for", "is busy with", "is senior to", "is junior to"], "answer": 2, "answerLabel": "C", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(C) is senior to\n【用語】be senior to + 人 (adj.phr.)：比…年長、資深\n【中譯】陳老師在這所學校工作了二十年，所以他比大部分其他老師資深。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 601, "question": "I have studied every night this week, so I ______ tomorrow's math test.", "options": ["am popular with", "am made from", "am ready for", "am similar to"], "answer": 2, "answerLabel": "C", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(C) am ready for\n【用語】be ready for + N (adj.phr.)：為…準備好了\n【中譯】我這週每天晚上都在讀書，所以我已經為明天的數學考試準備好了。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 602, "question": "This bike ______ Taiwan, and it is sold all over the world.", "options": ["was made of", "was made from", "was made in", "was known as"], "answer": 2, "answerLabel": "C", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(C) was made in\n【用語】be made in + 地方 (adj.phr.)：在…地方製造\n【中譯】這輛腳踏車是在台灣製造的，而且銷售到全世界。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 603, "question": "Hot pot ______ my American friend, so I showed him how to cook the meat.", "options": ["is senior to", "is careful about", "is foreign to", "is free of"], "answer": 2, "answerLabel": "C", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(C) is foreign to\n【用語】be foreign to + 人 (adj.phr.)：對……陌生的\n【中譯】火鍋對我的美國朋友來說很陌生，所以我教他怎麼煮肉。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 604, "question": "Taiwan ______ its bubble tea, and many tourists want to try it.", "options": ["is shocked at", "is patient with", "is made from", "is famous for"], "answer": 3, "answerLabel": "D", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(D) is famous for\n【用語】be famous for + N (adj.phr.)：因……聞名\n【中譯】台灣因珍珠奶茶而聞名，許多觀光客都想嚐嚐看。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 605, "question": "This book ______ the history of Taipei, so it is useful for my report.", "options": ["is ready for", "is angry at", "is nervous about", "is related to"], "answer": 3, "answerLabel": "D", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(D) is related to\n【用語】be related to + N (adj.phr.)：與……有關\n【中譯】這本書與台北的歷史有關，所以對我的報告很有用。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 606, "question": "Michael Jordan ______ one of the best basketball players in the world.", "options": ["is bored with", "is worried about", "is known as", "is disgusted with"], "answer": 2, "answerLabel": "C", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(C) is known as\n【用語】be known as + N (adj.phr.)：以……身分聞名\n【中譯】Michael Jordan以世界上最優秀的籃球員之一而聞名。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 607, "question": "It's late, so let's brush our teeth and ______ bed.", "options": ["get ready for", "be afraid of", "be careful about", "be different from"], "answer": 0, "answerLabel": "A", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(A) get ready for\n【用語】get ready for + N / to + VR (adj.phr.)：準備好\n【中譯】很晚了，我們刷牙準備睡覺吧。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 608, "question": "All the students ______ planning the school sports day this year.", "options": ["were touched by", "were similar to", "were in the shape of", "were involved in"], "answer": 3, "answerLabel": "D", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(D) were involved in\n【用語】be involved in + N/V-ing (adj.phr.)：參與\n【中譯】今年所有學生都參與了籌劃學校運動會。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 609, "question": "Dad ______ my little brother because he broke the window with a ball.", "options": ["was senior to", "was dressed in", "got mad at", "was poor at"], "answer": 2, "answerLabel": "C", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(C) got mad at\n【用語】get mad at + 人 (adj.phr.)：對…生氣\n【中譯】爸爸對我弟弟生氣，因為他用球打破了窗戶。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 610, "question": "This small beach ______ only a few local people, so it is quiet and clean.", "options": ["is aware of", "is good at", "is known to", "is shocked at"], "answer": 2, "answerLabel": "C", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(C) is known to\n【用語】be known to + 人 (adj.phr.)：為…所熟知\n【中譯】這個小海灘只為少數當地人所熟知，所以它又安靜又乾淨。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 611, "question": "My sister ______ K-pop; she has hundreds of posters of her favorite singers.", "options": ["is sick of", "is crazy about", "gets bored with", "is sorry for"], "answer": 1, "answerLabel": "B", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(B) is crazy about\n【用語】be crazy about + N/V-ing (adj.phr.)：超級喜愛；為……著迷瘋狂\n【中譯】我姊姊超級喜愛韓國流行音樂；她有好幾百張她最喜歡的歌手的海報。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 612, "question": "I ______ hear that you won first prize in the contest!", "options": ["am sure to", "am about to", "am delighted to", "am able to"], "answer": 2, "answerLabel": "C", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(C) am delighted to\n【用語】be delighted to + VR (adj.phr.)：很高興（做）……\n【中譯】我很高興聽到你在比賽中得了第一名！", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 613, "question": "Eating vegetables and fruit ______ your health.", "options": ["is good for", "is based on", "is sick of", "is late for"], "answer": 0, "answerLabel": "A", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(A) is good for\n【用語】be good for + N (adj.phr.)：對……有益的\n【中譯】吃蔬菜和水果對你的健康有益。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 614, "question": "Mom ______ the mess in my room, so she shouted at me to clean it up right away.", "options": ["was dressed in", "was satisfied with", "was used to", "was angry at"], "answer": 3, "answerLabel": "D", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(D) was angry at\n【用語】be angry at + 事 (adj.phr.)：為某事生氣\n【中譯】媽媽為我房間的髒亂生氣，所以她大聲叫我馬上整理乾淨。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 615, "question": "The customer ______ the food and service, so she gave the restaurant five stars.", "options": ["was shocked at", "was satisfied with", "was in search of", "was absent from"], "answer": 1, "answerLabel": "B", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(B) was satisfied with\n【用語】be satisfied with + N (adj.phr.)：滿意…\n【中譯】那位顧客對食物和服務很滿意，所以她給這家餐廳五顆星。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 616, "question": "Tainan ______ its delicious traditional snacks, like shrimp rolls and milkfish soup.", "options": ["is sorry about", "is married to", "is similar to", "is known for"], "answer": 3, "answerLabel": "D", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(D) is known for\n【用語】be known for + N (adj.phr.)：因……而聞名\n【中譯】台南因美味的傳統小吃而聞名，像是蝦捲和虱目魚湯。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 617, "question": "The big box under the bed ______ old toys and books.", "options": ["is interested in", "is excited about", "is proud of", "is filled with"], "answer": 3, "answerLabel": "D", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(D) is filled with\n【用語】be filled with + N (adj.phr.)：充滿\n【中譯】床底下的大箱子裝滿了舊玩具和書。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 618, "question": "I have lived in this neighborhood for ten years, so I ______ every street here.", "options": ["am disgusted with", "am familiar with", "am new to", "am superior to"], "answer": 1, "answerLabel": "B", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(B) am familiar with\n【用語】be familiar with + N (adj.phr.)：熟悉\n【中譯】我在這個社區住了十年，所以我很熟悉這裡的每一條街。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 619, "question": "I ______ money, so can you lend me ten dollars for the bus?", "options": ["am free of", "am short of", "am patient with", "am in the shape of"], "answer": 1, "answerLabel": "B", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(B) am short of\n【用語】be short of + N (adj.phr.)：缺少\n【中譯】我缺錢，所以你可以借我十元搭公車嗎？", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 620, "question": "Our teacher gave Ben a job this year: he ______ the plants in our classroom.", "options": ["is responsible for watering", "is likely to water", "is poor at watering", "is afraid of watering"], "answer": 0, "answerLabel": "A", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(A) is responsible for watering\n【用語】be responsible for + N/V-ing (adj.phr.)：為……負責\n【中譯】老師今年給了Ben一個工作：他負責替我們教室裡的植物澆水。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 621, "question": "Mr. Wang ______ this week, so a new teacher is teaching our English class.", "options": ["is broke", "is grounded", "is away", "is sold out"], "answer": 2, "answerLabel": "C", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(C) is away\n【用語】be away (adj.phr.)：離開；不在的\n【中譯】王老師這星期不在，所以有一位新老師在教我們的英文課。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 622, "question": "Kevin ______ this video game. He has played it every day for two years, and now it isn't fun anymore.", "options": ["is patient with", "is similar to", "is curious about", "is bored with"], "answer": 3, "answerLabel": "D", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(D) is bored with\n【用語】be bored with + N (adj.phr.)：對……感到無聊、厭煩\n【中譯】凱文對這個電玩感到厭煩了。他已經每天玩了兩年，現在它不再好玩了。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 623, "question": "At the party, Lisa ______ red. She looked like a beautiful flower.", "options": ["was dressed in", "was rich in", "was in search of", "was afraid of"], "answer": 0, "answerLabel": "A", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(A) was dressed in\n【用語】be dressed in + 顏色 (adj.phr.)：穿某種顏色的衣服\n【中譯】在派對上，麗莎穿著紅色的衣服。她看起來像一朵美麗的花。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 624, "question": "The weather ______ in the afternoon. It started to rain hard, and the wind was very strong.", "options": ["got hurt", "got worse", "got better", "got lost"], "answer": 1, "answerLabel": "B", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(B) got worse\n【用語】get worse (adj.phr.)：變糟\n【中譯】下午天氣變糟了。開始下起大雨，而且風非常強。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 625, "question": "Dinosaurs ______ millions of years ago, but today we can only see their bones in museums.", "options": ["were embarrassed", "were around", "were broke", "were sold out"], "answer": 1, "answerLabel": "B", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(B) were around\n【用語】be around (adj.phr.)：存在\n【中譯】恐龍存在於數百萬年前，但今天我們只能在博物館裡看到牠們的骨頭。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 626, "question": "The movie ______ a true story about a little boy and his dog.", "options": ["is afraid of", "is based on", "is good for", "is used to"], "answer": 1, "answerLabel": "B", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(B) is based on\n【用語】be based on + N (adj.phr.)：以……為基礎、依據\n【中譯】這部電影是根據一個關於小男孩和他的狗的真實故事改編的。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 627, "question": "I ______ eating instant noodles every day. I want some real food!", "options": ["am sick and tired of", "am proud of", "am curious about", "am serious about"], "answer": 0, "answerLabel": "A", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(A) am sick and tired of\n【用語】be sick and tired of + N/V-ing (adj.phr.)：厭倦某事\n【中譯】我厭倦每天吃泡麵了。我想吃一些真正的食物！", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 628, "question": "Mr. Chen parked his car in the wrong place, so he ______. He had to pay 1,200 dollars.", "options": ["was fined", "was amazed", "was through", "was on a diet"], "answer": 0, "answerLabel": "A", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(A) was fined\n【用語】be fined (adj.phr.)：被罰款\n【中譯】陳先生把車停在錯誤的地方，所以他被罰款了。他必須付一千二百元。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 629, "question": "Please ______ crossing the street here. The cars on this road go very fast.", "options": ["be careful about", "be sick of", "be busy", "be disgusted with"], "answer": 0, "answerLabel": "A", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(A) be careful about\n【用語】be careful about + N/V-ing (adj.phr.)：對……小心\n【中譯】在這裡過馬路請小心。這條路上的車開得很快。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 630, "question": "I ______ my math test score. I studied very hard, but I only got 60.", "options": ["was satisfied with", "was disappointed with", "got involved in", "was famous for"], "answer": 1, "answerLabel": "B", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(B) was disappointed with\n【用語】be disappointed with/at + N (adj.phr.)：對……感到失望\n【中譯】我對我的數學考試成績感到失望。我很努力讀書，但只考了六十分。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 631, "question": "My parents ______ this weekend, so I am staying at Grandma's house.", "options": ["are in danger", "are embarrassed", "are on a diet", "are away from home"], "answer": 3, "answerLabel": "D", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(D) are away from home\n【用語】be away from home (adj.phr.)：不在家\n【中譯】我爸媽這個週末不在家，所以我住在奶奶家。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 632, "question": "After the heavy snow last night, our car ______ snow. Dad had to clean it before he drove to work.", "options": ["was made of", "was like", "was sorry for", "was covered with"], "answer": 3, "answerLabel": "D", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(D) was covered with\n【用語】be covered with + N (adj.phr.)：被……覆蓋\n【中譯】昨晚下了大雪之後，我們的車被雪覆蓋了。爸爸開車去上班前必須把它清乾淨。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 633, "question": "Everyone ______ the news. The old bridge fell down in the storm last night.", "options": ["was shocked at", "was famous as", "was similar to", "was good at"], "answer": 0, "answerLabel": "A", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(A) was shocked at\n【用語】be shocked at + N (adj.phr.)：對……感到震驚\n【中譯】每個人都對這個消息感到震驚。那座老橋昨晚在暴風雨中倒塌了。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 634, "question": "My aunt ______ a doctor last month. They had a big wedding in Taichung.", "options": ["was superior to", "was close to", "got mad at", "got married to"], "answer": 3, "answerLabel": "D", "source": "be動詞+形容詞片語 be + Adjective Phrases｜be動詞+形容詞片語 be + Adjective Phrases", "explanation": "【答案】(D) got married to\n【用語】get married to + 人 (adj.phr.)：和…結婚\n【中譯】我阿姨上個月和一位醫生結婚了。他們在台中舉辦了一場盛大的婚禮。", "explanationSource": "supplemental", "section": "be動詞+形容詞片語 be + Adjective Phrases"}, {"id": 635, "question": "Watermelons are ______ in winter, so they are very expensive now.", "options": ["to the point", "in use", "out of season", "on duty"], "answer": 2, "answerLabel": "C", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(C) out of season\n【用語】out of season (adj.phr.)：非盛產季節\n【中譯】西瓜在冬天不是盛產季節，所以現在很貴。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 636, "question": "Grandpa was very sick last week, but the doctor says he is ______ now.", "options": ["in place", "out of danger", "on sale", "out of date"], "answer": 1, "answerLabel": "B", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(B) out of danger\n【用語】out of danger (adj.phr.)：脫離險境\n【中譯】爺爺上週病得很重，但醫生說他現在已經脫離險境了。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 637, "question": "Mangoes are ______ in summer, so they are cheap and sweet.", "options": ["on leave", "in vain", "in season", "in trouble"], "answer": 2, "answerLabel": "C", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(C) in season\n【用語】in season (adj.phr.)：在盛產季節、在旺季\n【中譯】芒果在夏天正值盛產季節，所以又便宜又甜。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 638, "question": "Mr. Lin's beef noodles are ______. Everyone says they are the best in town.", "options": ["at risk", "in pain", "second to none", "out of date"], "answer": 2, "answerLabel": "C", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(C) second to none\n【用語】second to none (adj.phr.)：不亞於任何人；最好的\n【中譯】林先生的牛肉麵是最棒的。大家都說那是鎮上最好吃的。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 639, "question": "The car was ______ on the wet road and hit a tree.", "options": ["in season", "on display", "on a diet", "out of control"], "answer": 3, "answerLabel": "D", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(D) out of control\n【用語】out of control (adj.phr.)：失控\n【中譯】那輛車在濕滑的路上失控，撞上了一棵樹。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 640, "question": "This map is ______. It doesn't show the new MRT station.", "options": ["safe and sound", "in sight", "out of date", "on board"], "answer": 2, "answerLabel": "C", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(C) out of date\n【用語】out of date (adj.phr.)：過時的\n【中譯】這張地圖過時了。它沒有標出新的捷運站。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 641, "question": "The elevator is ______, so we have to take the stairs.", "options": ["second to none", "in good health", "out of order", "at ease"], "answer": 2, "answerLabel": "C", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(C) out of order\n【用語】out of order (adj.phr.)：（機器或設備）故障\n【中譯】電梯故障了，所以我們必須走樓梯。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 642, "question": "My brother's hobby is ______ mine. He likes sports, but I like reading.", "options": ["the same as", "close to", "similar to", "different from"], "answer": 3, "answerLabel": "D", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(D) different from\n【用語】different from + N (adj.phr.)：與……不同\n【中譯】我哥哥的嗜好和我的不同。他喜歡運動，但我喜歡閱讀。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 643, "question": "If you don't wear a helmet on a scooter, your life is ______.", "options": ["on sale", "at risk", "to the point", "in season"], "answer": 1, "answerLabel": "B", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(B) at risk\n【用語】at risk (adj.phr.)：有危險、冒風險\n【中譯】如果你騎機車不戴安全帽，你的生命就會有危險。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 644, "question": "Help! The little boy is ______. He fell into the river!", "options": ["on duty", "in danger", "at ease", "out of danger"], "answer": 1, "answerLabel": "B", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(B) in danger\n【用語】in danger (adj.phr.)：處於危險之中\n【中譯】救命！那個小男孩有危險。他掉進河裡了！", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 645, "question": "The teacher's test questions are ______ the lessons in our textbook, so read the book carefully.", "options": ["based on", "far less than", "different from", "far from"], "answer": 0, "answerLabel": "A", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(A) based on\n【用語】based on + N (adj.phr.)：以……為基礎；根據\n【中譯】老師的考題是根據我們課本裡的課文出的，所以要仔細讀課本。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 646, "question": "December is ______ month of the year, and January is the first.", "options": ["the same as", "the latest", "the last", "far less than"], "answer": 2, "answerLabel": "C", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(C) the last\n【用語】the last + N (adj.phr.)：最後的\n【中譯】十二月是一年中的最後一個月，而一月是第一個月。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 647, "question": "Your speech was short and ______. Everyone understood your main idea.", "options": ["out of season", "in vain", "on leave", "to the point"], "answer": 3, "answerLabel": "D", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(D) to the point\n【用語】to the point (adj.phr.)：切題；掌握要點\n【中譯】你的演講簡短又切中要點。每個人都懂你的主旨。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 648, "question": "Tom looked for his lost key all day, but his search was ______. He never found it.", "options": ["in place", "in use", "in vain", "good enough"], "answer": 2, "answerLabel": "C", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(C) in vain\n【用語】in vain (adj.phr.)：徒勞無功\n【中譯】湯姆整天都在找他遺失的鑰匙，但他的尋找都是白費力氣。他始終沒找到。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 649, "question": "Ben broke the classroom window. Now he is ______ with the teacher.", "options": ["in season", "on the increase", "sunny side up", "in trouble"], "answer": 3, "answerLabel": "D", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(D) in trouble\n【用語】in trouble (adj.phr.)：處在麻煩中\n【中譯】班打破了教室的窗戶。現在他在老師那裡惹上麻煩了。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 650, "question": "My school is ______ my home, so I have to take the bus every day.", "options": ["far from", "the same as", "based on", "similar to"], "answer": 0, "answerLabel": "A", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(A) far from\n【用語】far from + N (adj.phr.)：遠離\n【中譯】我的學校離我家很遠，所以我每天都必須搭公車。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 651, "question": "These shoes are ______ today. They are 50% off!", "options": ["on sale", "on board", "on leave", "on duty"], "answer": 0, "answerLabel": "A", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(A) on sale\n【用語】on sale (adj.phr.)：在拍賣中、特價中\n【中譯】這些鞋子今天特價。打五折！", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 652, "question": "Your English is ______ for the test. Don't worry.", "options": ["out of date", "in pain", "at hand", "good enough"], "answer": 3, "answerLabel": "D", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(D) good enough\n【用語】good enough (adj.phr.)：夠好；足夠好的\n【中譯】你的英文程度應付這次考試已經夠好了。別擔心。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 653, "question": "Amy felt ______ at her new school because her classmates were very friendly.", "options": ["on display", "in season", "at ease", "on sale"], "answer": 2, "answerLabel": "C", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(C) at ease\n【用語】at ease (adj.phr.)：自在\n【中譯】艾咪在新學校感到很自在，因為她的同學都很友善。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 654, "question": "After the big typhoon, we were happy that all our family members were ______.", "options": ["out of season", "on the increase", "sunny side up", "safe and sound"], "answer": 3, "answerLabel": "D", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(D) safe and sound\n【用語】safe and sound (adj.phr.)：安然無恙\n【中譯】大颱風過後，我們很高興全家人都安然無恙。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 655, "question": "Your answer is ______ mine. We both wrote 25.", "options": ["far from", "far less than", "the same as", "different from"], "answer": 2, "answerLabel": "C", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(C) the same as\n【用語】the same as + N (adj.phr.)：和……相同\n【中譯】你的答案和我的一樣。我們都寫了25。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 656, "question": "We give our old clothes to people ______.", "options": ["on display", "in need", "in sight", "in place"], "answer": 1, "answerLabel": "B", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(B) in need\n【用語】in need (adj.phr.)：在窮困中的、有需要的\n【中譯】我們把舊衣服捐給有需要的人。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 657, "question": "Our art works are ______ in the school hall this week. Come and see them!", "options": ["in pain", "on a diet", "out of control", "on display"], "answer": 3, "answerLabel": "D", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(D) on display\n【用語】on display (adj.phr.)：展出、展示\n【中譯】我們的美術作品這週在學校大廳展出。來看看吧！", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 658, "question": "Mr. Wang is ______ tonight, so he can't go home until 10 p.m.", "options": ["on sale", "second to none", "in season", "on duty"], "answer": 3, "answerLabel": "D", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(D) on duty\n【用語】on duty (adj.phr.)：值班、上班\n【中譯】王先生今晚值班，所以他要到晚上十點才能回家。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 659, "question": "The number of people with pet dogs is ______ in Taiwan. There are more and more dogs every year.", "options": ["in vain", "at ease", "on sale", "on the increase"], "answer": 3, "answerLabel": "D", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(D) on the increase\n【用語】on the increase (adj.phr.)：在增加中\n【中譯】在台灣養寵物狗的人數正在增加。每年狗都越來越多。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 660, "question": "The price of this phone is ______ the price of that one. This one is only NT$3,000, but that one is NT$30,000.", "options": ["close to", "far less than", "similar to", "the same as"], "answer": 1, "answerLabel": "B", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(B) far less than\n【用語】far less than + N (adj.phr.)：遠低於…（如：遠低於費用）\n【中譯】這支手機的價格遠低於那支的價格。這支只要三千元，但那支要三萬元。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 661, "question": "Ken always wants ______ phone. He buys a new one as soon as it comes out.", "options": ["far less than", "the latest", "the same as", "the last"], "answer": 1, "answerLabel": "B", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(B) the latest\n【用語】the latest + N (adj.phr.)：最新的\n【中譯】肯總是想要最新的手機。新手機一推出他就買。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 662, "question": "My grandma is 90 years old, but she is still ______. She walks in the park every morning.", "options": ["in good health", "at hand", "out of season", "on display"], "answer": 0, "answerLabel": "A", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(A) in good health\n【用語】in good health (adj.phr.)：健康狀況良好\n【中譯】我奶奶九十歲了，但她身體仍然很健康。她每天早上都在公園散步。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 663, "question": "Your new bike looks ______ mine. Both are red, but yours is a little bigger.", "options": ["based on", "far from", "the same as", "similar to"], "answer": 3, "answerLabel": "D", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(D) similar to\n【用語】similar to + N (adj.phr.)：與……相似\n【中譯】你的新腳踏車看起來和我的很像。兩台都是紅色的，但你的稍微大一點。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 664, "question": "Everything is ______ for the party. The food, drinks, and music are all ready.", "options": ["out of control", "in vain", "in place", "in trouble"], "answer": 2, "answerLabel": "C", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(C) in place\n【用語】in place (adj.phr.)：在適當的地方、就緒\n【中譯】派對的一切都已就緒。食物、飲料和音樂都準備好了。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 665, "question": "Ms. Lee is ______ this week. She went to Japan with her family, so we have a new teacher.", "options": ["on the increase", "in use", "sunny side up", "on leave"], "answer": 3, "answerLabel": "D", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(D) on leave\n【用語】on leave (adj.phr.)：在休假中\n【中譯】李老師這週休假。她和家人去了日本，所以我們有一位代課老師。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 666, "question": "The fire was big, but the firemen soon got it ______.", "options": ["under control", "on display", "out of control", "in season"], "answer": 0, "answerLabel": "A", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(A) under control\n【用語】under control (adj.phr.)：處於控制之下、在掌握之中\n【中譯】火勢很大，但消防員很快就控制住了。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 667, "question": "The hotel is ______ the beach. We can walk there in two minutes.", "options": ["based on", "close to", "far from", "different from"], "answer": 1, "answerLabel": "B", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(B) close to\n【用語】close to + N (adj.phr.)：靠近……；接近……\n【中譯】那間飯店離海灘很近。我們走兩分鐘就到了。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 668, "question": "We walked for an hour, and finally the mountain house was ______.", "options": ["in sight", "in need", "in good health", "on a diet"], "answer": 0, "answerLabel": "A", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(A) in sight\n【用語】in sight (adj.phr.)：看得見；在視線內\n【中譯】我們走了一個小時，終於看得到山屋了。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 669, "question": "Mom is ______, so she eats only salad for dinner and no dessert.", "options": ["in use", "in sight", "on a diet", "second to none"], "answer": 2, "answerLabel": "C", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(C) on a diet\n【用語】on a diet (adj.phr.)：節食中\n【中譯】媽媽正在節食，所以晚餐她只吃沙拉，不吃甜點。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 670, "question": "The books on the shelf are ______. Please put them back from Book 1 to Book 10.", "options": ["on the increase", "in vain", "out of order", "in place"], "answer": 2, "answerLabel": "C", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(C) out of order\n【用語】out of order (adj.phr.)：混亂、沒有照順序\n【中譯】書架上的書順序亂了。請把它們從第一冊到第十冊依序放回去。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 671, "question": "Mary doesn't want to share a room with her sister. She wants a room ______.", "options": ["in sight", "in use", "on sale", "of her own"], "answer": 3, "answerLabel": "D", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(D) of her own\n【用語】of one's own (adj.phr.)：屬於自己的\n【中譯】瑪莉不想和她妹妹共用房間。她想要一間屬於自己的房間。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 672, "question": "Please move your bike. It's ______, and I can't get out of the door.", "options": ["in my way", "under control", "on display", "in season"], "answer": 0, "answerLabel": "A", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(A) in my way\n【用語】in one's way (adj.phr.)：擋到（某人）的路\n【中譯】請移開你的腳踏車。它擋到我的路，我沒辦法出門。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 673, "question": "Sorry, you can't use this computer now. It is ______.", "options": ["at ease", "in good health", "in season", "in use"], "answer": 3, "answerLabel": "D", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(D) in use\n【用語】in use (adj.phr.)：在使用中\n【中譯】抱歉，你現在不能用這台電腦。它正在使用中。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 674, "question": "I'd like my eggs ______, with the yellow part on top.", "options": ["sunny side up", "in vain", "on board", "out of season"], "answer": 0, "answerLabel": "A", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(A) sunny side up\n【用語】sunny side up (adj.phr.)：單面煎蛋的\n【中譯】我的蛋要單面煎的，蛋黃朝上。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 675, "question": "Jack hurt his leg in the game, and he was ______ all night.", "options": ["in place", "on the increase", "on sale", "in pain"], "answer": 3, "answerLabel": "D", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(D) in pain\n【用語】in pain (adj.phr.)：痛苦；疼痛中\n【中譯】傑克在比賽中弄傷了腿，整晚都很痛。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 676, "question": "All the passengers are ______ now, so the train can leave.", "options": ["in vain", "on board", "on leave", "out of season"], "answer": 1, "answerLabel": "B", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(B) on board\n【用語】on board (adj.phr.)：在船、火車、飛機上\n【中譯】所有乘客現在都上車了，所以火車可以出發了。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 677, "question": "The final exam is ______. It's next Monday, so let's study hard.", "options": ["out of season", "at hand", "at ease", "sunny side up"], "answer": 1, "answerLabel": "B", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(B) at hand\n【用語】at hand (adj.phr.)：即將發生、就在眼前\n【中譯】期末考就快到了。就在下週一，所以我們用功讀書吧。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 678, "question": "I can't find any fresh strawberries at the market. They are ______ in August.", "options": ["in pain", "out of season", "under control", "on display"], "answer": 1, "answerLabel": "B", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(B) out of season\n【用語】out of season (adj.phr.)：非盛產季節\n【中譯】我在市場找不到新鮮草莓。八月不是草莓的盛產季節。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 679, "question": "The boat was in a big storm, but now it is back at the port and everyone is ______.", "options": ["in season", "out of danger", "out of date", "on sale"], "answer": 1, "answerLabel": "B", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(B) out of danger\n【用語】out of danger (adj.phr.)：脫離險境\n【中譯】那艘船遇上了大暴風雨，但現在它已回到港口，大家都脫離險境了。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 680, "question": "It's July now. Lychees are ______, so you can see them in every fruit shop.", "options": ["out of season", "in pain", "out of order", "in season"], "answer": 3, "answerLabel": "D", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(D) in season\n【用語】in season (adj.phr.)：在盛產季節、在旺季\n【中譯】現在是七月。荔枝正值盛產季節，所以每家水果店都看得到。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 681, "question": "Everyone loves the beef noodles at this shop. They are ______ in our town.", "options": ["second to none", "out of date", "on a diet", "in danger"], "answer": 0, "answerLabel": "A", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(A) second to none\n【用語】second to none (adj.phr.)：不亞於任何人；最好的\n【中譯】大家都愛這家店的牛肉麵。它們在我們鎮上是最好的。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 682, "question": "The car was ______ and hit a tree on the rainy road.", "options": ["out of control", "in season", "safe and sound", "on display"], "answer": 0, "answerLabel": "A", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(A) out of control\n【用語】out of control (adj.phr.)：失控\n【中譯】那輛車在下雨的路上失控，撞上了一棵樹。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 683, "question": "Don't use this old dictionary. It's ______, and many new words are not in it.", "options": ["in season", "out of date", "on board", "second to none"], "answer": 1, "answerLabel": "B", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(B) out of date\n【用語】out of date (adj.phr.)：過時的\n【中譯】別用這本舊字典。它過時了，很多新字都沒有收在裡面。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 684, "question": "The vending machine is ______. It took my money but gave me nothing.", "options": ["out of order", "in good health", "on sale", "to the point"], "answer": 0, "answerLabel": "A", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(A) out of order\n【用語】out of order (adj.phr.)：（機器或設備）故障\n【中譯】這台販賣機故障了。它吃了我的錢，卻什麼都沒給我。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 685, "question": "Jenny looks like her twin sister, but her hobbies are ______ her sister's. Jenny loves sports, but her sister loves music.", "options": ["different from", "the same as", "similar to", "close to"], "answer": 0, "answerLabel": "A", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(A) different from\n【用語】different from + N (adj.phr.)：與……不同\n【中譯】珍妮長得像她的雙胞胎姊妹，但她的嗜好和她姊妹的不同。珍妮熱愛運動，而她的姊妹熱愛音樂。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 686, "question": "If you ride a bike without a helmet, your life is ______.", "options": ["at risk", "second to none", "on sale", "on display"], "answer": 0, "answerLabel": "A", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(A) at risk\n【用語】at risk (adj.phr.)：有危險、冒風險\n【中譯】如果你騎腳踏車不戴安全帽，你的生命就會有危險。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 687, "question": "Help! The little boy fell into the river. He is ______!", "options": ["out of date", "on a diet", "in danger", "on duty"], "answer": 2, "answerLabel": "C", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(C) in danger\n【用語】in danger (adj.phr.)：處於危險之中\n【中譯】救命啊！那個小男孩掉進河裡了。他有危險！", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 688, "question": "This movie is ______ a true story. It really happened in 1999.", "options": ["based on", "far from", "different from", "far less than"], "answer": 0, "answerLabel": "A", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(A) based on\n【用語】based on + N (adj.phr.)：以……為基礎；根據\n【中譯】這部電影是根據真實故事改編的。這件事真的在1999年發生過。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 689, "question": "Z is ______ letter of the English alphabet.", "options": ["the last", "similar to", "the same as", "the latest"], "answer": 0, "answerLabel": "A", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(A) the last\n【用語】the last + N (adj.phr.)：最後的\n【中譯】Z是英文字母的最後一個字母。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 690, "question": "Your speech is too long. Please keep it short and ______.", "options": ["in sight", "on board", "to the point", "in vain"], "answer": 2, "answerLabel": "C", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(C) to the point\n【用語】to the point (adj.phr.)：切題；掌握要點\n【中譯】你的演講太長了。請保持簡短並切中要點。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 691, "question": "Tom looked for his lost dog all day, but his hard work was ______. He never found it.", "options": ["in good health", "in vain", "on display", "to the point"], "answer": 1, "answerLabel": "B", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(B) in vain\n【用語】in vain (adj.phr.)：徒勞無功\n【中譯】湯姆找他走失的狗找了一整天，但他的努力都白費了。他始終沒有找到牠。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 692, "question": "Ben broke his mom's favorite cup. Now he is ______.", "options": ["in season", "in trouble", "at ease", "on display"], "answer": 1, "answerLabel": "B", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(B) in trouble\n【用語】in trouble (adj.phr.)：處在麻煩中\n【中譯】班打破了他媽媽最愛的杯子。現在他麻煩大了。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 693, "question": "Lisa's home is ______ her school, so she has to get up at six and take a bus for an hour.", "options": ["the same as", "similar to", "far from", "close to"], "answer": 2, "answerLabel": "C", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(C) far from\n【用語】far from + N (adj.phr.)：遠離\n【中譯】莉莎家離學校很遠，所以她必須六點起床，搭一個小時的公車。", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 694, "question": "Everything in this store is ______ this week. You can buy two T-shirts for the price of one!", "options": ["on duty", "on sale", "in pain", "out of danger"], "answer": 1, "answerLabel": "B", "source": "形容詞片語 Adjective Phrases｜形容詞片語 Adjective Phrases", "explanation": "【答案】(B) on sale\n【用語】on sale (adj.phr.)：在拍賣中、特價中\n【中譯】這家店的所有商品這週都在特價。你可以用一件的價格買兩件T恤！", "explanationSource": "supplemental", "section": "形容詞片語 Adjective Phrases"}, {"id": 695, "question": "Mr. Lin made a lot of money ______ his health, and now he is very sick.", "options": ["on the back of", "in memory of", "in order of", "at the cost of"], "answer": 3, "answerLabel": "D", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(D) at the cost of\n【用語】at the cost/expense of + N (prep.phr.)：犧牲……、以……為代價\n【中譯】林先生犧牲健康賺了很多錢，現在他病得很重。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 696, "question": "We stayed home ______ the heavy rain.", "options": ["because of", "in front of", "instead of", "in memory of"], "answer": 0, "answerLabel": "A", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(A) because of\n【用語】because of + N/V-ing (prep.phr.)：由於、因為\n【中譯】因為大雨，我們待在家裡。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 697, "question": "My brother loves math, but ______ me, I like English better.", "options": ["thanks to", "next to", "instead of", "as for"], "answer": 3, "answerLabel": "D", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(D) as for\n【用語】as for + N (prep.phr.)：至於；關於\n【中譯】我哥哥喜歡數學，但至於我，我比較喜歡英文。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 698, "question": "______ cooking, my mom is the best in our family.", "options": ["For fear of", "When it comes to", "At the price of", "In case of"], "answer": 1, "answerLabel": "B", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(B) When it comes to\n【用語】when it comes to + N/V-ing (prep.phr.)：說到、提及\n【中譯】說到烹飪，我媽媽是我們家最厲害的。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 699, "question": "______ English, Amy can also speak Japanese.", "options": ["Away from", "Aside from", "According to", "In place of"], "answer": 1, "answerLabel": "B", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(B) Aside from\n【用語】aside from + N/V-ing (prep.phr.)：除了⋯⋯之外\n【中譯】除了英文之外，Amy也會說日文。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 700, "question": "I have a question ______ the homework.", "options": ["with regard to", "in spite of", "away from", "in memory of"], "answer": 0, "answerLabel": "A", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(A) with regard to\n【用語】in/with regard to + N (prep.phr.)：關於\n【中譯】我有一個關於作業的問題。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 701, "question": "The little monkey is riding ______ its mother.", "options": ["in spite of", "according to", "in case of", "on the back of"], "answer": 3, "answerLabel": "D", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(D) on the back of\n【用語】on the back of + N (prep.phr.)：在…的背上\n【中譯】小猴子騎在牠媽媽的背上。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 702, "question": "The hungry cat walked around the kitchen ______ food.", "options": ["in search of", "in order of", "in memory of", "at the price of"], "answer": 0, "answerLabel": "A", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(A) in search of\n【用語】in search of + N (prep.phr.)：尋找\n【中譯】那隻飢餓的貓在廚房裡走來走去尋找食物。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 703, "question": "This bus can carry ______ fifty people.", "options": ["in front of", "because of", "up to", "such as"], "answer": 2, "answerLabel": "C", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(C) up to\n【用語】up to + N (prep.phr.)：多達、高至、長達\n【中譯】這台公車可以載多達五十人。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 704, "question": "I saw an old friend ______ school this morning.", "options": ["on my way to", "regardless of", "in spite of", "in place of"], "answer": 0, "answerLabel": "A", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(A) on my way to\n【用語】on one's way to + 地方 (prep.phr.)：在去……的路上\n【中譯】今天早上我在去學校的路上看到一位老朋友。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 705, "question": "The driver always sits ______ the bus.", "options": ["instead of", "because of", "in memory of", "in the front of"], "answer": 3, "answerLabel": "D", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(D) in the front of\n【用語】in the front of + N (prep.phr.)：在⋯⋯的前部\n【中譯】司機總是坐在公車的前部。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 706, "question": "______ my teacher's help, I passed the math test.", "options": ["In search of", "At the end of", "Thanks to", "Away from"], "answer": 2, "answerLabel": "C", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(C) Thanks to\n【用語】thanks to + N (prep.phr.)：多虧；由於\n【中譯】多虧老師的幫忙，我通過了數學考試。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 707, "question": "Ben goes jogging every morning ______ the weather.", "options": ["in order of", "regardless of", "on the back of", "at the price of"], "answer": 1, "answerLabel": "B", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(B) regardless of\n【用語】regardless of + N (prep.phr.)：不論、不管、不顧\n【中譯】不論天氣如何，Ben每天早上都去慢跑。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 708, "question": "I like fruits ______ apples and bananas.", "options": ["such as", "on behalf of", "in the face of", "in case of"], "answer": 0, "answerLabel": "A", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(A) such as\n【用語】such as + N (prep.phr.)：例如、像是\n【中譯】我喜歡水果，例如蘋果和香蕉。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 709, "question": "Please keep the baby ______ the hot water.", "options": ["in terms of", "thanks to", "according to", "away from"], "answer": 3, "answerLabel": "D", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(D) away from\n【用語】away from + N (prep.phr.)：遠離\n【中譯】請讓寶寶遠離熱水。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 710, "question": "This restaurant has great food, ______ its friendly service.", "options": ["at the sight of", "for fear of", "in place of", "not to mention"], "answer": 3, "answerLabel": "D", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(D) not to mention\n【用語】not to mention + N/V-ing (prep.phr.)：更別提、更不用說\n【中譯】這家餐廳有很棒的食物，更不用說它親切的服務。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 711, "question": "The students had different ideas ______ where to go for the class trip.", "options": ["at the bottom of", "in front of", "right after", "as to"], "answer": 3, "answerLabel": "D", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(D) as to\n【用語】as to + N/wh- 子句 (prep.phr.)：關於、至於\n【中譯】學生們對於校外教學要去哪裡有不同的想法。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 712, "question": "Mia did her homework ______ dinner.", "options": ["right after", "in memory of", "in terms of", "in search of"], "answer": 0, "answerLabel": "A", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(A) right after\n【用語】right after + N (prep.phr.)：就在……之後；緊接著\n【中譯】Mia晚餐後馬上就寫功課。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 713, "question": "Wash your hands ______ eating.", "options": ["in order of", "in front of", "up to", "before"], "answer": 3, "answerLabel": "D", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(D) before\n【用語】before + N/V-ing (prep.phr.)：在……之前\n【中譯】吃東西之前要洗手。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 714, "question": "There is a tall tree ______ our school.", "options": ["in front of", "in case of", "thanks to", "due to"], "answer": 0, "answerLabel": "A", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(A) in front of\n【用語】in front of + N (prep.phr.)：在……前面\n【中譯】我們學校前面有一棵高大的樹。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 715, "question": "I found my lost key ______ my bag.", "options": ["because of", "at the bottom of", "regardless of", "in terms of"], "answer": 1, "answerLabel": "B", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(B) at the bottom of\n【用語】at the bottom of + N (prep.phr.)：在…底部\n【中譯】我在我的包包底部找到我遺失的鑰匙。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 716, "question": "My phone rang ______ the movie, and everyone looked at me.", "options": ["in the middle of", "in place of", "in search of", "thanks to"], "answer": 0, "answerLabel": "A", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(A) in the middle of\n【用語】in the middle of + N (prep.phr.)：在……的中間\n【中譯】我的手機在電影播到一半時響了，大家都看著我。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 717, "question": "The town built a statue ______ a kind old doctor who helped many people.", "options": ["in terms of", "away from", "in memory of", "in case of"], "answer": 2, "answerLabel": "C", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(C) in memory of\n【用語】in memory of + N (prep.phr.)：（為了）紀念、懷念\n【中譯】這個鎮為了紀念一位幫助過許多人的親切老醫生，建了一座雕像。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 718, "question": "______ playing the piano, Lily also plays the violin.", "options": ["According to", "In addition to", "For fear of", "In the face of"], "answer": 1, "answerLabel": "B", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(B) In addition to\n【用語】in addition to + N/V-ing (prep.phr.)：除了……以外（還有）\n【中譯】除了彈鋼琴以外，Lily也會拉小提琴。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 719, "question": "______ the weather report, it will rain tomorrow.", "options": ["Instead of", "In the back of", "According to", "In place of"], "answer": 2, "answerLabel": "C", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(C) According to\n【用語】according to + N (prep.phr.)：根據\n【中譯】根據氣象報告，明天會下雨。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 720, "question": "Mr. Wang is sick today, so Ms. Chen will teach our class ______ him.", "options": ["in terms of", "in place of", "at the sight of", "at the bottom of"], "answer": 1, "answerLabel": "B", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(B) in place of\n【用語】in place of + 人 (prep.phr.)：代替某人\n【中譯】王老師今天生病，所以陳老師會代替他教我們班。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 721, "question": "Our team is ten points ______ the other team.", "options": ["instead of", "in memory of", "because of", "ahead of"], "answer": 3, "answerLabel": "D", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(D) ahead of\n【用語】ahead of + N (prep.phr.)：在⋯⋯前面；領先\n【中譯】我們隊領先另一隊十分。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 722, "question": "Please turn off your phone ______ the test.", "options": ["in terms of", "in search of", "at the price of", "prior to"], "answer": 3, "answerLabel": "D", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(D) prior to\n【用語】prior to + N/V-ing (prep.phr.)：在……之前\n【中譯】考試之前請關掉手機。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 723, "question": "Amy sits ______ me in class, so we often talk.", "options": ["such as", "in case of", "next to", "in terms of"], "answer": 2, "answerLabel": "C", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(C) next to\n【用語】next to + N (prep.phr.)：在……旁邊\n【中譯】Amy上課坐在我旁邊，所以我們常聊天。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 724, "question": "Let's walk to the park ______ taking the bus.", "options": ["in the face of", "in memory of", "instead of", "at the end of"], "answer": 2, "answerLabel": "C", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(C) instead of\n【用語】instead of + N/V-ing (prep.phr.)：代替；而不是\n【中譯】我們走路去公園，而不要搭公車吧。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 725, "question": "Jenny finished her report two days ______ the deadline.", "options": ["ahead of", "in spite of", "in place of", "in order of"], "answer": 0, "answerLabel": "A", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(A) ahead of\n【用語】ahead of + N (prep.phr.)：在⋯⋯之前（時間）\n【中譯】Jenny比截止日期提前兩天完成了報告。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 726, "question": "______ fire, please use the stairs, not the elevator.", "options": ["In addition to", "Along with", "Thanks to", "In case of"], "answer": 3, "answerLabel": "D", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(D) In case of\n【用語】in case of + N (prep.phr.)：以防萬一發生……\n【中譯】萬一發生火災，請走樓梯，不要搭電梯。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 727, "question": "______ the heavy rain, they still played soccer.", "options": ["Because of", "In spite of", "Next to", "Such as"], "answer": 1, "answerLabel": "B", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(B) In spite of\n【用語】in spite of + N/V-ing (prep.phr.)：儘管\n【中譯】儘管下大雨，他們還是去踢足球。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 728, "question": "The children are sleeping ______ the car.", "options": ["due to", "on behalf of", "in the back of", "in case of"], "answer": 2, "answerLabel": "C", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(C) in the back of\n【用語】in the back of + N (prep.phr.)：在…的後面（內部後方）\n【中譯】孩子們正在車子的後座睡覺。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 729, "question": "We have a big test ______ this month.", "options": ["at the end of", "such as", "regardless of", "in place of"], "answer": 0, "answerLabel": "A", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(A) at the end of\n【用語】at the end of + N (prep.phr.)：在……的結尾\n【中譯】我們在這個月底有一個大考。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 730, "question": "______ price, this phone is better than that one.", "options": ["In search of", "In place of", "At the sight of", "In terms of"], "answer": 3, "answerLabel": "D", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(D) In terms of\n【用語】in terms of + N (prep.phr.)：從……的角度、就……而言\n【中譯】就價格而言，這支手機比那支好。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 731, "question": "Everyone went to the party ______ Tom, who was sick.", "options": ["except for", "in the face of", "at the price of", "in the center of"], "answer": 0, "answerLabel": "A", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(A) except for\n【用語】except for + N (prep.phr.)：除了……以外\n【中譯】除了生病的Tom以外，大家都去了派對。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 732, "question": "She walked slowly on the ice ______ falling down.", "options": ["thanks to", "along with", "for fear of", "in terms of"], "answer": 2, "answerLabel": "C", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(C) for fear of\n【用語】for fear of + N/V-ing (prep.phr.)：因害怕⋯⋯；害怕⋯⋯而\n【中譯】她因為害怕跌倒，在冰上走得很慢。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 733, "question": "Please line up ______ height, from short to tall.", "options": ["in order of", "on the back of", "away from", "in memory of"], "answer": 0, "answerLabel": "A", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(A) in order of\n【用語】in order of + N (prep.phr.)：以⋯⋯的順序；按照⋯⋯排列\n【中譯】請按照身高順序排隊，從矮到高。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 734, "question": "The train was late ______ the typhoon.", "options": ["at the sight of", "due to", "in place of", "in addition to"], "answer": 1, "answerLabel": "B", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(B) due to\n【用語】due to + N (prep.phr.)：由於；因為\n【中譯】火車因為颱風而誤點了。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 735, "question": "We went swimming ______ school.", "options": ["at the sight of", "for fear of", "according to", "after"], "answer": 3, "answerLabel": "D", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(D) after\n【用語】after + N (prep.phr.)：在……之後；隨後\n【中譯】我們放學後去游泳。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 736, "question": "The teacher chose the class leader ______ the students' votes.", "options": ["on the basis of", "in memory of", "away from", "in the back of"], "answer": 0, "answerLabel": "A", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(A) on the basis of\n【用語】on the basis of + N (prep.phr.)：以……為基礎\n【中譯】老師以學生的投票為依據選出班長。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 737, "question": "We stopped at a convenience store ______ the beach.", "options": ["regardless of", "on the way to", "thanks to", "in terms of"], "answer": 1, "answerLabel": "B", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(B) on the way to\n【用語】on the way to + 地方 (prep.phr.)：在前往……的路上\n【中譯】我們在去海邊的路上，在一家便利商店停了一下。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 738, "question": "______ the long lines, we had a great time at the zoo.", "options": ["On the back of", "In search of", "Apart from", "In order of"], "answer": 2, "answerLabel": "C", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(C) Apart from\n【用語】apart from + N/V-ing (prep.phr.)：除了……之外\n【中譯】除了大排長龍之外，我們在動物園玩得很開心。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 739, "question": "I bought this T-shirt ______ 200 dollars.", "options": ["in response to", "in memory of", "in the face of", "at the price of"], "answer": 3, "answerLabel": "D", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(D) at the price of\n【用語】at the price of + N (prep.phr.)：以……的價格\n【中譯】我以兩百元的價格買了這件T恤。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 740, "question": "Let's meet at the bank; it is ______ the post office, just on the other side of the street.", "options": ["at the sight of", "in response to", "across from", "in memory of"], "answer": 2, "answerLabel": "C", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(C) across from\n【用語】across from + N (prep.phr.)：在…對面\n【中譯】我們在銀行見面吧；它就在郵局的對面，就在街道的另一邊。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 741, "question": "Amy is our class leader, so she thanked the teacher ______ our whole class.", "options": ["at the bottom of", "on behalf of", "in search of", "in case of"], "answer": 1, "answerLabel": "B", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(B) on behalf of\n【用語】on behalf of + N (prep.phr.)：代表\n【中譯】Amy 是我們的班長，所以她代表我們全班向老師道謝。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 742, "question": "______ the movie, the hero is a poor boy, but at the end he becomes a king.", "options": ["In search of", "At the price of", "At the beginning of", "For fear of"], "answer": 2, "answerLabel": "C", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(C) At the beginning of\n【用語】at the beginning of + N (prep.phr.)：在……的開始\n【中譯】在電影的開頭，主角是個窮男孩，但最後他成為了國王。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 743, "question": "The little girl started to cry ______ the big dog.", "options": ["in terms of", "in place of", "at the sight of", "on behalf of"], "answer": 2, "answerLabel": "C", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(C) at the sight of\n【用語】at the sight of + N (prep.phr.)：一看到、一見到\n【中譯】小女孩一看到那隻大狗就開始哭。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 744, "question": "There is a big fountain ______ the park, and many paths go out from it to every side.", "options": ["on the back of", "in response to", "in the center of", "at the cost of"], "answer": 2, "answerLabel": "C", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(C) in the center of\n【用語】in the center of + N (prep.phr.)：在…中央\n【中譯】公園的中央有一座大噴泉，許多小路從那裡通往四面八方。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 745, "question": "The firefighters stayed calm and brave ______ great danger.", "options": ["on the back of", "in the face of", "in order of", "across from"], "answer": 1, "answerLabel": "B", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(B) in the face of\n【用語】in the face of + N (prep.phr.)：面對\n【中譯】消防員面對極大的危險時仍保持冷靜和勇敢。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 746, "question": "______ the students' letters, the school decided to open the library on Saturdays.", "options": ["At the price of", "In response to", "Across from", "In the center of"], "answer": 1, "answerLabel": "B", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(B) In response to\n【用語】in response to + N (prep.phr.)：做為對……的回應\n【中譯】作為對學生來信的回應，學校決定在星期六開放圖書館。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 747, "question": "Please bring your notebook ______ your English book because you will need both of them tomorrow.", "options": ["in the face of", "at the sight of", "along with", "on behalf of"], "answer": 2, "answerLabel": "C", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(C) along with\n【用語】along with + N (prep.phr.)：與、和\n【中譯】請把你的筆記本和英文課本一起帶來，因為你明天兩樣都會用到。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 748, "question": "Tom played video games all night ______ his sleep, so he was very tired the next day.", "options": ["in memory of", "in the center of", "across from", "at the cost of"], "answer": 3, "answerLabel": "D", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(D) at the cost of\n【用語】at the cost/expense of + N (prep.phr.)：犧牲……、以……為代價\n【中譯】Tom 犧牲睡眠整晚打電動，所以隔天非常累。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 749, "question": "The baseball game was stopped ______ the heavy rain.", "options": ["because of", "in spite of", "instead of", "such as"], "answer": 0, "answerLabel": "A", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(A) because of\n【用語】because of + N/V-ing (prep.phr.)：由於、因為\n【中譯】棒球比賽因為大雨而暫停了。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 750, "question": "My parents both like coffee; ______ me, I prefer milk tea.", "options": ["in case of", "as for", "next to", "thanks to"], "answer": 1, "answerLabel": "B", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(B) as for\n【用語】as for + N (prep.phr.)：至於；關於\n【中譯】我爸媽都喜歡咖啡；至於我，我比較喜歡奶茶。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 751, "question": "Tina is not good at sports, but ______ math, she is the best student in our class.", "options": ["in case of", "on the back of", "when it comes to", "at the bottom of"], "answer": 2, "answerLabel": "C", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(C) when it comes to\n【用語】when it comes to + N/V-ing (prep.phr.)：說到、提及\n【中譯】Tina 不擅長運動，但說到數學，她是我們班上最好的學生。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 752, "question": "______ English, Ben also studies Japanese and Korean after school.", "options": ["Aside from", "At the sight of", "On behalf of", "In the face of"], "answer": 0, "answerLabel": "A", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(A) Aside from\n【用語】aside from + N/V-ing (prep.phr.)：除了⋯⋯之外\n【中譯】除了英文之外，Ben 放學後還學日文和韓文。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 753, "question": "I have a question ______ the homework for tomorrow.", "options": ["across from", "in regard to", "for fear of", "at the price of"], "answer": 1, "answerLabel": "B", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(B) in regard to\n【用語】in/with regard to + N (prep.phr.)：關於\n【中譯】我有一個關於明天作業的問題。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 754, "question": "The little boy is tired, so he is sitting ______ his father as they walk home together.", "options": ["at the beginning of", "on the back of", "in the back of", "at the bottom of"], "answer": 1, "answerLabel": "B", "source": "介系詞片語 Prepositional Phrases｜介系詞片語 Prepositional Phrases", "explanation": "【答案】(B) on the back of\n【用語】on the back of + N (prep.phr.)：在…的背上\n【中譯】小男孩累了，所以他們一起走路回家時，他坐在爸爸的背上。", "explanationSource": "supplemental", "section": "介系詞片語 Prepositional Phrases"}, {"id": 755, "question": "The doctors worked ______ to save the sick boy.", "options": ["for fun", "from head to toe", "around the clock", "in the long run"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) around the clock\n【用語】around the clock (adv.phr.)：不眠不休地、日以繼夜地\n【中譯】醫生們不眠不休地工作，為了救那個生病的男孩。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 756, "question": "You don't need to pay. You can get the ice cream ______ today.", "options": ["for nothing", "to begin with", "at hand", "at a high price"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) for nothing\n【用語】for nothing (adv.phr.)：免費；沒有報酬；白白地\n【中譯】你不用付錢。今天你可以免費拿到冰淇淋。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 757, "question": "Look! Some ducks are swimming ______ behind our school.", "options": ["all over the world", "in the pond", "by birth", "on the grass"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) in the pond\n【用語】in the pond (adv.phr.)：在池塘裡\n【中譯】你看！有些鴨子在我們學校後面的池塘裡游泳。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 758, "question": "______, I didn't like dogs, but now I love them.", "options": ["At a low price", "In the world", "At first", "By hand"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) At first\n【用語】at first (adv.phr.)：起初、一開始\n【中譯】起初，我不喜歡狗，但現在我很愛牠們。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 759, "question": "Mr. Lin sleeps only three hours a night to make money. He works ______, and now he is sick.", "options": ["at a high price", "by air", "in public", "at the cost of his health"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) at the cost of his health\n【用語】at the cost of health (adv.phr.)：以健康為代價\n【中譯】林先生為了賺錢每晚只睡三個小時。他以健康為代價工作，現在他生病了。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 760, "question": "Amy moved to Taipei in 2020, and she has lived there ______.", "options": ["last year", "in a good way", "sooner or later", "ever since"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) ever since\n【用語】ever since (adv.phr.)：從那時起一直\n【中譯】Amy在2020年搬到台北，從那時起她就一直住在那裡。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 761, "question": "In one minute, Ben ran ______ between the sofa and the door five times.", "options": ["to and fro", "for a long time", "than ever before", "on the moon"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) to and fro\n【用語】to and fro (adv.phr.)：來回地、往返地\n【中譯】一分鐘內，Ben在沙發和門之間來回跑了五次。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 762, "question": "______, living in a big city is fun. On the other hand, it is very noisy.", "options": ["As a result", "By accident", "To make matters worse", "On the one hand"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) On the one hand\n【用語】on the one hand (adv.phr.)：一方面\n【中譯】一方面，住在大城市很有趣。另一方面，大城市很吵。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 763, "question": "There are many people at the bus stop, so we have to wait ______.", "options": ["on the computer", "from the bottom of my heart", "in line", "in the sea"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) in line\n【用語】in line (adv.phr.)：排隊\n【中譯】公車站有很多人，所以我們必須排隊等候。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 764, "question": "Tom has two dogs and three cats. He has five pets ______.", "options": ["by the same token", "on the river", "in total", "in a hurry"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) in total\n【用語】in total (adv.phr.)：總共；一共\n【中譯】Tom有兩隻狗和三隻貓。他總共有五隻寵物。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 765, "question": "The teacher drew a big circle on the ground and told us to put the ball ______.", "options": ["in uniform", "by check", "before it's too late", "in the circle"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) in the circle\n【用語】in the circle (adv.phr.)：在圈內；在圓圈中\n【中譯】老師在地上畫了一個大圓圈，並叫我們把球放在圓圈裡。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 766, "question": "At night, we can see the moon and stars ______.", "options": ["as I expected", "at lunchtime", "anything but", "in the sky"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) in the sky\n【用語】in the sky (adv.phr.)：在空中\n【中譯】晚上，我們可以看到天空中的月亮和星星。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 767, "question": "Jack didn't understand the new word, so the teacher said it ______ until he remembered it.", "options": ["at a low price", "over and over again", "in the mountains", "before long"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) over and over again\n【用語】over and over (again) (adv.phr.)：一次又一次\n【中譯】Jack不懂這個新單字，所以老師一次又一次地唸，直到他記住為止。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 768, "question": "I have never been to Japan, but I hope to go there ______.", "options": ["at that time", "at the corner", "last year", "some day"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) some day\n【用語】some day (adv.phr.)：將來有一天\n【中譯】我從來沒去過日本，但我希望將來有一天能去那裡。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 769, "question": "Harry Potter books are popular ______. People in many countries read them.", "options": ["at the scene", "behind schedule", "on the moon", "all around the world"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) all around the world\n【用語】all around the world (adv.phr.)：全世界各地\n【中譯】哈利波特的書在全世界各地都很受歡迎。很多國家的人都讀這些書。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 770, "question": "A: I'm going to the store now. ______, have you seen my red umbrella?\nB: It's behind the door.", "options": ["In the storm", "Nothing but", "By the way", "In short"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) By the way\n【用語】by the way (adv.phr.)：順便一提\n【中譯】A：我現在要去商店。順便問一下，你有看到我的紅色雨傘嗎？B：它在門後面。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 771, "question": "Grandpa walks to the park every morning, ______. Even heavy rain can't stop him.", "options": ["rain or shine", "on the phone", "after all", "once in a while"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) rain or shine\n【用語】rain or shine (adv.phr.)：不論晴雨；無論如何\n【中譯】爺爺每天早上不論晴雨都走路去公園。連大雨也無法阻止他。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 772, "question": "We waited for the bus for an hour. ______, it came.", "options": ["In advance", "For a while", "More often than not", "At last"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) At last\n【用語】at last (adv.phr.)：終於（帶有鬆一口氣的語氣）\n【中譯】我們等公車等了一個小時。終於，公車來了。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 773, "question": "I want to be a doctor ______.", "options": ["on the market", "in the future", "in the past", "last year"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) in the future\n【用語】in the future (adv.phr.)：在未來\n【中譯】我將來想當一名醫生。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 774, "question": "Mr. Wang moved to Kaohsiung, so he ______ lives next to us.", "options": ["as usual", "first of all", "no longer", "on the contrary"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) no longer\n【用語】no longer (adv.phr.)：不再\n【中譯】王先生搬到高雄了，所以他不再住在我們隔壁。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 775, "question": "The new phone was too hard to use, so Grandma went ______ and used her old phone again.", "options": ["the day after tomorrow", "back to the old way", "by check", "one by one"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) back to the old way\n【用語】back to the old way (adv.phr.)：回到舊方式\n【中譯】新手機太難用了，所以奶奶回到舊方式，又用回她的舊手機。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 776, "question": "We don't have school ______, so I often sleep late on Saturday.", "options": ["on the weekend", "at a high cost", "on weekdays", "in the water"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) on the weekend\n【用語】on the weekend (adv.phr.)：在週末\n【中譯】我們週末不用上學，所以我星期六常常睡到很晚。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 777, "question": "Kevin gets up early ______ catch the first bus.", "options": ["so far", "in order to", "as usual", "in short"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) in order to\n【用語】in order to + VR (adv.phr.)：為了\n【中譯】Kevin早起是為了趕上第一班公車。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 778, "question": "To stay healthy, you should eat vegetables and sleep well. ______, you must exercise every day. That is the key.", "options": ["No more than", "On the contrary", "Most importantly", "On the sidewalk"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) Most importantly\n【用語】most importantly (adv.phr.)：最重要的是\n【中譯】為了保持健康，你應該吃蔬菜並睡飽。最重要的是，你必須每天運動。那才是關鍵。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 779, "question": "There is a bird's nest ______ near my window.", "options": ["on the cell phone", "last time we met", "in the ocean", "in the tree"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) in the tree\n【用語】in the tree (adv.phr.)：在樹上（不屬於樹的東西，如鳥、貓）\n【中譯】我窗戶附近的樹上有一個鳥巢。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 780, "question": "A: How do you go to school?\nB: I go ______. The bus stop is in front of my house, and the ride takes only ten minutes.", "options": ["without fail", "on foot", "between meals", "by bus"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) by bus\n【用語】by train/bus/plane/taxi/ship (adv.phr.)：搭乘火車／公車／飛機／計程車／船\n【中譯】A：你怎麼去上學？B：我搭公車去。公車站就在我家前面，車程只要十分鐘。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 781, "question": "Our class eats lunch together in the classroom ______ every school day.", "options": ["at lunchtime", "by air", "in the sea", "once in a while"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) at lunchtime\n【用語】at lunchtime (adv.phr.)：在午餐時間\n【中譯】我們班每個上學日的午餐時間都一起在教室吃午餐。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 782, "question": "Dr. Chen is seventy, but he is still ______. He sees sick people every day.", "options": ["on vacation", "in general", "in practice", "all over the world"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) in practice\n【用語】in practice (adv.phr.)：在執業中\n【中譯】陳醫師七十歲了，但他仍在執業。他每天都看病人。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 783, "question": "Kevin always does his homework ______, just before the teacher asks for it.", "options": ["that is", "at the last minute", "in advance", "all the way"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) at the last minute\n【用語】at the last minute (adv.phr.)：在最後一刻\n【中譯】Kevin總是在最後一刻才寫作業，就在老師要收作業之前。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 784, "question": "It's six o'clock. Let's go home ______. It will be night soon.", "options": ["for sale", "before dark", "on a daily basis", "in no way"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) before dark\n【用語】before dark (adv.phr.)：天黑前\n【中譯】六點了。我們天黑前回家吧。很快就要入夜了。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 785, "question": "Please stop smoking ______. Your family wants you to be healthy.", "options": ["in the world", "for example", "for your family's sake", "in the snow"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) for your family's sake\n【用語】for someone's/something's sake (adv.phr.)：為了……的緣故\n【中譯】為了你家人著想，請戒菸。你的家人希望你健康。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 786, "question": "We had no money, so our plan to build a new park is ______ now.", "options": ["on the shelf", "at once", "in the sun", "so far"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) on the shelf\n【用語】on the shelf (adv.phr.)：被擱置\n【中譯】我們沒有錢，所以蓋新公園的計畫現在被擱置了。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 787, "question": "It is warm in Kenting ______, so you can swim there even in winter.", "options": ["than usual", "on the tree", "all year round", "last night"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) all year round\n【用語】all year round (adv.phr.)：一年到頭\n【中譯】墾丁一年到頭都很溫暖，所以即使在冬天你也能在那裡游泳。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 788, "question": "The new library was going to open in May, but it opened in March, two months ______.", "options": ["in person", "in the snow", "ahead of schedule", "behind schedule"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) ahead of schedule\n【用語】ahead of schedule (adv.phr.)：超前進度；比預定提早\n【中譯】新圖書館原本要在五月開幕，但它在三月就開了，比預定提早兩個月。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 789, "question": "I went to bed at 11:00 ______, so I am tired this morning.", "options": ["the day after tomorrow", "in other words", "never ever", "last night"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) last night\n【用語】last night (adv.phr.)：昨晚\n【中譯】我昨晚十一點才睡，所以今天早上很累。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 790, "question": "I read about the fire ______ this morning. It was on page 3.", "options": ["on the radio", "in the sun", "for good", "in the newspaper"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) in the newspaper\n【用語】in the newspaper (adv.phr.)：在報紙上\n【中譯】我今天早上在報紙上讀到那場火災的消息。它在第三版。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 791, "question": "Ms. Lee didn't want other students to hear, so she talked to Tom ______.", "options": ["in public", "in private", "on business", "on average"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) in private\n【用語】in private (adv.phr.)：私下地；私底下\n【中譯】李老師不想讓其他學生聽到，所以她私下和Tom談話。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 792, "question": "The package was sent from Japan to Taiwan ______, so it arrived in only two days.", "options": ["in a way", "by air", "on the CD player", "from door to door"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) by air\n【用語】by air (adv.phr.)：搭飛機；藉由空運\n【中譯】這個包裹是從日本空運寄到台灣的，所以只花兩天就到了。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 793, "question": "A: Why did you push me?\nB: I'm sorry. I didn't do it ______. Someone pushed me first.", "options": ["in the sky", "on purpose", "at dinner", "in cash"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) on purpose\n【用語】on purpose (adv.phr.)：故意地\n【中譯】A：你為什麼推我？B：對不起。我不是故意的。是有人先推我的。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 794, "question": "My favorite singer was ______ last night, so I watched the show at home.", "options": ["as well", "in my free time", "on TV", "with a check"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) on TV\n【用語】on TV (adv.phr.)：在電視節目中\n【中譯】我最喜歡的歌手昨晚上了電視節目，所以我在家看了那個節目。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 795, "question": "The kids are sitting ______ in the living room, because there are no chairs.", "options": ["on the floor", "in bed", "of course", "for sure"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) on the floor\n【用語】on the floor (adv.phr.)：在地板上\n【中譯】孩子們坐在客廳的地板上，因為那裡沒有椅子。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 796, "question": "I often play basketball with my classmates ______. We play for ten minutes before the next class starts.", "options": ["on the moon", "after class", "at a low price", "in the sea"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) after class\n【用語】after class (adv.phr.)：下課後\n【中譯】我常在下課後和同學打籃球。我們在下一堂課開始前打十分鐘。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 797, "question": "My uncle grows rice and keeps chickens ______ in the country.", "options": ["in the ocean", "on the farm", "the day before yesterday", "behind schedule"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) on the farm\n【用語】on the farm (adv.phr.)：在田裡、在農場裡\n【中譯】我叔叔在鄉下的農場裡種稻、養雞。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 798, "question": "Jason is ______, and he plays baseball with his teammates every Saturday.", "options": ["in a strange way", "on the whole", "on a team", "little by little"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) on a team\n【用語】on a team (adv.phr.)：在某個隊伍中\n【中譯】Jason 是一支球隊的隊員，他每週六和隊友們一起打棒球。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 799, "question": "Mom, look! Your photo is ______ of the computer.", "options": ["on the screen", "for better or worse", "in the water", "best of all"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) on the screen\n【用語】on the screen (adv.phr.)：在螢光幕上\n【中譯】媽，你看！你的照片在電腦螢幕上。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 800, "question": "Ben's home is very close to school, so he doesn't take the bus; he goes to school ______.", "options": ["on foot", "in the sky", "in the sea", "either way"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) on foot\n【用語】on foot (adv.phr.)：步行、走路\n【中譯】Ben 的家離學校很近，所以他不搭公車；他走路去上學。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 801, "question": "Grandpa doesn't have a TV, so he listens to the news ______ every morning.", "options": ["on the radio", "in the newspaper", "in fact", "at all times"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) on the radio\n【用語】on the radio (adv.phr.)：在收音機裡\n【中譯】爺爺沒有電視，所以他每天早上收聽收音機裡的新聞。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 802, "question": "The farmer is working ______ under the hot sun, planting rice.", "options": ["in the field", "in the ocean", "just in case", "in his bedroom"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) in the field\n【用語】in the field (adv.phr.)：在田野間\n【中譯】那位農夫正在炎熱的太陽下在田野間工作，種著稻子。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 803, "question": "Kevin didn't study for the test. ______, he got a bad grade.", "options": ["As a result", "For example", "On his head", "From top to bottom"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) As a result\n【用語】as a result (adv.phr.)：因此\n【中譯】Kevin 沒有準備考試。因此，他考得很差。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 804, "question": "A: It's going to rain this afternoon.\nB: ______, we should take an umbrella with us.", "options": ["In the living room", "In the past", "From bad to worse", "In that case"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) In that case\n【用語】in that case (adv.phr.)：如果那樣；在那種情況下\n【中譯】A：今天下午會下雨。\nB：如果那樣的話，我們應該帶把傘。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 805, "question": "The cookies are ______ in the kitchen, but I can't reach them because I'm too short.", "options": ["on the top of the mountain", "as soon as possible", "in the pond", "on the shelf"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) on the shelf\n【用語】on the shelf (adv.phr.)：在架子上\n【中譯】餅乾在廚房的架子上，但我太矮了拿不到。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 806, "question": "My aunt is a nurse ______, but she wants to be a doctor in the future.", "options": ["last year", "in the end", "at present", "from time to time"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) at present\n【用語】at present (adv.phr.)：目前\n【中譯】我阿姨目前是護理師，但她將來想當醫生。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 807, "question": "Grandma made this sweater ______, not with a machine.", "options": ["by hand", "from then on", "at the same time", "at work"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) by hand\n【用語】by hand (adv.phr.)：用手工\n【中譯】奶奶是用手工織這件毛衣的，不是用機器。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 808, "question": "Living in a big city is very convenient. ______, it is often noisy and crowded.", "options": ["In the beginning", "For example", "On the other hand", "After meals"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) On the other hand\n【用語】on the other hand (adv.phr.)：另一方面\n【中譯】住在大城市非常方便。另一方面，那裡常常又吵又擁擠。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 809, "question": "We ran all the way to the station and got there ______ to catch the last train.", "options": ["in the past", "by accident", "in time", "on the line"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) in time\n【用語】in time (adv.phr.)：及時\n【中譯】我們一路跑到車站，及時趕上了最後一班火車。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 810, "question": "Tom studied for five hours ______; he didn't even stop to eat or drink.", "options": ["throughout the world", "without a break", "in turn", "between meals"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) without a break\n【用語】without a break (adv.phr.)：不休息地；不停地\n【中譯】Tom 不休息地讀了五個小時的書；他甚至沒有停下來吃東西或喝水。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 811, "question": "I usually play basketball with my friends ______, and then I go home for dinner.", "options": ["after school", "on the moon", "last time", "on the TV"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) after school\n【用語】after school (adv.phr.)：放學後\n【中譯】我通常放學後和朋友打籃球，然後回家吃晚餐。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 812, "question": "This glass bowl breaks easily, so please carry it ______.", "options": ["with care", "above all", "in the pasture", "in a hurry"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) with care\n【用語】with care (adv.phr.)：小心地（= carefully）\n【中譯】這個玻璃碗很容易破，所以請小心地拿。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 813, "question": "When astronauts are ______, they can look down and see the whole Earth.", "options": ["twice a week", "in space", "on the farm", "most important of all"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) in space\n【用語】in space (adv.phr.)：在太空中\n【中譯】當太空人在太空中時，他們可以往下看到整個地球。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 814, "question": "Amy doesn't play the piano for money; she plays it just ______.", "options": ["on the bed", "a great deal", "for sale", "for fun"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) for fun\n【用語】for fun (adv.phr.)：為了樂趣；好玩\n【中譯】Amy 彈鋼琴不是為了賺錢；她只是為了好玩而彈。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 815, "question": "These lions live in the zoo now, but they used to live ______ in Africa.", "options": ["on the spot", "in return", "on the sidewalk", "in the wild"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) in the wild\n【用語】in the wild (adv.phr.)：在野外\n【中譯】這些獅子現在住在動物園裡，但牠們以前住在非洲的野外。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 816, "question": "Our team played two games ______ on Saturday, with no rest between them.", "options": ["back to back", "right away", "in the circle", "far from"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) back to back\n【用語】back to back (adv.phr.)：連續地\n【中譯】我們的隊伍星期六連續打了兩場比賽，中間沒有休息。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 817, "question": "At the night market, you can buy food, clothes, toys, ______.", "options": ["from place to place", "and so on", "on weekdays", "at once"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) and so on\n【用語】and so on (adv.phr.)：等、諸如此類\n【中譯】在夜市，你可以買到食物、衣服、玩具等等。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 818, "question": "Many people have helped us, and ______ we have collected 5,000 books for the poor children.", "options": ["by ourselves", "off the record", "to date", "the day after tomorrow"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) to date\n【用語】to date (adv.phr.)：到目前為止\n【中譯】很多人幫助了我們，到目前為止我們已經為貧困的孩子們收集了五千本書。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 819, "question": "I got up late this morning. ______, it started to rain on my way to school.", "options": ["Best of all", "In the first place", "In cash", "To make matters worse"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) To make matters worse\n【用語】to make matters worse (adv.phr.)：更糟的是\n【中譯】我今天早上起晚了。更糟的是，在上學途中開始下雨了。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 820, "question": "I met my old classmate ______ at the supermarket yesterday; we didn't plan it at all.", "options": ["by chance", "on my right", "in this way", "on purpose"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) by chance\n【用語】by chance (adv.phr.)：偶然地；碰巧\n【中譯】我昨天在超市碰巧遇到我的老同學；我們完全沒有事先約好。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 821, "question": "My little sister is only six, but she can tie her shoes ______ without anyone's help.", "options": ["not even", "for good", "on her own", "on time"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) on her own\n【用語】on one's own (adv.phr.)：獨自地、靠自己\n【中譯】我妹妹才六歲，但她可以不靠任何人幫忙，自己綁鞋帶。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 822, "question": "This hotel has a big swimming pool. ______, it has a free gym for its guests.", "options": ["Around the corner", "On the contrary", "In other words", "In addition"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) In addition\n【用語】in addition (adv.phr.)：此外\n【中譯】這家飯店有一座大游泳池。此外，它還有一間供房客免費使用的健身房。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 823, "question": "In this game, you can change the color of your car ______; just click the button whenever you want.", "options": ["at will", "in the river", "behind schedule", "to your surprise"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) at will\n【用語】at will (adv.phr.)：任意、隨心所欲地\n【中譯】在這個遊戲裡，你可以隨心所欲地改變車子的顏色；想改的時候按下按鈕就好。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 824, "question": "The school bought these computers ______, not for playing games.", "options": ["now and then", "for learning purposes", "by no means", "with a check"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) for learning purposes\n【用語】for + N + purposes (adv.phr.)：為了…目的\n【中譯】學校買這些電腦是為了學習的目的，不是為了玩遊戲。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 825, "question": "The movie started at seven, and Tim arrived ______, so he missed only the first few minutes.", "options": ["soon after", "in the present", "some day", "on the mountainside"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) soon after\n【用語】soon after (adv.phr.)：不久之後\n【中譯】電影七點開始，Tim 不久之後就到了，所以他只錯過了開頭幾分鐘。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 826, "question": "This plan sounds easy, but ______ it is very hard to do.", "options": ["at a low price", "in the opposite way", "in practice", "as follows"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) in practice\n【用語】in practice (adv.phr.)：實際上\n【中譯】這個計畫聽起來很簡單，但實際上很難做到。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 827, "question": "I was late for school three times this week, so ______ I will get up earlier.", "options": ["from now on", "last night", "in the corner", "all day long"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) from now on\n【用語】from now on (adv.phr.)：從現在起\n【中譯】我這週上學遲到了三次，所以從現在起我會早點起床。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 828, "question": "We have lived in this house for ten years, but we are moving tomorrow, so tonight we will sleep here ______.", "options": ["for the last time", "the day before yesterday", "for the first time", "since then"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) for the last time\n【用語】for the last time (adv.phr.)：最後一次\n【中譯】我們在這間房子住了十年，但我們明天就要搬家了，所以今晚是我們最後一次睡在這裡。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 829, "question": "This elevator can take ten people ______, so we can't all get in together.", "options": ["at least", "at most", "in the same way", "in the ocean"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) at most\n【用語】at most (adv.phr.)：最多；至多\n【中譯】這台電梯最多只能載十個人，所以我們沒辦法全部一起進去。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 830, "question": "The food in this restaurant is delicious. ______ the prices are very low.", "options": ["On the corner,", "What's more,", "For sale,", "On the contrary,"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) What's more,\n【用語】What's more, (adv.phr.)：而且；更重要的是\n【中譯】這家餐廳的食物很好吃。而且，價格很便宜。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 831, "question": "The children are ______ in the park; they are flying kites and having fun.", "options": ["in a hurry", "in bed", "at play", "on the school team"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) at play\n【用語】at play (adv.phr.)：正在玩耍\n【中譯】孩子們正在公園裡玩耍；他們在放風箏，玩得很開心。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 832, "question": "Kevin has changed ______ since he moved to Japan; he looks very different now.", "options": ["at times", "on his back", "for nothing", "a lot"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) a lot\n【用語】a lot (adv.phr.)：很多（放在動詞後）\n【中譯】Kevin 搬到日本後改變了很多；他現在看起來很不一樣。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 833, "question": "Doctors say children should sleep ______ nine hours every night, not less.", "options": ["on vacation", "at least", "in alphabetical order", "after meals"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) at least\n【用語】at least (adv.phr.)：至少\n【中譯】醫生說孩子們每晚應該至少睡九個小時，不能更少。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 834, "question": "The blue whale is the biggest animal ______.", "options": ["at the cost of the environment", "on earth", "way too big", "in the sky"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) on earth\n【用語】on earth (adv.phr.)：在世界上\n【中譯】藍鯨是世界上最大的動物。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 835, "question": "It takes ______ an hour to get to the zoo by bus; it's about 55 to 65 minutes.", "options": ["on the ranch", "never ever", "in the dark", "more or less"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) more or less\n【用語】more or less (adv.phr.)：或多或少、差不多\n【中譯】搭公車到動物園差不多要一個小時；大約五十五到六十五分鐘。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 836, "question": "Taipei 101 is ______ one of the most famous buildings in Taiwan.", "options": ["in turn", "without a doubt", "at the scene", "on Mondays"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) without a doubt\n【用語】without (a) doubt (adv.phr.)：毫無疑問地\n【中譯】台北101毫無疑問是台灣最有名的建築之一。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 837, "question": "The picture on the wall is hanging ______, so please make it straight.", "options": ["on the floor", "worst of all", "at an angle", "better yet"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) at an angle\n【用語】at an angle (adv.phr.)：傾斜地；成一個角度\n【中譯】牆上的畫掛歪了，所以請把它弄正。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 838, "question": "I couldn't find this book in any store, so I bought it ______.", "options": ["as soon as you can", "on the Internet", "the other way around", "on the moon"], "answer": 1, "answerLabel": "B", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(B) on the Internet\n【用語】on the Internet (adv.phr.)：在網路上\n【中譯】我在任何一家店都找不到這本書，所以我在網路上買了它。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 839, "question": "I lost my wallet on the bus. ______ my phone was in it, too.", "options": ["By check,", "Out of the blue,", "What's worse,", "Best of all,"], "answer": 2, "answerLabel": "C", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(C) What's worse,\n【用語】What's worse, (adv.phr.)：更糟的是\n【中譯】我在公車上弄丟了錢包。更糟的是，我的手機也在裡面。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 840, "question": "This restaurant is very popular, so you need to call and book a table ______.", "options": ["in advance", "in public", "at the last minute", "to this end"], "answer": 0, "answerLabel": "A", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(A) in advance\n【用語】in advance (adv.phr.)：事先\n【中譯】這家餐廳很受歡迎，所以你需要事先打電話訂位。", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 841, "question": "What ______ happened to your room? It's a big mess!", "options": ["to and fro", "in the tree", "with a credit card", "on earth"], "answer": 3, "answerLabel": "D", "source": "副詞片語 Adverb Phrases｜副詞片語 Adverb Phrases", "explanation": "【答案】(D) on earth\n【用語】on earth (adv.phr.)：到底、究竟\n【中譯】你的房間到底發生了什麼事？簡直一團亂！", "explanationSource": "supplemental", "section": "副詞片語 Adverb Phrases"}, {"id": 842, "question": "My little brother is very shy; he talks to people ______ his mother is next to him.", "options": ["only when", "in case", "as if", "so that"], "answer": 0, "answerLabel": "A", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(A) only when\n【用語】only when + 子句 (conj.phr.)：只有在……時候才……\n【中譯】我弟弟很害羞；只有在他媽媽在他旁邊的時候，他才會跟別人說話。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 843, "question": "______ I am concerned, summer is the best season because I can swim every day.", "options": ["As far as", "So that", "Even though", "As soon as"], "answer": 0, "answerLabel": "A", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(A) As far as\n【用語】as far as + N + be concerned (conj.phr.)：就……而言\n【中譯】就我而言，夏天是最棒的季節，因為我每天都可以游泳。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 844, "question": "Ben was very hungry, so he started eating ______ he got home.", "options": ["even though", "as if", "in case", "as soon as"], "answer": 3, "answerLabel": "D", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(D) as soon as\n【用語】as soon as + 子句 (conj.phr.)：一……就……\n【中譯】Ben 很餓，所以他一回到家就開始吃東西。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 845, "question": "You can go to the movies tonight ______ you finish your homework first.", "options": ["as though", "now that", "only if", "even though"], "answer": 2, "answerLabel": "C", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(C) only if\n【用語】only if + 子句 (conj.phr.)：只有在……條件下才……\n【中譯】只有在你先完成功課的條件下，你今晚才可以去看電影。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 846, "question": "The new bike in the living room is ______ because today is his birthday, so I can't ride it.", "options": ["neither for me nor for my brother", "both for me and for my brother", "not for me but for my brother", "either for me or for my brother"], "answer": 2, "answerLabel": "C", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(C) not for me but for my brother\n【用語】not A but B (conj.phr.)：不是A而是B\n【中譯】客廳裡的新腳踏車不是給我的，而是給我弟弟的，因為今天是他的生日，所以我不能騎它。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 847, "question": "Kevin talks ______ he knows everything, but he really doesn't.", "options": ["as soon as", "so that", "as if", "in case"], "answer": 2, "answerLabel": "C", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(C) as if\n【用語】as if + 子句 (conj.phr.)：彷彿、好像\n【中譯】Kevin 說話的樣子好像他什麼都知道，但其實他並不知道。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 848, "question": "Ms. Lin is our English teacher, and she can speak ______, so she can talk with the students from Japan.", "options": ["English rather than Japanese", "not English but Japanese", "neither English nor Japanese", "English as well as Japanese"], "answer": 3, "answerLabel": "D", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(D) English as well as Japanese\n【用語】as well as (conj.phr.)：以及；和\n【中譯】林老師是我們的英文老師，她會說英文以及日文，所以她能和來自日本的學生交談。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 849, "question": "Dad is very busy this weekend, so he can drive us to the zoo ______, but not on both days.", "options": ["both on Saturday and on Sunday", "not only on Saturday but also on Sunday", "either on Saturday or on Sunday", "neither on Saturday nor on Sunday"], "answer": 2, "answerLabel": "C", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(C) either on Saturday or on Sunday\n【用語】either A or B (conj.phr.)：不是……就是……\n【中譯】爸爸這個週末很忙，所以他不是星期六就是星期日可以載我們去動物園，但不能兩天都載。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 850, "question": "Lucy went to school ______ she had a bad cold.", "options": ["so that", "now that", "in case", "even though"], "answer": 3, "answerLabel": "D", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(D) even though\n【用語】even though + 子句 (conj.phr.)：雖然、即使\n【中譯】雖然 Lucy 得了重感冒，她還是去上學了。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 851, "question": "Many people go to my uncle's restaurant because the food there is ______; it costs little and tastes great.", "options": ["not only cheap but also delicious", "cheap rather than delicious", "neither cheap nor delicious", "either cheap or delicious"], "answer": 0, "answerLabel": "A", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(A) not only cheap but also delicious\n【用語】not only A but also B (conj.phr.)：不僅A而且B\n【中譯】很多人去我叔叔的餐廳，因為那裡的食物不僅便宜而且美味；花費少又很好吃。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 852, "question": "The little boy cried ______ he was badly hurt, but he only fell down on the soft grass.", "options": ["as though", "so that", "now that", "as soon as"], "answer": 0, "answerLabel": "A", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(A) as though\n【用語】as though (conj.phr.)：彷彿；好像（= as if）\n【中譯】那個小男孩哭得彷彿受了重傷，但他只是跌倒在柔軟的草地上。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 853, "question": "The box was ______ I couldn't carry it by myself.", "options": ["heavy in case", "heavy now that", "heavy even though", "so heavy that"], "answer": 3, "answerLabel": "D", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(D) so heavy that\n【用語】so + adj./adv. + that 子句 (conj.phr.)：如此……以致於……\n【中譯】那個箱子重到我自己一個人搬不動。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 854, "question": "Take an umbrella with you ______ it rains this afternoon.", "options": ["now that", "even though", "in case", "as if"], "answer": 2, "answerLabel": "C", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(C) in case\n【用語】in case + 子句 (conj.phr.)：萬一；以防\n【中譯】帶把雨傘在身上，以防今天下午下雨。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 855, "question": "It was ______ all the students stayed inside the classroom.", "options": ["a hot day as if", "such a hot day that", "a hot day in case", "a hot day even though"], "answer": 1, "answerLabel": "B", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(B) such a hot day that\n【用語】such + N + that 子句 (conj.phr.)：如此……以致於……\n【中譯】那天是如此炎熱的一天，以致於所有學生都待在教室裡。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 856, "question": "Mom says cake is bad for my teeth, so she always gives me ______ after dinner.", "options": ["not fruit but cake", "fruit rather than cake", "either fruit or cake", "both fruit and cake"], "answer": 1, "answerLabel": "B", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(B) fruit rather than cake\n【用語】A rather than B (conj.phr.)：而非、而不是\n【中譯】媽媽說蛋糕對我的牙齒不好，所以晚餐後她總是給我水果，而不是蛋糕。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 857, "question": "I couldn't choose between the red shirt and the blue one, so I bought ______, and now I have two new shirts.", "options": ["neither the red one nor the blue one", "both the red one and the blue one", "the red one rather than the blue one", "either the red one or the blue one"], "answer": 1, "answerLabel": "B", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(B) both the red one and the blue one\n【用語】both A and B (conj.phr.)：A和B兩者都\n【中譯】我無法在紅色和藍色的襯衫之間做選擇，所以紅色和藍色的我都買了，現在我有兩件新襯衫。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 858, "question": "______ came to my birthday party, so I had two good friends with me.", "options": ["Tom as well as Amy", "Not Tom but Amy", "Tom rather than Amy", "Neither Tom nor Amy"], "answer": 0, "answerLabel": "A", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(A) Tom as well as Amy\n【用語】A as well as B (conj.phr.)：A以及B\n【中譯】Tom 以及 Amy 來參加了我的生日派對，所以我有兩位好朋友陪著我。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 859, "question": "______ can come to my party, because Tom is sick and Amy is visiting her grandma.", "options": ["Neither Tom nor Amy", "Either Tom or Amy", "Not only Tom but also Amy", "Both Tom and Amy"], "answer": 0, "answerLabel": "A", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(A) Neither Tom nor Amy\n【用語】neither A nor B (conj.phr.)：既不是A也不是B\n【中譯】Tom 和 Amy 都不能來參加我的派對，因為 Tom 生病了，而 Amy 要去探望她的奶奶。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 860, "question": "Every morning, my strong grandpa ______: he swims at six and runs in the park at seven.", "options": ["either swims or runs", "not only swims but also runs", "neither swims nor runs", "swims rather than runs"], "answer": 1, "answerLabel": "B", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(B) not only swims but also runs\n【用語】not only A but (also) B (conj.phr.)：不僅A而且B\n【中譯】我強壯的爺爺每天早上不僅游泳而且跑步：他六點游泳，七點在公園跑步。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 861, "question": "______ you are in junior high school, you should get up early by yourself.", "options": ["In case", "Even though", "Now that", "As if"], "answer": 2, "answerLabel": "C", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(C) Now that\n【用語】now (that) + 子句 (conj.phr.)：既然\n【中譯】既然你已經是國中生了，你應該自己早起。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 862, "question": "Please speak louder ______ everyone in the classroom can hear you.", "options": ["as if", "even though", "so that", "now that"], "answer": 2, "answerLabel": "C", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(C) so that\n【用語】so that (conj.phr.)：以便；好讓\n【中譯】請說大聲一點，好讓教室裡的每個人都能聽到你說話。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 863, "question": "______ it rains tomorrow, we will still play basketball in the gym.", "options": ["Even if", "Now that", "So that", "As if"], "answer": 0, "answerLabel": "A", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(A) Even if\n【用語】even if (conj.phr.)：即使（條件句：以現在簡單式代替未來式）\n【中譯】即使明天下雨，我們還是會在體育館打籃球。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 864, "question": "You can borrow my bike ______ you give it back to me before dinner.", "options": ["so that", "even though", "as if", "as long as"], "answer": 3, "answerLabel": "D", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(D) as long as\n【用語】as long as + 子句 (conj.phr.)：只要\n【中譯】只要你在晚餐前還給我，你就可以借我的腳踏車。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 865, "question": "My dad drinks coffee ______ he has to work late at night; he never drinks it in the morning.", "options": ["only when", "even though", "so that", "as though"], "answer": 0, "answerLabel": "A", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(A) only when\n【用語】only when + 子句 (conj.phr.)：只有在……時候才……\n【中譯】我爸爸只有在必須熬夜工作的時候才喝咖啡；他早上從不喝咖啡。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 866, "question": "______ my little sister is concerned, ice cream is the best food in the world.", "options": ["Now that", "As long as", "In case", "As far as"], "answer": 3, "answerLabel": "D", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(D) As far as\n【用語】as far as + N + be concerned (conj.phr.)：就……而言\n【中譯】就我妹妹而言，冰淇淋是世界上最棒的食物。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 867, "question": "The baby stopped crying ______ she saw her mother.", "options": ["so that", "in case", "as soon as", "even though"], "answer": 2, "answerLabel": "C", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(C) as soon as\n【用語】as soon as + 子句 (conj.phr.)：一……就……\n【中譯】那個嬰兒一看到她媽媽就停止哭泣了。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 868, "question": "The old lady will sell her house ______ someone pays five million dollars for it; she won't take less.", "options": ["only if", "even though", "as if", "now that"], "answer": 0, "answerLabel": "A", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(A) only if\n【用語】only if + 子句 (conj.phr.)：只有在……條件下才……\n【中譯】那位老太太只有在有人出五百萬元的條件下才會賣她的房子；少一點她都不接受。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 869, "question": "My favorite sport is ______; I play basketball every day, but I never swim.", "options": ["swimming rather than basketball", "neither swimming nor basketball", "not swimming but basketball", "both swimming and basketball"], "answer": 2, "answerLabel": "C", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(C) not swimming but basketball\n【用語】not A but B (conj.phr.)：不是A而是B\n【中譯】我最喜歡的運動不是游泳而是籃球；我每天打籃球，但我從不游泳。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 870, "question": "Mom looked at me ______ she didn't believe my story.", "options": ["as soon as", "so that", "as if", "in case"], "answer": 2, "answerLabel": "C", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(C) as if\n【用語】as if + 子句 (conj.phr.)：彷彿、好像\n【中譯】媽媽看著我，好像她不相信我說的故事。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 871, "question": "Jenny can play ______, so she can play two instruments.", "options": ["neither the piano nor the violin", "the piano as well as the violin", "either the piano or the violin", "the piano rather than the violin"], "answer": 1, "answerLabel": "B", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(B) the piano as well as the violin\n【用語】as well as (conj.phr.)：以及；和\n【中譯】Jenny 會彈鋼琴以及拉小提琴，所以她會兩種樂器。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 872, "question": "We have only two choices for lunch today: you can have ______, but not both.", "options": ["either rice or noodles", "neither rice nor noodles", "not only rice but also noodles", "both rice and noodles"], "answer": 0, "answerLabel": "A", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(A) either rice or noodles\n【用語】either A or B (conj.phr.)：不是……就是……\n【中譯】我們今天午餐只有兩個選擇：你不是吃飯就是吃麵，但不能兩個都吃。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 873, "question": "______ Ken studied very hard, he didn't pass the math test.", "options": ["Now that", "Even though", "As soon as", "So that"], "answer": 1, "answerLabel": "B", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(B) Even though\n【用語】even though + 子句 (conj.phr.)：雖然、即使\n【中譯】雖然 Ken 很用功讀書，他的數學考試還是沒有及格。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 874, "question": "Our new classmate, Mia, can speak ______; she learned Japanese from her mother and Korean from her father.", "options": ["neither Japanese nor Korean", "Japanese rather than Korean", "not only Japanese but also Korean", "not Japanese but Korean"], "answer": 2, "answerLabel": "C", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(C) not only Japanese but also Korean\n【用語】not only A but also B (conj.phr.)：不僅A而且B\n【中譯】我們的新同學 Mia 不僅會說日文，而且會說韓文；她跟媽媽學日文，跟爸爸學韓文。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 875, "question": "Ted spends money ______ he is a rich man, but he is only a student.", "options": ["so that", "as though", "now that", "in case"], "answer": 1, "answerLabel": "B", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(B) as though\n【用語】as though (conj.phr.)：彷彿；好像（= as if）\n【中譯】Ted 花錢的樣子彷彿他是個有錢人，但他只是個學生。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 876, "question": "The movie was ______ I laughed until I cried.", "options": ["so funny that", "funny in case", "funny as if", "funny even though"], "answer": 0, "answerLabel": "A", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(A) so funny that\n【用語】so + adj./adv. + that 子句 (conj.phr.)：如此……以致於……\n【中譯】那部電影如此好笑，以致於我笑到哭了。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 877, "question": "Write down my phone number ______ you get lost in the city.", "options": ["even though", "in case", "so that", "as if"], "answer": 1, "answerLabel": "B", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(B) in case\n【用語】in case + 子句 (conj.phr.)：萬一；以防\n【中譯】把我的電話號碼寫下來，以防你在城市裡迷路。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 878, "question": "Jack is ______ everyone in our class likes him.", "options": ["a kind boy even though", "a kind boy as if", "such a kind boy that", "a kind boy in case"], "answer": 2, "answerLabel": "C", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(C) such a kind boy that\n【用語】such + N + that 子句 (conj.phr.)：如此……以致於……\n【中譯】Jack 是如此親切的男孩，以致於我們班上每個人都喜歡他。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 879, "question": "It's sunny and warm today, so let's ______.", "options": ["both walk to school and take the bus", "walk to school rather than take the bus", "not walk to school but take the bus", "neither walk to school nor take the bus"], "answer": 1, "answerLabel": "B", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(B) walk to school rather than take the bus\n【用語】A rather than B (conj.phr.)：而非、而不是\n【中譯】今天陽光普照又溫暖，所以我們走路上學，而不要搭公車吧。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 880, "question": "______ will join the soccer team, so our class will have two players on the team.", "options": ["Neither Tom nor Ken", "Both Tom and Ken", "Tom rather than Ken", "Either Tom or Ken"], "answer": 1, "answerLabel": "B", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(B) Both Tom and Ken\n【用語】both A and B (conj.phr.)：A和B兩者都\n【中譯】Tom 和 Ken 兩個人都會加入足球隊，所以我們班在隊上會有兩名球員。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 881, "question": "Ann is on the school basketball team and the volleyball team because she plays ______ very well.", "options": ["basketball as well as volleyball", "neither basketball nor volleyball", "not basketball but volleyball", "basketball rather than volleyball"], "answer": 0, "answerLabel": "A", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(A) basketball as well as volleyball\n【用語】A as well as B (conj.phr.)：A以及B\n【中譯】Ann 是學校籃球隊和排球隊的隊員，因為她籃球以及排球都打得很好。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 882, "question": "I like ______, so I only drink water.", "options": ["coffee rather than tea", "not only coffee but also tea", "both coffee and tea", "neither coffee nor tea"], "answer": 3, "answerLabel": "D", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(D) neither coffee nor tea\n【用語】neither A nor B (conj.phr.)：既不是A也不是B\n【中譯】我既不喜歡咖啡也不喜歡茶，所以我只喝水。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 883, "question": "Grandpa's farm grows ______; he sells apples in fall and oranges in winter.", "options": ["not apples but oranges", "neither apples nor oranges", "apples rather than oranges", "not only apples but also oranges"], "answer": 3, "answerLabel": "D", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(D) not only apples but also oranges\n【用語】not only A but (also) B (conj.phr.)：不僅A而且B\n【中譯】爺爺的農場不僅種蘋果，而且種柳橙；他秋天賣蘋果，冬天賣柳橙。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 884, "question": "______ the rain has stopped, let's go out and play in the park.", "options": ["So that", "Even though", "In case", "Now that"], "answer": 3, "answerLabel": "D", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(D) Now that\n【用語】now (that) + 子句 (conj.phr.)：既然\n【中譯】既然雨已經停了，我們出去公園玩吧。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 885, "question": "I got up early this morning ______ I could catch the first bus.", "options": ["even though", "as if", "so that", "in case"], "answer": 2, "answerLabel": "C", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(C) so that\n【用語】so that (conj.phr.)：以便；好讓\n【中譯】我今天早上很早起床，好讓我能趕上第一班公車。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 886, "question": "I will finish my homework tonight ______ I have to stay up late.", "options": ["as if", "so that", "even if", "as soon as"], "answer": 2, "answerLabel": "C", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(C) even if\n【用語】even if (conj.phr.)：即使（條件句：以現在簡單式代替未來式）\n【中譯】即使我必須熬夜，我今晚也會把功課寫完。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 887, "question": "You can play video games ______ you finish your homework first.", "options": ["as if", "even though", "in case", "as long as"], "answer": 3, "answerLabel": "D", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(D) as long as\n【用語】as long as + 子句 (conj.phr.)：只要\n【中譯】只要你先寫完功課，你就可以玩電動。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 888, "question": "My little brother is quiet ______ he is sleeping; at other times, he is very noisy.", "options": ["even if", "only when", "so that", "in case"], "answer": 1, "answerLabel": "B", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(B) only when\n【用語】only when + 子句 (conj.phr.)：只有在……時候才……\n【中譯】我弟弟只有在睡覺的時候才安靜；其他時候他都很吵。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 889, "question": "______ my dad is concerned, math is the most useful subject at school.", "options": ["As soon as", "In case", "As long as", "As far as"], "answer": 3, "answerLabel": "D", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(D) As far as\n【用語】as far as + N + be concerned (conj.phr.)：就……而言\n【中譯】就我爸爸而言，數學是學校裡最有用的科目。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 890, "question": "______ the bell rang, the students ran out of the classroom.", "options": ["So that", "Even though", "In case", "As soon as"], "answer": 3, "answerLabel": "D", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(D) As soon as\n【用語】as soon as + 子句 (conj.phr.)：一……就……\n【中譯】鐘聲一響，學生們就跑出教室。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 891, "question": "You can get a free cake ______ you buy two drinks; if you buy only one, you have to pay for it.", "options": ["as though", "only if", "in case", "even though"], "answer": 1, "answerLabel": "B", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(B) only if\n【用語】only if + 子句 (conj.phr.)：只有在……條件下才……\n【中譯】只有在你買兩杯飲料的情況下，才能得到一個免費蛋糕；如果你只買一杯，就必須付錢買蛋糕。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 892, "question": "Dad never drinks coffee, so Mom bought him ______ for his birthday.", "options": ["not only coffee but also tea", "not coffee but tea", "both coffee and tea", "coffee as well as tea"], "answer": 1, "answerLabel": "B", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(B) not coffee but tea\n【用語】not A but B (conj.phr.)：不是A而是B\n【中譯】爸爸從不喝咖啡，所以媽媽買給他的生日禮物不是咖啡而是茶。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 893, "question": "Ben eats ______ he hasn't eaten for days, but he just had lunch an hour ago.", "options": ["as if", "as soon as", "in case", "now that"], "answer": 0, "answerLabel": "A", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(A) as if\n【用語】as if + 子句 (conj.phr.)：彷彿、好像\n【中譯】班吃東西的樣子好像他好幾天沒吃東西了，但他一小時前才剛吃過午餐。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 894, "question": "Ken can speak ______, so he often helps visitors from America and Japan.", "options": ["English as well as Japanese", "not English but Japanese", "neither English nor Japanese", "English rather than Japanese"], "answer": 0, "answerLabel": "A", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(A) English as well as Japanese\n【用語】as well as (conj.phr.)：以及；和\n【中譯】肯會說英文以及日文，所以他常常幫助來自美國和日本的遊客。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 895, "question": "There is only one seat left in the car, so ______ can come with us.", "options": ["neither Tom nor Ben", "both Tom and Ben", "not only Tom but also Ben", "either Tom or Ben"], "answer": 3, "answerLabel": "D", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(D) either Tom or Ben\n【用語】either A or B (conj.phr.)：不是……就是……\n【中譯】車上只剩一個座位，所以不是湯姆就是班可以跟我們一起去。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 896, "question": "______ it was raining hard, Lily still walked to school.", "options": ["As soon as", "So that", "In case", "Even though"], "answer": 3, "answerLabel": "D", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(D) Even though\n【用語】even though + 子句 (conj.phr.)：雖然、即使\n【中譯】雖然雨下得很大，莉莉還是走路去上學。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 897, "question": "Amy is very busy after school because she learns ______; she has piano class on Monday and swimming class on Friday.", "options": ["either piano or swimming", "neither piano nor swimming", "not only piano but also swimming", "not piano but swimming"], "answer": 2, "answerLabel": "C", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(C) not only piano but also swimming\n【用語】not only A but also B (conj.phr.)：不僅A而且B\n【中譯】艾美放學後很忙，因為她不僅學鋼琴，而且還學游泳；她星期一上鋼琴課，星期五上游泳課。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 898, "question": "My grandma looks ______ she is fifty, but she is really seventy.", "options": ["as soon as", "in case", "only if", "as though"], "answer": 3, "answerLabel": "D", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(D) as though\n【用語】as though (conj.phr.)：彷彿；好像（= as if）\n【中譯】我奶奶看起來好像五十歲，但她其實七十歲了。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 899, "question": "The soup was ______ I couldn't eat it right away, so I waited for ten minutes.", "options": ["hot in case", "so hot that", "hot as if", "hot even though"], "answer": 1, "answerLabel": "B", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(B) so hot that\n【用語】so + adj./adv. + that 子句 (conj.phr.)：如此……以致於……\n【中譯】湯如此燙，以致於我無法馬上喝，所以我等了十分鐘。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 900, "question": "Bring a jacket ______ it gets cold at night in the mountains.", "options": ["in case", "so that", "as though", "even though"], "answer": 0, "answerLabel": "A", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(A) in case\n【用語】in case + 子句 (conj.phr.)：萬一；以防\n【中譯】帶件外套，以防山上晚上變冷。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 901, "question": "It was ______ we all went swimming in the river.", "options": ["a hot day as if", "such a hot day that", "a hot day in case", "a hot day even though"], "answer": 1, "answerLabel": "B", "source": "連接詞片語 Conjunction Phrases｜連接詞片語 Conjunction Phrases", "explanation": "【答案】(B) such a hot day that\n【用語】such + N + that 子句 (conj.phr.)：如此……以致於……\n【中譯】那天是如此炎熱的一天，以致於我們全都去河裡游泳了。", "explanationSource": "supplemental", "section": "連接詞片語 Conjunction Phrases"}, {"id": 902, "question": "I'm going to ______ near my home to buy some milk; it is open 24 hours a day.", "options": ["a convenience store", "a matter of life and death", "a parking lot", "a hot air balloon"], "answer": 0, "answerLabel": "A", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(A) a convenience store\n【用語】convenience store (n.phr.)：便利商店\n【中譯】我要去我家附近的便利商店買牛奶；它一天24小時都營業。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 903, "question": "Tom couldn't get into his house because he lost ______ the front door.", "options": ["the key to", "the answer to", "the solution to", "the road to"], "answer": 0, "answerLabel": "A", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(A) the key to\n【用語】the key to + N (n.phr.)：（門）的鑰匙\n【中譯】湯姆進不了家，因為他弄丟了前門的鑰匙。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 904, "question": "For breakfast, Dad put an egg without its shell into hot water and made ______.", "options": ["a fried egg", "a chance of a lifetime", "a poached egg", "a lit candle"], "answer": 2, "answerLabel": "C", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(C) a poached egg\n【用語】poached egg (n.phr.)：水波蛋\n【中譯】早餐時，爸爸把一顆去殼的蛋放進熱水裡，做了一顆水波蛋。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 905, "question": "For homework, we have to write ______ about how plants grow in the sun.", "options": ["a sense of smell", "the former", "a health checkup", "a science report"], "answer": 3, "answerLabel": "D", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(D) a science report\n【用語】science report (n.phr.)：科學報告\n【中譯】我們的作業是要寫一份關於植物如何在陽光下生長的科學報告。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 906, "question": "When I scored a goal, my coach smiled and gave me ______ to say \"Good job!\"", "options": ["a thumbs up", "an amusement park", "anyone else", "a heat wave"], "answer": 0, "answerLabel": "A", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(A) a thumbs up\n【用語】thumbs up (n.phr.)：比讚（手勢）\n【中譯】當我進球時，教練微笑著對我比讚，表示「做得好！」", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 907, "question": "Before bed, Grandma told us ______ about a princess and a magic frog.", "options": ["a power plant", "a fairy tale", "a common behavior", "a wet blanket"], "answer": 1, "answerLabel": "B", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(B) a fairy tale\n【用語】fairy tale (n.phr.)：童話故事\n【中譯】睡前，奶奶跟我們說了一個關於公主和魔法青蛙的童話故事。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 908, "question": "Mom cooked ______ in hot oil and put it on my toast for breakfast.", "options": ["a fried egg", "a back door", "a balanced diet", "a straight line"], "answer": 0, "answerLabel": "A", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(A) a fried egg\n【用語】fried egg (n.phr.)：煎蛋\n【中譯】媽媽用熱油煎了一顆煎蛋，放在我的吐司上當早餐。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 909, "question": "We bought two movie tickets at the ______ before the show started.", "options": ["lost and found", "box office", "matching colors", "deep water"], "answer": 1, "answerLabel": "B", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(B) box office\n【用語】box office (n.phr.)：售票處；票房\n【中譯】我們在電影開演前，在售票處買了兩張電影票。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 910, "question": "In the comedy movie, a shy boy used a silly ______, \"Are you a camera? I smile every time I see you!\" and everyone in the theater laughed.", "options": ["health care", "pick-up line", "carry-on luggage", "bow tie"], "answer": 1, "answerLabel": "B", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(B) pick-up line\n【用語】pick-up line (n.phr.)：搭訕台詞\n【中譯】在那部喜劇電影裡，一個害羞的男孩用了一句很蠢的搭訕台詞：「你是相機嗎？每次看到你我都會笑！」電影院裡的每個人都笑了。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 911, "question": "Our ______ showed us around the old town and told us about its history.", "options": ["washing machine", "odd number", "hard-boiled egg", "tour guide"], "answer": 3, "answerLabel": "D", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(D) tour guide\n【用語】tour guide (n.phr.)：導遊\n【中譯】我們的導遊帶我們參觀老城區，並告訴我們它的歷史。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 912, "question": "Amy is a ______ of that singer; she waits outside his hotel all night just to see him.", "options": ["straight hair", "light blue", "dollar bill", "crazy fan"], "answer": 3, "answerLabel": "D", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(D) crazy fan\n【用語】crazy fan (n.phr.)：瘋狂粉絲\n【中譯】艾咪是那位歌手的瘋狂粉絲；她整晚在他的飯店外面等，只為了見他一面。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 913, "question": "From the top of Taipei 101, you can enjoy a beautiful ______ at night.", "options": ["middle class", "low-cost airline", "city view", "wet blanket"], "answer": 2, "answerLabel": "C", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(C) city view\n【用語】city view (n.phr.)：城市景觀\n【中譯】從台北101的頂樓，你可以在晚上欣賞美麗的城市景觀。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 914, "question": "Please keep ______ when you hear new ideas from your classmates.", "options": ["a guide dog", "an open mind", "a dollar bill", "a cooking skill"], "answer": 1, "answerLabel": "B", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(B) an open mind\n【用語】open mind (n.phr.)：開放的心胸；不持偏見的態度\n【中譯】當你聽到同學的新想法時，請保持開放的心胸。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 915, "question": "Before buying the shoes online, I read the ______ to see if they were comfortable.", "options": ["buyers' feedback", "book review", "movie review", "big screen"], "answer": 0, "answerLabel": "A", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(A) buyers' feedback\n【用語】buyers' feedback (n.phr.)：買家回饋\n【中譯】在網路上買這雙鞋之前，我先看了買家回饋，看看它們穿起來舒不舒服。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 916, "question": "With a ______, you can take the bus as many times as you want today.", "options": ["make-up test", "washing machine", "daily pass", "online course"], "answer": 2, "answerLabel": "C", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(C) daily pass\n【用語】daily pass (n.phr.)：一日通行證\n【中譯】有了一日通行證，你今天想搭幾次公車就可以搭幾次。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 917, "question": "Disneyland is a famous ______ built around cartoon stories and characters.", "options": ["wine bar", "regular exercise", "theme park", "power plant"], "answer": 2, "answerLabel": "C", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(C) theme park\n【用語】theme park (n.phr.)：主題樂園\n【中譯】迪士尼樂園是一座以卡通故事和角色為主題打造的著名主題樂園。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 918, "question": "______ students are absent today, maybe five or six, so the classroom is quiet.", "options": ["A large amount of", "A bowl of", "A number of", "A pair of"], "answer": 2, "answerLabel": "C", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(C) A number of\n【用語】a number of + N (n.phr.)：一些、若干\n【中譯】今天有一些學生缺席，大概五、六個，所以教室很安靜。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 919, "question": "In P.E. class, we played ______; we threw a ball at the other team and tried not to get hit.", "options": ["hot air balloons", "dodge ball", "concert tickets", "board games"], "answer": 1, "answerLabel": "B", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(B) dodge ball\n【用語】dodge ball (n.phr.)：躲避球\n【中譯】體育課時，我們玩躲避球；我們把球丟向對方隊伍，並試著不被打到。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 920, "question": "______ Tim lied to his best friend made her very sad.", "options": ["Plenty of", "A couple of", "The fact that", "A large number of"], "answer": 2, "answerLabel": "C", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(C) The fact that\n【用語】the fact that + 子句 (n.phr.)：……這個事實\n【中譯】提姆對他最好的朋友說謊這個事實讓她非常難過。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 921, "question": "My dad is my ______; I want to be kind and hard-working like him.", "options": ["action movie", "model student", "cover model", "role model"], "answer": 3, "answerLabel": "D", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(D) role model\n【用語】role model (n.phr.)：榜樣；學習對象\n【中譯】我爸爸是我的榜樣；我想要像他一樣善良又勤奮。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 922, "question": "The car almost hit the boy, but he jumped away just in time. It was ______.", "options": ["a model student", "a narrow escape", "the environment", "a common cold"], "answer": 1, "answerLabel": "B", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(B) a narrow escape\n【用語】a narrow escape (n.phr.)：千鈞一髮；死裡逃生\n【中譯】那輛車差點撞到男孩，但他及時跳開了。真是千鈞一髮。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 923, "question": "Many students write \"informations,\" but this is ______ in English.", "options": ["a role model", "a common mistake", "a boiled egg", "greenhouse gases"], "answer": 1, "answerLabel": "B", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(B) a common mistake\n【用語】a common mistake (n.phr.)：常見的錯誤\n【中譯】很多學生會寫「informations」，但這是英文中常見的錯誤。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 924, "question": "This restaurant adds ______ of 10% to your bill.", "options": ["a service fee", "a hit", "a garage sale", "the following"], "answer": 0, "answerLabel": "A", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(A) a service fee\n【用語】service fee (n.phr.)：服務費\n【中譯】這家餐廳會在你的帳單上加收10%的服務費。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 925, "question": "Your essay is good, but there is still ______, so check your spelling again.", "options": ["a common friend", "graduate school", "the job market", "room for improvement"], "answer": 3, "answerLabel": "D", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(D) room for improvement\n【用語】room for improvement (n.phr.)：進步的空間\n【中譯】你的作文寫得不錯，但還有進步的空間，所以再檢查一次拼字吧。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 926, "question": "Grandpa's ______ his grandchildren is very deep; he calls them every day.", "options": ["key to", "love for", "way to", "use of"], "answer": 1, "answerLabel": "B", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(B) love for\n【用語】love for + 人 (n.phr.)：對……的愛\n【中譯】爺爺對孫子們的愛很深；他每天都打電話給他們。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 927, "question": "The ______ near the river makes electricity for the whole city.", "options": ["living costs", "air fryer", "power plant", "sharp knife"], "answer": 2, "answerLabel": "C", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(C) power plant\n【用語】power plant (n.phr.)：發電廠\n【中譯】河邊的那座發電廠為整座城市發電。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 928, "question": "For people in this small village, farming is not just a job; it is ______.", "options": ["a way of life", "a computer bug", "a bow tie", "an air fryer"], "answer": 0, "answerLabel": "A", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(A) a way of life\n【用語】a way of life (n.phr.)：生活方式\n【中譯】對這個小村莊的人來說，務農不只是一份工作，更是一種生活方式。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 929, "question": "On the MRT, please give the ______ to old people and people in need.", "options": ["priority seat", "Super Bowl", "computer bug", "straight line"], "answer": 0, "answerLabel": "A", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(A) priority seat\n【用語】priority seat (n.phr.)：博愛座\n【中譯】在捷運上，請把博愛座讓給老人和有需要的人。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 930, "question": "Your essay must be under 200 words, so check the ______ before you hand it in.", "options": ["past experience", "total word count", "shelf life", "bow tie"], "answer": 1, "answerLabel": "B", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(B) total word count\n【用語】total word count (n.phr.)：字數總計\n【中譯】你的作文必須少於200字，所以交出去之前要檢查字數總計。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 931, "question": "All students have ______ the computers in the library, so they can use them after class.", "options": ["the solution to", "the answer to", "a ticket to", "access to"], "answer": 3, "answerLabel": "D", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(D) access to\n【用語】access to + N (n.phr.)：有使用……途徑、管道\n【中譯】所有學生都有使用圖書館電腦的管道，所以他們下課後可以使用。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 932, "question": "Mr. and Mrs. Wang got married in 1990; they have been ______ for more than thirty years.", "options": ["a shelf life", "a common friend", "a swine flu", "a couple"], "answer": 3, "answerLabel": "D", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(D) a couple\n【用語】a couple (n.phr.)：情侶；一對戀人\n【中譯】王先生和王太太在1990年結婚；他們成為一對夫妻已經三十多年了。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 933, "question": "Our coach says practicing every day is ______; you can't win without it.", "options": ["the lower class", "the final decision", "the key to success", "the big screen"], "answer": 2, "answerLabel": "C", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(C) the key to success\n【用語】the key to success (n.phr.)：成功的關鍵\n【中譯】我們教練說每天練習是成功的關鍵；沒有它你就贏不了。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 934, "question": "Oil and coal are ______, and burning them makes the air dirty.", "options": ["social classes", "health checkups", "eye drops", "fossil fuels"], "answer": 3, "answerLabel": "D", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(D) fossil fuels\n【用語】fossil fuel (n.phr.)：化石燃料（如石油、煤等）\n【中譯】石油和煤是化石燃料，燃燒它們會讓空氣變髒。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 935, "question": "My uncle loves loud and fast music like ______.", "options": ["swine flu", "a tie", "rock and roll", "a changed man"], "answer": 2, "answerLabel": "C", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(C) rock and roll\n【用語】rock and roll (n.phr.)：搖滾樂\n【中譯】我叔叔喜歡像搖滾樂這種又大聲又快的音樂。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 936, "question": "Our school uses ______ like solar power because it doesn't hurt nature.", "options": ["the Super Bowl", "living costs", "green energy", "a sharp eye"], "answer": 2, "answerLabel": "C", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(C) green energy\n【用語】green energy (n.phr.)：綠色能源（環保能源）\n【中譯】我們學校使用像太陽能這樣的綠色能源，因為它不會傷害大自然。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 937, "question": "I ate ______ cake, so there was only a small piece left for my sister.", "options": ["a large number of", "most of the", "a pair of", "a couple of"], "answer": 1, "answerLabel": "B", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(B) most of the\n【用語】most of the + N (n.phr.)：大部分的\n【中譯】我吃掉了大部分的蛋糕，所以只剩一小塊給我妹妹。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 938, "question": "I didn't bring any cash, so I paid for the shoes with my ______.", "options": ["credit card", "eye drops", "book report", "candy bar"], "answer": 0, "answerLabel": "A", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(A) credit card\n【用語】credit card (n.phr.)：信用卡\n【中譯】我沒帶現金，所以用我的信用卡付了鞋子的錢。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 939, "question": "It's cold today, so I'd like ______ hot soup.", "options": ["a large number of", "a couple of", "a bowl of", "a pair of"], "answer": 2, "answerLabel": "C", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(C) a bowl of\n【用語】a bowl of + N (n.phr.)：一碗⋯⋯（如一碗飯）\n【中譯】今天很冷，所以我想要一碗熱湯。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 940, "question": "Many young people in this town help ______ cross the street and carry heavy bags.", "options": ["the computer virus", "the elderly", "the make-up test", "the job market"], "answer": 1, "answerLabel": "B", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(B) the elderly\n【用語】the elderly (n.phr.)：年長者；老人\n【中譯】這個鎮上很多年輕人會幫老人過馬路和提重的袋子。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 941, "question": "My brother watches TV on the sofa all day and never exercises; he is ______.", "options": ["a model student", "the others", "a couch potato", "a serious earthquake"], "answer": 2, "answerLabel": "C", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(C) a couch potato\n【用語】couch potato (n.phr.)：愛看電視、不運動的人（懶人）\n【中譯】我哥哥整天在沙發上看電視，從不運動；他是個沙發馬鈴薯（懶人）。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 942, "question": "At the hotel, we had ______: soup, salad, fish, steak, and dessert.", "options": ["renewable energy", "environmental protection", "a straight line", "a five-course meal"], "answer": 3, "answerLabel": "D", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(D) a five-course meal\n【用語】five-course meal (n.phr.)：五道菜的套餐\n【中譯】在飯店裡，我們吃了五道菜的套餐：湯、沙拉、魚、牛排和甜點。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 943, "question": "Amy and I are best friends, so we often help ______ with our homework.", "options": ["each other", "breaking news", "a wild party", "anything else"], "answer": 0, "answerLabel": "A", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(A) each other\n【用語】each other (n.phr.)：彼此（兩者之間）\n【中譯】艾咪和我是最好的朋友，所以我們常常互相幫忙寫功課。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 944, "question": "2, 4, and 6 are ______, but 3 is not.", "options": ["serious injuries", "cell phone screens", "odd numbers", "even numbers"], "answer": 3, "answerLabel": "D", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(D) even numbers\n【用語】even number (n.phr.)：偶數\n【中譯】2、4和6是偶數，但3不是。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 945, "question": "There are no clouds today; look at the beautiful ______!", "options": ["straight hair", "wine bar", "common belief", "clear sky"], "answer": 3, "answerLabel": "D", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(D) clear sky\n【用語】clear sky (n.phr.)：晴朗的天空\n【中譯】今天一朵雲都沒有；看看這美麗晴朗的天空！", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 946, "question": "Mom bought ______ at the supermarket, twelve in one box.", "options": ["a dozen eggs", "a big deal", "an all-kill", "a final exam"], "answer": 0, "answerLabel": "A", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(A) a dozen eggs\n【用語】a dozen eggs (n.phr.)：一打蛋\n【中譯】媽媽在超市買了一打蛋，一盒十二顆。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 947, "question": "Ms. Lin is tired of the ______ who never listens and always runs around in class.", "options": ["wild student", "model student", "reward point", "check-in luggage"], "answer": 0, "answerLabel": "A", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(A) wild student\n【用語】wild student (n.phr.)：狂野不受教的學生\n【中譯】林老師對那個從不聽話、總是在課堂上跑來跑去的狂野不受教的學生感到很疲憊。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 948, "question": "Don't worry. It's just ______, so drink some hot water and get some rest.", "options": ["a common cold", "a serious typhoon", "answers to the questions", "a dozen eggs"], "answer": 0, "answerLabel": "A", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(A) a common cold\n【用語】a common cold (n.phr.)：普通感冒\n【中譯】別擔心，這只是普通感冒，所以喝點熱水、好好休息吧。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 949, "question": "Excuse me, is this ______ to the train station? I want to walk there.", "options": ["the dollar bill", "the computer screen", "the road", "one another"], "answer": 2, "answerLabel": "C", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(C) the road\n【用語】the road to + N (n.phr.)：通往⋯⋯的道路\n【中譯】不好意思，這是通往火車站的路嗎？我想走路過去。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 950, "question": "My aunt told my cousin to be careful when she chats with strangers on a ______ on her phone.", "options": ["dating app", "fitting room", "job market", "credit card"], "answer": 0, "answerLabel": "A", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(A) dating app\n【用語】dating app (n.phr.)：約會應用程式\n【中譯】我阿姨提醒我表姊，在手機上的約會應用程式和陌生人聊天時要小心。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 951, "question": "The four of us will work together on our ______ about night markets this week.", "options": ["heat wave", "group report", "enough time", "eye drops"], "answer": 1, "answerLabel": "B", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(B) group report\n【用語】group report (n.phr.)：小組報告\n【中譯】我們四個人這週會一起合作完成關於夜市的小組報告。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 952, "question": "Tom played the video game all night to get more ______ and win a new sword in the game.", "options": ["game points", "job interviews", "greenhouse gases", "bird flu"], "answer": 0, "answerLabel": "A", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(A) game points\n【用語】game points (n.phr.)：遊戲點數\n【中譯】湯姆整晚玩電玩，想賺更多遊戲點數，贏得遊戲裡的一把新劍。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 953, "question": "Our English teacher has ______, so everyone can hear her well in the big classroom.", "options": ["a sharp knife", "a clear voice", "every corner of the world", "a die-hard fan"], "answer": 1, "answerLabel": "B", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(B) a clear voice\n【用語】clear voice (n.phr.)：清晰的聲音\n【中譯】我們的英文老師有清晰的聲音，所以在大教室裡每個人都能聽清楚她說話。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 954, "question": "Amy can't skate in the park today because she lost ______.", "options": ["the above", "a bow tie", "her point of view", "one roller skate"], "answer": 3, "answerLabel": "D", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(D) one roller skate\n【用語】roller skate (n.phr.)：輪式溜冰鞋\n【中譯】艾咪今天不能在公園溜冰，因為她弄丟了一隻輪式溜冰鞋。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 955, "question": "Kevin read the short story three times because it has ______ that is hard to understand.", "options": ["a fried egg", "pop music", "a deep idea", "the way you sing"], "answer": 2, "answerLabel": "C", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(C) a deep idea\n【用語】deep idea (n.phr.)：深奧的想法\n【中譯】凱文把這篇短篇故事讀了三遍，因為它有一個難以理解的深奧想法。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 956, "question": "My ______ is three years older than me, and she is in high school now.", "options": ["aging society", "elder sister", "fairy tale", "wild animal"], "answer": 1, "answerLabel": "B", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(B) elder sister\n【用語】elder sister/brother (n.phr.)：姐姐／哥哥\n【中譯】我姐姐比我大三歲，她現在讀高中。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 957, "question": "My aunt's friend set up a ______ for her, so she will have dinner with a man she has never met before.", "options": ["work of art", "rock concert", "garage sale", "blind date"], "answer": 3, "answerLabel": "D", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(D) blind date\n【用語】blind date (n.phr.)：相親；事先不認識的約會\n【中譯】我阿姨的朋友幫她安排了一場相親，所以她將會和一個從未見過的男人共進晚餐。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 958, "question": "My school uniform is ______, the same color as the night sky.", "options": ["light blue", "straight hair", "dark blue", "chocolate bar"], "answer": 2, "answerLabel": "C", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(C) dark blue\n【用語】dark blue (n.phr.)：深藍色\n【中譯】我的學校制服是深藍色的，和夜空的顏色一樣。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 959, "question": "The night market sells ______ snacks, so you can try many different foods there.", "options": ["a pair of", "a variety of", "a bowl of", "a couple of"], "answer": 1, "answerLabel": "B", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(B) a variety of\n【用語】a variety of + N (n.phr.)：多樣的\n【中譯】夜市賣各式各樣的小吃，所以你可以在那裡嚐到許多不同的食物。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 960, "question": "The doctor told me to put ______ into my eyes twice a day.", "options": ["a credit card", "the answer to the question", "a candy bar", "eye drops"], "answer": 3, "answerLabel": "D", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(D) eye drops\n【用語】eye drops (n.phr.)：眼藥水\n【中譯】醫生叫我一天點兩次眼藥水。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 961, "question": "Riding a bike is a cheap and healthy ______ getting to school.", "options": ["use of", "lost and found", "couch potato", "way of"], "answer": 3, "answerLabel": "D", "source": "名詞片語（含數量詞） Noun &amp; Quantity Phrases｜名詞片語（含數量詞） Noun & Quantity Phrases", "explanation": "【答案】(D) way of\n【用語】way of + V-ing (n.phr.)：做……的方法\n【中譯】騎腳踏車是一種便宜又健康的上學方法。", "explanationSource": "supplemental", "section": "名詞片語（含數量詞） Noun &amp; Quantity Phrases"}, {"id": 962, "question": "A: I just won a free trip to Japan!\nB: ______ You never win anything!", "options": ["I get it.", "Are you kidding?", "See you later.", "What do you have in mind?"], "answer": 1, "answerLabel": "B", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(B) Are you kidding?\n【用語】Are you kidding? (phr.)：你在開玩笑吧？\n【中譯】A：我剛贏得一趟免費的日本之旅！\nB：你在開玩笑吧？你從來沒贏過任何東西！", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 963, "question": "A: I'm going to eat Tom's ice cream in the fridge.\nB: ______ He gets really angry when people take his food.", "options": ["I have seen this movie before.", "So long.", "What a play!", "Don't cross him."], "answer": 3, "answerLabel": "D", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(D) Don't cross him.\n【用語】Don't cross + 人. (phr.)：別惹⋯⋯生氣\n【中譯】A：我要去吃冰箱裡湯姆的冰淇淋。\nB：別惹他生氣。別人拿他的食物時，他會非常生氣。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 964, "question": "A: The concert tickets are on sale for only one more hour. Should I buy one?\nB: ______ Buy it right now!", "options": ["It's now or never.", "It turns out that the shop is closed.", "An earthquake hit the town.", "I'll pass."], "answer": 0, "answerLabel": "A", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(A) It's now or never.\n【用語】It's now or never. (phr.)：機不可失；此時不做更待何時\n【中譯】A：演唱會門票只剩一個小時可以買。我該買一張嗎？\nB：機不可失。現在馬上買！", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 965, "question": "A: I think we should have the class party on Friday.\nB: ______ Friday is the best day for everyone.", "options": ["Talk to you later.", "It's time for lunch.", "I second that.", "Seeing is believing."], "answer": 2, "answerLabel": "C", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(C) I second that.\n【用語】I second that. (phr.)：我附議／我贊同（正式或幽默用法）\n【中譯】A：我認為我們應該在星期五辦班級派對。\nB：我贊同。星期五對大家來說是最好的日子。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 966, "question": "A: How was the sunrise at Alishan?\nB: ______ I have never seen anything so beautiful.", "options": ["It took my breath away.", "It doesn't count.", "It is here to stay.", "It cost an arm and a leg."], "answer": 0, "answerLabel": "A", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(A) It took my breath away.\n【用語】take + 人's breath away (phr.)：令人屏息；令人驚艷\n【中譯】A：阿里山的日出怎麼樣？\nB：它美得令我屏息。我從來沒看過這麼美的東西。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 967, "question": "A: Do you mind if I open the window?\nB: ______ Go ahead.", "options": ["I don't mind.", "What a play!", "Good things never last.", "It's too expensive, though."], "answer": 0, "answerLabel": "A", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(A) I don't mind.\n【用語】I don't mind. (phr.)：我不介意\n【中譯】A：你介意我打開窗戶嗎？\nB：我不介意。請便。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 968, "question": "At the end of her birthday card to Grandma, Amy wrote, \"______, Amy.\"", "options": ["Best wishes", "Poor as a church mouse", "Trick or treat", "There is a market for cards"], "answer": 0, "answerLabel": "A", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(A) Best wishes\n【用語】Best wishes (phr.)：致上最誠摯的祝福\n【中譯】在給奶奶的生日卡片最後，艾咪寫道：「致上最誠摯的祝福，艾咪。」", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 969, "question": "A: Who will buy the drinks for the party?\nB: ______ I already bought ten bottles of juice.", "options": ["I don't know when the party will start.", "I've got it covered.", "I turned a blind eye to it.", "My mind went blank."], "answer": 1, "answerLabel": "B", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(B) I've got it covered.\n【用語】I've got it covered. (phr.)：搞定；處理好了\n【中譯】A：誰要買派對的飲料？\nB：我搞定了。我已經買了十瓶果汁。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 970, "question": "A: You ran ten kilometers this morning. Are you tired?\nB: ______ I feel great!", "options": ["The more, the merrier.", "I'm not tired at all.", "Do you mind helping me?", "I don't get it."], "answer": 1, "answerLabel": "B", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(B) I'm not tired at all.\n【用語】not + V/adj. + at all (phr.)：一點也不……、完全不……\n【中譯】A：你今天早上跑了十公里。你累嗎？\nB：我一點也不累。我覺得很棒！", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 971, "question": "A: That new boy looks scary. I don't want to talk to him.\nB: ______ He is actually very kind.", "options": ["Don't judge a book by its cover.", "Understood?", "Good things never last.", "It doesn't count."], "answer": 0, "answerLabel": "A", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(A) Don't judge a book by its cover.\n【用語】Don't judge a book by its cover. (phr.)：不可貌相；別以貌取人\n【中譯】A：那個新來的男孩看起來很可怕。我不想跟他說話。\nB：人不可貌相。他其實非常善良。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 972, "question": "The teacher said, \"______ Please put down your pencils and hand in your test papers.\"", "options": ["Do you get it?", "What's up?", "Chances are that it will rain.", "Time is up."], "answer": 3, "answerLabel": "D", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(D) Time is up.\n【用語】Time is up. (phr.)：時間到了\n【中譯】老師說：「時間到了。請放下鉛筆，交出你們的考卷。」", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 973, "question": "A: Mom, can I play video games now?\nB: ______ Finish your homework, and then you can play.", "options": ["What else do you want to do?", "What a play!", "It's on me.", "First things first."], "answer": 3, "answerLabel": "D", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(D) First things first.\n【用語】First things first. (phr.)：要事第一；先做重要的事\n【中譯】A：媽，我現在可以玩電動嗎？\nB：先做重要的事。把你的功課寫完，然後你就可以玩。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 974, "question": "A: Dad, can I skip washing the dishes tonight?\nB: No. You promised to wash them if I bought you the new game. ______", "options": ["Way to go.", "The report says that it will rain.", "That was close.", "A deal is a deal."], "answer": 3, "answerLabel": "D", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(D) A deal is a deal.\n【用語】A deal is a deal. (phr.)：說好的事就要算數\n【中譯】A：爸，我今晚可以不洗碗嗎？\nB：不行。你答應過如果我買新遊戲給你，你就會洗碗。說好的事就要算數。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 975, "question": "A: How was the math test?\nB: ______ I finished it in ten minutes and got 100.", "options": ["Way to go.", "It doesn't matter if I pass.", "It's beyond me.", "It was a piece of cake."], "answer": 3, "answerLabel": "D", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(D) It was a piece of cake.\n【用語】a piece of cake (phr.)：輕而易舉\n【中譯】A：數學考試怎麼樣？\nB：輕而易舉。我十分鐘就寫完，還考了一百分。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 976, "question": "A: Is Jenny coming to your birthday party?\nB: ______ She hasn't answered my message yet.", "options": ["What a play!", "There's no way through.", "I don't know if she will come.", "One is red, and the other is blue."], "answer": 2, "answerLabel": "C", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(C) I don't know if she will come.\n【用語】S + V + if + 未來式 (phr.)：間接問句：未來是否會發生某事（= whether）\n【中譯】A：珍妮會來你的生日派對嗎？\nB：我不知道她會不會來。她還沒回我的訊息。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 977, "question": "A: Look at those birds in the sky.\nB: ______ Then I could go anywhere I like.", "options": ["Leave me alone.", "If only I could fly!", "Trick or treat!", "Honesty is the best policy."], "answer": 1, "answerLabel": "B", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(B) If only I could fly!\n【用語】If only + 子句 (phr.)：但願、要是……多好\n【中譯】A：看天空中的那些鳥。\nB：要是我會飛就好了！那我就可以去任何我想去的地方。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 978, "question": "A: Why did the chicken cross the road? To get to the other side! Ha ha!\nB: ______ Why is that funny?", "options": ["I'll call you later.", "I don't get it.", "You can say that again.", "It's on me."], "answer": 1, "answerLabel": "B", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(B) I don't get it.\n【用語】I don't get it. (phr.)：我不懂\n【中譯】A：雞為什麼要過馬路？為了到另一邊去！哈哈！\nB：我不懂。那有什麼好笑的？", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 979, "question": "A: I'm afraid to try skydiving.\nB: Come on! ______ Try something new and enjoy your life!", "options": ["Oh my goodness!", "What's your take on the movie?", "Don't push me.", "You only live once."], "answer": 3, "answerLabel": "D", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(D) You only live once.\n【用語】You only live once. (phr.)：人生只有一次；及時行樂\n【中譯】A：我不敢嘗試跳傘。\nB：拜託！人生只有一次。嘗試新事物，享受你的人生！", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 980, "question": "A: Tom, you have played with the ball for twenty minutes. ______ Give it to me, please.\nB: OK, here you are.", "options": ["It's your call.", "It's beyond me.", "Who else is coming?", "It's my turn."], "answer": 3, "answerLabel": "D", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(D) It's my turn.\n【用語】It's my turn. (phr.)：輪到我了\n【中譯】A：湯姆，你已經玩球玩了二十分鐘了。輪到我了。請把球給我。\nB：好，給你。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 981, "question": "A: ______\nB: Yes, I went to Tokyo with my family last summer.", "options": ["How about going to the park?", "Don't bother me.", "Have you ever been to Japan?", "What's up?"], "answer": 2, "answerLabel": "C", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(C) Have you ever been to Japan?\n【用語】Have you ever been to + 地方? (phr.)：你曾經去過⋯⋯嗎？\n【中譯】A：你曾經去過日本嗎？\nB：有，我去年夏天和家人去了東京。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 982, "question": "A: I didn't finish my homework last night.\nB: ______ I fell asleep at eight o'clock.", "options": ["I couldn't agree more.", "What's the catch?", "Neither did I.", "The box is too heavy to carry."], "answer": 2, "answerLabel": "C", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(C) Neither did I.\n【用語】Neither + 助動詞/be動詞 + 主詞. (phr.)：（前句否定）⋯⋯也不\n【中譯】A：我昨晚沒寫完功課。\nB：我也沒有。我八點就睡著了。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 983, "question": "Good evening, everyone. ______ introduce our special guest tonight, the singer Amy Lin.", "options": ["It costs me a lot to", "Even a baby can", "It's my pleasure to", "I'm old enough to"], "answer": 2, "answerLabel": "C", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(C) It's my pleasure to\n【用語】It's my pleasure to + VR (phr.)：很樂意做⋯⋯／是我的榮幸做⋯⋯\n【中譯】大家晚安。我很榮幸為大家介紹今晚的特別來賓，歌手林艾咪。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 984, "question": "A: Should we eat pizza or noodles tonight?\nB: I like both. ______ You can choose.", "options": ["What's the matter?", "So long.", "That was close.", "It's your call."], "answer": 3, "answerLabel": "D", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(D) It's your call.\n【用語】It's your call. (phr.)：由你決定；看你怎麼選\n【中譯】A：我們今晚該吃披薩還是麵？\nB：兩個我都喜歡。由你決定。你可以選。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 985, "question": "A: Hurry! The last bus leaves in three minutes!\nB: OK! ______", "options": ["I'll run as fast as possible.", "What kinds of games do you like?", "Trick or treat!", "It's my turn."], "answer": 0, "answerLabel": "A", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(A) I'll run as fast as possible.\n【用語】as + adj./adv. + as possible (phr.)：盡可能（地）……\n【中譯】A：快點！末班公車三分鐘後就要開了！\nB：好！我會盡可能跑快一點。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 986, "question": "A: This new phone is only 100 dollars, and you get a free computer with it!\nB: Only 100 dollars? ______", "options": ["The last thing I want to do is study.", "Way to go.", "What's the catch?", "She is in her teens."], "answer": 2, "answerLabel": "C", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(C) What's the catch?\n【用語】What's the catch? (phr.)：有什麼陷阱？（口語）\n【中譯】A：這支新手機只要一百元，而且還送你一台電腦！\nB：只要一百元？有什麼陷阱？", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 987, "question": "A: Did you copy Tom's answers on the test?\nB: Of course not! ______", "options": ["That's the last thing I would do.", "Never mind.", "There is no use crying.", "It cost an arm and a leg."], "answer": 0, "answerLabel": "A", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(A) That's the last thing I would do.\n【用語】the last thing I would do (phr.)：我最不可能做的事\n【中譯】A：你考試時抄湯姆的答案嗎？\nB：當然沒有！那是我最不可能做的事。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 988, "question": "A: Is your brother taller than you?\nB: No. ______ We are both 160 centimeters.", "options": ["What's up?", "He is as tall as I am.", "After he comes home, he will eat dinner.", "It doesn't count."], "answer": 1, "answerLabel": "B", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(B) He is as tall as I am.\n【用語】as + adj./adv.(原級) + as (phr.)：跟⋯⋯一樣⋯⋯\n【中譯】A：你哥哥比你高嗎？\nB：沒有。他跟我一樣高。我們都是一百六十公分。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 989, "question": "A: Should I wear the red shirt or the blue one to the party?\nB: Both look nice on you. ______", "options": ["It's up to you.", "Oh my goodness!", "It cost me 500 dollars to buy it.", "Trick or treat!"], "answer": 0, "answerLabel": "A", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(A) It's up to you.\n【用語】It's up to you. (phr.)：由你決定；看你怎麼選\n【中譯】A：我該穿紅色還是藍色的襯衫去派對？\nB：兩件你穿都好看。由你決定。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 990, "question": "A: Did you really see a famous singer at the MRT station?\nB: ______ I even took a photo with her!", "options": ["No kidding.", "It's one of the tallest buildings in the world.", "I don't buy it.", "Never mind."], "answer": 0, "answerLabel": "A", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(A) No kidding.\n【用語】No kidding. (phr.)：不騙你；真的\n【中譯】A：你真的在捷運站看到一位有名的歌手嗎？\nB：不騙你。我甚至還跟她合照了！", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 991, "question": "A: Hey, I'm carrying a very heavy box. ______\nB: Oh, sorry! I'll move.", "options": ["What's on your mind?", "Don't be in my way.", "Understood?", "I can't help it."], "answer": 1, "answerLabel": "B", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(B) Don't be in my way.\n【用語】Don't be in my way. (phr.)：別擋我的路。\n【中譯】A：嘿，我正搬著一個很重的箱子。別擋我的路。\nB：喔，抱歉！我會讓開。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 992, "question": "When Mom said he couldn't go to the concert, Ben ______ and didn't talk to anyone all evening.", "options": ["pulled a long face", "cost an arm and a leg", "couldn't help it", "killed it"], "answer": 0, "answerLabel": "A", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(A) pulled a long face\n【用語】pull a long face (phr.)：拉長臉；不高興\n【中譯】當媽媽說他不能去演唱會時，班拉長了臉，整個晚上都不跟任何人說話。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 993, "question": "A: Will you still go hiking if it rains tomorrow?\nB: Yes. ______", "options": ["It doesn't count.", "The more, the merrier.", "Tom is the last person to tell a lie.", "Whether it rains or not, I will go."], "answer": 3, "answerLabel": "D", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(D) Whether it rains or not, I will go.\n【用語】whether + 現在簡單式 (or not), S + 未來式 (phr.)：條件句：無論某事是否發生，都將會……\n【中譯】A：如果明天下雨，你還會去爬山嗎？\nB：會。無論下不下雨，我都會去。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 994, "question": "A: Do you remember Mr. Chen, our first-grade teacher?\nB: Mr. Chen? ______ I can't remember him at all.", "options": ["I'll pass.", "It doesn't ring a bell.", "Way to go.", "That was close."], "answer": 1, "answerLabel": "B", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(B) It doesn't ring a bell.\n【用語】It doesn't ring a bell. (phr.)：想不起來；沒印象（口語）\n【中譯】A：你記得陳老師嗎？我們一年級的老師。\nB：陳老師？我沒印象。我完全想不起他。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 995, "question": "A: Come on, just jump into the pool! Do it now!\nB: ______ I'm still scared. I'll do it when I'm ready.", "options": ["This smell makes me sick.", "You can say that again.", "Way to go.", "Don't push me."], "answer": 3, "answerLabel": "D", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(D) Don't push me.\n【用語】Don't push me. (phr.)：別逼我\n【中譯】A：快點，跳進泳池就對了！現在就跳！\nB：別逼我。我還是很害怕。我準備好了就會跳。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 996, "question": "A: Are you going to the mountains this weekend?\nB: Maybe. ______ I really want to see the snow.", "options": ["So long.", "I'm not sure whether it will snow there.", "It's time to go to bed.", "It's my turn."], "answer": 1, "answerLabel": "B", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(B) I'm not sure whether it will snow there.\n【用語】S + V + whether + 未來式 (phr.)：間接問句：未來是否會發生某事\n【中譯】A：你這個週末要去山上嗎？\nB：也許吧。我不確定那裡會不會下雪。我真的很想看雪。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 997, "question": "A: Can I borrow your new comic book?\nB: Sorry. ______ I'm only on page 20.", "options": ["Leave me alone.", "End of discussion.", "I haven't finished reading it yet.", "It's on me."], "answer": 2, "answerLabel": "C", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(C) I haven't finished reading it yet.\n【用語】not + V + yet (phr.)：還沒⋯⋯\n【中譯】A：我可以借你的新漫畫書嗎？\nB：抱歉。我還沒看完。我才看到第二十頁。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 998, "question": "A: Why does your dad speak Japanese so well?\nB: ______ He worked in Tokyo for five years.", "options": ["Time is up.", "Neither does he.", "He once lived in Japan.", "I don't buy it."], "answer": 2, "answerLabel": "C", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(C) He once lived in Japan.\n【用語】S + once + 過去式動詞 (phr.)：曾經；以前（某段時間）\n【中譯】A：你爸爸日文為什麼說得這麼好？\nB：他曾經住過日本。他在東京工作了五年。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 999, "question": "A: Can I play with your phone? Please? Please? Please?\nB: ______ I said no ten times!", "options": ["You bet.", "Stop bugging me.", "I second that.", "Which way are you heading?"], "answer": 1, "answerLabel": "B", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(B) Stop bugging me.\n【用語】Stop bugging me. (phr.)：別煩我了（俚語）\n【中譯】A：我可以玩你的手機嗎？拜託？拜託？拜託？\nB：別煩我了。我已經說了十次不行！", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1000, "question": "A: Hi, Mike. Do you have time to talk now?\nB: Sorry, I'm on a crowded bus. ______", "options": ["I've got it covered.", "I'll call you later.", "This is the least I can do.", "Last but not least."], "answer": 1, "answerLabel": "B", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(B) I'll call you later.\n【用語】I'll call you later. (phr.)：我待會打給你\n【中譯】A：嗨，麥克。你現在有時間講話嗎？\nB：抱歉，我在一台很擠的公車上。我待會打給你。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1001, "question": "A: How long does it take you to get to school?\nB: ______ My house is very close to the school.", "options": ["It's beyond me.", "I'd love to, but I have to study.", "Neither do I.", "Walking there takes me only five minutes."], "answer": 3, "answerLabel": "D", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(D) Walking there takes me only five minutes.\n【用語】V-ing + takes + 人 + 時間 (phr.)：做⋯⋯花某人多少時間\n【中譯】A：你到學校要花多久時間？\nB：走路去只要花我五分鐘。我家離學校很近。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1002, "question": "A: How was the new restaurant?\nB: ______ I want to go there again.", "options": ["It's my turn.", "It doesn't count.", "It turned out to be terrible.", "It was better than I thought."], "answer": 3, "answerLabel": "D", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(D) It was better than I thought.\n【用語】better than I thought (phr.)：比我想像的好\n【中譯】A：那家新餐廳怎麼樣？\nB：比我想像的好。我想再去一次。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1003, "question": "A: How much money did your parents give you for your birthday? Tell me!\nB: ______ That's a secret.", "options": ["I turned a deaf ear to it.", "Better late than never.", "Mind your own business.", "You can say that again."], "answer": 2, "answerLabel": "C", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(C) Mind your own business.\n【用語】Mind your own business. (phr.)：少管閒事\n【中譯】A：你爸媽生日給了你多少錢？告訴我！\nB：少管閒事。那是秘密。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1004, "question": "A: Sorry, I'm 30 minutes late for the party.\nB: ______ Come in and have some cake.", "options": ["Good things never last.", "It's now or never.", "Better late than never.", "I don't buy it."], "answer": 2, "answerLabel": "C", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(C) Better late than never.\n【用語】Better late than never. (phr.)：晚做總比不做好\n【中譯】A：抱歉，我參加派對遲到了三十分鐘。\nB：晚到總比不到好。進來吃點蛋糕吧。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1005, "question": "A: Let me pay for the drinks.\nB: No, no. ______ You paid last time.", "options": ["Who else is coming?", "What's the catch?", "It's on me.", "It was not until ten that I got home."], "answer": 2, "answerLabel": "C", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(C) It's on me.\n【用語】It's on me. (phr.)：我請客（口語）\n【中譯】A：飲料讓我付吧。\nB：不不不。我請客。你上次付過了。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1006, "question": "Teacher: No phones in class. If I see one, I will take it. ______\nStudents: Yes, Mr. Lee.", "options": ["What's the catch?", "Am I clear?", "What a play!", "It can't get any better."], "answer": 1, "answerLabel": "B", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(B) Am I clear?\n【用語】Am I clear? (phr.)：我說清楚了嗎？\n【中譯】老師：上課不准用手機。如果我看到，我就會沒收。我說清楚了嗎？\n學生們：清楚了，李老師。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1007, "question": "A: Why can't Amy wear that skirt to school?\nB: ______ The teacher won't let her.", "options": ["I get it.", "It takes her ten minutes to put it on.", "It's my treat.", "It's such a short skirt."], "answer": 3, "answerLabel": "D", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(D) It's such a short skirt.\n【用語】such a + adj. + N = so + adj. + a + N (phr.)：如此…的…（如：如此短的裙子）\n【中譯】A：為什麼艾咪不能穿那件裙子去學校？\nB：那是一件如此短的裙子。老師不會允許她穿。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1008, "question": "A: I'm so sorry. I broke your pencil.\nB: ______ I have many pencils.", "options": ["It's not a big deal.", "You killed it!", "Seeing is believing.", "It's now or never."], "answer": 0, "answerLabel": "A", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(A) It's not a big deal.\n【用語】It's not a big deal. (phr.)：小事；沒什麼（= No biggie.）\n【中譯】A：真抱歉，我把你的鉛筆弄斷了。\nB：沒什麼。我有很多枝鉛筆。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1009, "question": "A: Did Dad eat breakfast with you at seven?\nB: No. ______", "options": ["Leave me alone.", "He didn't get up until ten.", "So long.", "It's my treat."], "answer": 1, "answerLabel": "B", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(B) He didn't get up until ten.\n【用語】not + V + until + 時間/子句 (phr.)：直到⋯⋯才\n【中譯】A：爸爸七點有和你一起吃早餐嗎？\nB：沒有。他直到十點才起床。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1010, "question": "A: What do you think of my new skateboard?\nB: ______ I want one, too!", "options": ["It's sick!", "I don't buy it.", "Never mind.", "You bet."], "answer": 0, "answerLabel": "A", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(A) It's sick!\n【用語】It's sick! (phr.)：太厲害了；超棒（俚語）\n【中譯】A：你覺得我的新滑板怎麼樣？\nB：太酷了！我也想要一個！", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1011, "question": "A: The bus left five minutes ago. Let's run after it!\nB: ______ We can't catch it.", "options": ["See you later.", "Way to go.", "There's no point running after it.", "It's never too late to learn."], "answer": 2, "answerLabel": "C", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(C) There's no point running after it.\n【用語】There is no point + V-ing (phr.)：做⋯⋯沒有意義\n【中譯】A：公車五分鐘前就開走了。我們追上去吧！\nB：追它沒有意義。我們追不上的。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1012, "question": "A: When will you wash your hands?\nB: ______", "options": ["I don't mind.", "Before I eat dinner, I will wash my hands.", "I would wash my hands with cold water.", "If it rains, I will stay home."], "answer": 1, "answerLabel": "B", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(B) Before I eat dinner, I will wash my hands.\n【用語】before + 現在簡單式, S + 未來式 (phr.)：條件句：在某事發生之前，另一件事會先發生\n【中譯】A：你什麼時候會洗手？\nB：在我吃晚餐之前，我會先洗手。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1013, "question": "The box has glass cups in it, so Mom wrote \"______\" on it.", "options": ["Please be seated.", "The less, the better.", "Trick or treat!", "Handle with care."], "answer": 3, "answerLabel": "D", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(D) Handle with care.\n【用語】Handle with care. (phr.)：小心處理（常見於包裹標示）\n【中譯】箱子裡有玻璃杯，所以媽媽在上面寫了「小心處理」。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1014, "question": "A: ______ Can I get past, please?\nB: Oh, sure. Sorry, I'm in your way.", "options": ["Mind your own business.", "Don't push me.", "It's too good to be true.", "Excuse me."], "answer": 3, "answerLabel": "D", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(D) Excuse me.\n【用語】Excuse me. (phr.)：借光；對不起（禮貌用語）\n【中譯】A：借過一下。我可以過去嗎？\nB：喔，當然。抱歉，我擋到你的路了。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1015, "question": "I have three pets. ______", "options": ["What's on your mind?", "If I get a dog, I will be happy.", "One is a dog, another is a cat, and the other is a bird.", "One is a dog, and the other is a cat."], "answer": 2, "answerLabel": "C", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(C) One is a dog, another is a cat, and the other is a bird.\n【用語】one ..., another ..., the other ...（三者） (phr.)：一個…；另一個…；剩下那個…\n【中譯】我有三隻寵物。一隻是狗，另一隻是貓，剩下那隻是鳥。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1016, "question": "A: ______\nB: To buy some milk for Grandma.", "options": ["What kinds of milk do you like?", "Please be seated.", "What are you going to the store for?", "What's the matter?"], "answer": 2, "answerLabel": "C", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(C) What are you going to the store for?\n【用語】What + 疑問句 + for? (phr.)：為了什麼\n【中譯】A：你去商店是為了什麼？\nB：去幫奶奶買一些牛奶。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1017, "question": "A: Kevin, how should I make the dumplings for you?\nB: ______ I really miss them, Grandma.", "options": ["Just the way you used to make them.", "The more, the better.", "You only live once.", "It's time for dinner."], "answer": 0, "answerLabel": "A", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(A) Just the way you used to make them.\n【用語】the way + S + used to (phr.)：像（某人）以前那樣\n【中譯】A：凱文，我該怎麼幫你做水餃？\nB：就像您以前做的那樣。我真的很懷念，奶奶。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1018, "question": "A: Why is there no school today?\nB: ______", "options": ["Don't mind me.", "Oh my goodness!", "A strong typhoon is hitting Taipei.", "I'll pass."], "answer": 2, "answerLabel": "C", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(C) A strong typhoon is hitting Taipei.\n【用語】a typhoon hits + 地方 (phr.)：颱風襲擊⋯⋯\n【中譯】A：為什麼今天不用上學？\nB：一個強烈颱風正在襲擊台北。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1019, "question": "A: Why did you leave the movie early?\nB: ______", "options": ["It was such a boring movie.", "It can't get any better.", "It was too good to be true.", "It was the best movie I have ever seen."], "answer": 0, "answerLabel": "A", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(A) It was such a boring movie.\n【用語】such a + adj. + N (phr.)：這麼⋯⋯的（+ 單數可數名詞）\n【中譯】A：你為什麼提早離開電影院？\nB：那是一部這麼無聊的電影。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1020, "question": "A: Why were your shoes wet yesterday?\nB: ______", "options": ["I see.", "When I walked home, it started to rain.", "I once lived in Tainan.", "I'll call you later."], "answer": 1, "answerLabel": "B", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(B) When I walked home, it started to rain.\n【用語】When + 過去簡單式, 主詞 + 過去簡單式. (phr.)：當過去某事發生時，另一件事也發生了\n【中譯】A：你昨天的鞋子為什麼濕了？\nB：當我走路回家時，開始下雨了。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1021, "question": "A: When will you tell Mom the good news?\nB: ______", "options": ["Once she gets home, I will tell her.", "So long.", "No way!", "What a play!"], "answer": 0, "answerLabel": "A", "source": "慣用語與句型 Expressions &amp; Sentence Patterns｜慣用語與句型 Expressions & Sentence Patterns", "explanation": "【答案】(A) Once she gets home, I will tell her.\n【用語】once + 現在簡單式, S + 未來式 (phr.)：一旦……就……\n【中譯】A：你什麼時候要告訴媽媽這個好消息？\nB：一旦她回到家，我就會告訴她。", "explanationSource": "supplemental", "section": "慣用語與句型 Expressions &amp; Sentence Patterns"}, {"id": 1022, "question": "To stay healthy, eat more vegetables and go to bed early. ______, exercise every day.", "options": ["Comparatively", "In the past", "On the contrary", "Above all"], "answer": 3, "answerLabel": "D", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(D) Above all\n【用語】above all (adv.phr.)：最重要的是（強調）\n【中譯】為了保持健康，要多吃蔬菜、早點睡覺。最重要的是，要每天運動。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1023, "question": "Our school has a big library. ______, it has a new swimming pool.", "options": ["On the one hand", "At that time", "Additionally", "Instead"], "answer": 2, "answerLabel": "C", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(C) Additionally\n【用語】additionally (adv.)：此外（補充）\n【中譯】我們學校有一間大圖書館。此外，它還有一座新的游泳池。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1024, "question": "Some animals can live without water for a long time. ______, a camel can walk in the desert for days without drinking.", "options": ["Otherwise", "In contrast", "Then", "As an illustration"], "answer": 3, "answerLabel": "D", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(D) As an illustration\n【用語】as an illustration (adv.phr.)：舉例說明（舉例）（正式用語）\n【中譯】有些動物可以很長一段時間不喝水。舉例來說，駱駝可以在沙漠中走好幾天都不喝水。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1025, "question": "Mike practiced basketball every day for five years. ______, he became a famous player.", "options": ["Previously", "On this occasion", "Furthermore", "Ultimately"], "answer": 3, "answerLabel": "D", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(D) Ultimately\n【用語】ultimately (adv.)：最終；最後（總結／結果）\n【中譯】麥克五年來每天練習籃球。最後，他成為一位有名的球員。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1026, "question": "Mr. Wang said the test would be hard. ______, it was the hardest test of the year.", "options": ["Indeed", "Alternatively", "Instead", "As a result"], "answer": 0, "answerLabel": "A", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(A) Indeed\n【用語】indeed (adv.)：確實；的確（延伸證實）（正式用語）\n【中譯】王老師說這次考試會很難。的確，那是今年最難的一次考試。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1027, "question": "Many people think Tim is shy. ______, he is the most talkative boy in our class.", "options": ["In fact", "Similarly", "Of course", "Before"], "answer": 0, "answerLabel": "A", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(A) In fact\n【用語】in fact (adv.phr.)：事實上（延伸說明）\n【中譯】很多人認為提姆很害羞。事實上，他是我們班上話最多的男生。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1028, "question": "The concert started with a piano solo, ______ a song by the school choir.", "options": ["such as", "notwithstanding", "followed by", "unlike"], "answer": 2, "answerLabel": "C", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(C) followed by\n【用語】followed by + N (prep.phr.)：接著是（順序）\n【中譯】音樂會以鋼琴獨奏開場，接著是學校合唱團演唱的一首歌。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1029, "question": "Amy's English has ______ improved since she moved to London.", "options": ["markedly", "in particular", "for instance", "conversely"], "answer": 0, "answerLabel": "A", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(A) markedly\n【用語】markedly (adv.)：明顯地（說明程度）（正式用語）\n【中譯】自從艾咪搬到倫敦以後，她的英文明顯進步了。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1030, "question": "Today I talked about three ways to save water. ______, let's all try to use less water every day.", "options": ["Although", "To conclude", "In the past", "On the other hand"], "answer": 1, "answerLabel": "B", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(B) To conclude\n【用語】to conclude (adv.phr.)：總結來說；最後（結論）\n【中譯】今天我談了三種節約用水的方法。總結來說，讓我們每天都試著少用一點水。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1031, "question": "Your new bike is ______ mine. They are both red and very fast.", "options": ["similar to", "differing from", "coupled with", "unlike"], "answer": 0, "answerLabel": "A", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(A) similar to\n【用語】similar to + N (adj.phr.)：和……相似（比較）\n【中譯】你的新腳踏車和我的很像。它們都是紅色的，而且騎起來都很快。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1032, "question": "It snowed heavily last night. ______, all the schools were closed today.", "options": ["For instance", "In contrast", "As a result", "In any case"], "answer": 2, "answerLabel": "C", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(C) As a result\n【用語】as a result (adv.phr.)：結果；因此（結果）\n【中譯】昨晚下了大雪。結果，今天所有的學校都停課了。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1033, "question": "My brother loves sports, ______ I enjoy reading books.", "options": ["whereas", "otherwise", "despite", "so then"], "answer": 0, "answerLabel": "A", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(A) whereas\n【用語】whereas + 子句 (conj.)：然而；而（對比）（正式用語）\n【中譯】我哥哥喜歡運動，而我喜歡看書。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1034, "question": "Lily saw a snake for the first time in her life. ______, she screamed and ran away.", "options": ["For this purpose", "Immediately", "Again", "On the whole"], "answer": 1, "answerLabel": "B", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(B) Immediately\n【用語】immediately (adv.)：立刻；馬上（時間）\n【中譯】莉莉這輩子第一次看到蛇。她立刻尖叫著跑走了。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1035, "question": "You can take the bus to the zoo. ______, you can ride a bike there.", "options": ["Initially", "Therefore", "Still", "Alternatively"], "answer": 3, "answerLabel": "D", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(D) Alternatively\n【用語】alternatively (adv.)：或者；另一個選擇是（替代）\n【中譯】你可以搭公車去動物園。或者，你也可以騎腳踏車去那裡。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1036, "question": "Grandpa got sick from smoking in 2015. ______, he never smoked again.", "options": ["Thereafter", "In particular", "For instance", "Conversely"], "answer": 0, "answerLabel": "A", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(A) Thereafter\n【用語】thereafter (adv.)：此後；從那之後（時間）（正式用語）\n【中譯】爺爺在2015年因為抽菸而生病。從那之後，他再也沒有抽過菸。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1037, "question": "The two runners crossed the finish line ______, so nobody knew who won.", "options": ["on the contrary", "simultaneously", "on the whole", "subsequently"], "answer": 1, "answerLabel": "B", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(B) simultaneously\n【用語】simultaneously (adv.)：同時（時間）（正式用語）\n【中譯】那兩位跑者同時衝過終點線，所以沒有人知道誰贏了。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1038, "question": "Jenny can speak Japanese ______ English.", "options": ["as well as", "so then", "similar", "notably"], "answer": 0, "answerLabel": "A", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(A) as well as\n【用語】as well as + N (conj.phr.)：以及；還有（補充）\n【中譯】珍妮會說日文，也會說英文。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1039, "question": "The teacher talked about the class rules for an hour. ______, she wants us to be kind and safe.", "options": ["Meanwhile", "In essence", "Before", "As a consequence"], "answer": 1, "answerLabel": "B", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(B) In essence\n【用語】in essence (adv.phr.)：本質上；基本上（總結重點）（正式用語）\n【中譯】老師花了一個小時講班規。基本上，她希望我們友善待人並注意安全。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1040, "question": "______ I finish my homework, I will play basketball with my friends.", "options": ["Recently", "After", "Briefly", "Although"], "answer": 1, "answerLabel": "B", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(B) After\n【用語】after + N/子句 (conj.)：在……之後（時間順序）\n【中譯】在我寫完功課之後，我會和朋友去打籃球。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1041, "question": "We need some fruit for the party. ______, we need two watermelons and ten apples.", "options": ["Nevertheless", "Previously", "Specifically", "On the other hand"], "answer": 2, "answerLabel": "C", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(C) Specifically\n【用語】specifically (adv.)：具體來說（舉例說明）\n【中譯】派對需要一些水果。具體來說，我們需要兩顆西瓜和十顆蘋果。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1042, "question": "Kate forgot to bring her umbrella. ______, she got wet in the rain.", "options": ["For example", "Instead", "Moreover", "Consequently"], "answer": 3, "answerLabel": "D", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(D) Consequently\n【用語】consequently (adv.)：因此；結果（結果）（正式用語）\n【中譯】凱特忘了帶雨傘。因此，她被雨淋濕了。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1043, "question": "Our school trip starts with a visit to the museum, ______ lunch at a small restaurant.", "options": ["on the contrary", "followed by", "unlike", "regardless of"], "answer": 1, "answerLabel": "B", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(B) followed by\n【用語】followed by + N (prep.phr.)：接著是；隨後是（時間順序）\n【中譯】我們的校外教學先參觀博物館，接著在一間小餐廳吃午餐。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1044, "question": "The hotel was clean, the food was good, and the workers were kind. ______, it was a great hotel.", "options": ["On the whole", "Shortly", "And yet", "For instance"], "answer": 0, "answerLabel": "A", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(A) On the whole\n【用語】on the whole (adv.phr.)：大體上；整體來說（總結）\n【中譯】那間飯店很乾淨，食物很好吃，員工也很親切。整體來說，那是一間很棒的飯店。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1045, "question": "We waited for the bus for more than an hour. ______, it came.", "options": ["In other words", "Namely", "Finally", "To be sure"], "answer": 2, "answerLabel": "C", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(C) Finally\n【用語】finally (adv.)：最後；終於（順序／結果）\n【中譯】我們等公車等了一個多小時。終於，公車來了。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1046, "question": "Peter is allergic to milk. ______, he never eats ice cream.", "options": ["Next", "To demonstrate", "However", "Therefore"], "answer": 3, "answerLabel": "D", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(D) Therefore\n【用語】therefore (adv.)：因此（結果）\n【中譯】彼得對牛奶過敏。因此，他從來不吃冰淇淋。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1047, "question": "That's all for today's class. ______, we learned three things: colors, animals, and numbers.", "options": ["Instead", "At this point", "For example", "In summary"], "answer": 3, "answerLabel": "D", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(D) In summary\n【用語】in summary (adv.phr.)：總結來說（總結）\n【中譯】今天的課就到這裡。總結來說，我們學了三件事：顏色、動物和數字。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1048, "question": "Tom's sister loves vegetables. ______ her, Tom never eats them.", "options": ["By and large", "Unlike", "In this case", "In fact"], "answer": 1, "answerLabel": "B", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(B) Unlike\n【用語】unlike + N (prep.)：不像；與……不同（對比）\n【中譯】湯姆的姊姊很愛吃蔬菜。跟她不一樣，湯姆從來不吃蔬菜。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1049, "question": "Cats like to sleep all day, ______ dogs like to go out and play.", "options": ["it could also be said that", "for this reason", "whereas", "in brief"], "answer": 2, "answerLabel": "C", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(C) whereas\n【用語】whereas + 子句 (conj.)：然而；而（對比）（正式用語）\n【中譯】貓喜歡整天睡覺，而狗喜歡出去玩。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1050, "question": "Don't be too hard on Jimmy. ______, he is only five years old.", "options": ["Instead", "In the future", "Similarly", "After all"], "answer": 3, "answerLabel": "D", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(D) After all\n【用語】after all (adv.phr.)：畢竟（總結理由）\n【中譯】不要對吉米太嚴格。畢竟，他才五歲而已。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1051, "question": "Sam lost his key. ______, he could not open the door of his house.", "options": ["Hence", "On the contrary", "Concurrently", "For instance"], "answer": 0, "answerLabel": "A", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(A) Hence\n【用語】hence (adv.)：因此（結果）（正式用語）\n【中譯】山姆弄丟了鑰匙。因此，他打不開家裡的門。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1052, "question": "This building was ______ a school, but now it is a library.", "options": ["especially", "regardless of", "formerly", "in particular"], "answer": 2, "answerLabel": "C", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(C) formerly\n【用語】formerly (adv.)：以前；從前（時間）（正式用語）\n【中譯】這棟建築以前是一所學校，但現在是一間圖書館。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1053, "question": "The bridge was broken. ______, we had to take a boat across the river.", "options": ["Likewise", "To illustrate", "Thus", "While"], "answer": 2, "answerLabel": "C", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(C) Thus\n【用語】thus (adv.)：因此；所以（結果）（正式用語）\n【中譯】橋壞了。因此，我們必須搭船過河。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1054, "question": "There are two girls in my family, ______ my sister and me.", "options": ["despite", "rather", "namely", "after"], "answer": 2, "answerLabel": "C", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(C) namely\n【用語】namely (adv.)：也就是；即（舉例說明）（正式用語）\n【中譯】我家有兩個女孩，也就是我姊姊和我。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1055, "question": "My mom can cook dinner and talk on the phone ______.", "options": ["at the same time", "on the contrary", "therefore", "that is to say"], "answer": 0, "answerLabel": "A", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(A) at the same time\n【用語】at the same time (adv.phr.)：同時（時間）\n【中譯】我媽媽可以一邊煮晚餐一邊講電話。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1056, "question": "______, people wrote letters to their friends. Now they send messages on their phones.", "options": ["Concurrently", "It seems", "Clearly", "In the past"], "answer": 3, "answerLabel": "D", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(D) In the past\n【用語】in the past (adv.phr.)：過去；以前（時間）\n【中譯】過去，人們會寫信給朋友。現在他們用手機傳訊息。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1057, "question": "My uncle is a cook now. ______, he was a bus driver.", "options": ["Afterward", "In short", "Soon", "Previously"], "answer": 3, "answerLabel": "D", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(D) Previously\n【用語】previously (adv.)：先前；以前（順序）\n【中譯】我叔叔現在是廚師。以前，他是公車司機。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1058, "question": "We visited many places ______ the summer vacation.", "options": ["however", "granted", "during", "including"], "answer": 2, "answerLabel": "C", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(C) during\n【用語】during + N (prep.)：在……期間（時間）\n【中譯】暑假期間，我們去了很多地方。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1059, "question": "I ate a piece of cake, and it was delicious. Can I have ______ piece?", "options": ["another", "nevertheless", "correspondingly", "also"], "answer": 0, "answerLabel": "A", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(A) another\n【用語】another + N (adj.)：另一個（補充）\n【中譯】我吃了一塊蛋糕，很好吃。我可以再吃一塊嗎？", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1060, "question": "Students must put their books away ______ the start of the test.", "options": ["after", "such as", "unlike", "prior to"], "answer": 3, "answerLabel": "D", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(D) prior to\n【用語】prior to + N/V-ing (prep.phr.)：在……之前（時間）（正式用語）\n【中譯】學生必須在考試開始之前把書收好。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1061, "question": "The movie was too long, the story was boring, and the actors were bad. ______, it was a terrible movie.", "options": ["At the same time", "In brief", "Subsequently", "Currently"], "answer": 1, "answerLabel": "B", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(B) In brief\n【用語】in brief (adv.phr.)：簡言之（總結）\n【中譯】那部電影太長，故事很無聊，演員也演得不好。簡言之，那是一部很糟的電影。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1062, "question": "It rained all day during our trip to the zoo. ______, we had a great time.", "options": ["Nonetheless", "That is", "Presently", "In conclusion"], "answer": 0, "answerLabel": "A", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(A) Nonetheless\n【用語】nonetheless (adv.)：儘管如此（讓步）（正式用語）\n【中譯】我們去動物園玩的那天下了一整天的雨。儘管如此，我們還是玩得很開心。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1063, "question": "Tom's room is always clean. ______, his brother's room is very messy.", "options": ["Then", "In contrast", "Likewise", "To put it differently"], "answer": 1, "answerLabel": "B", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(B) In contrast\n【用語】in contrast (adv.phr.)：相比之下；對照之下（對比）\n【中譯】湯姆的房間總是很乾淨。相比之下，他弟弟的房間非常亂。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1064, "question": "This phone is light and cheap. ______, it takes great photos.", "options": ["Instead", "On the one hand", "For instance", "Moreover"], "answer": 3, "answerLabel": "D", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(D) Moreover\n【用語】moreover (adv.)：此外；而且（比較／補充）（正式用語）\n【中譯】這支手機又輕又便宜。此外，它還能拍出很棒的照片。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1065, "question": "I want to join the English speech contest. ______, my English is not perfect, but I practice every day.", "options": ["Hence", "After all", "Earlier", "Admittedly"], "answer": 3, "answerLabel": "D", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(D) Admittedly\n【用語】admittedly (adv.)：不可否認地（讓步）\n【中譯】我想參加英文演講比賽。不可否認，我的英文並不完美，但我每天都在練習。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1066, "question": "______ it was raining, Eric still went running.", "options": ["Naturally", "Finally", "Even though", "At that time"], "answer": 2, "answerLabel": "C", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(C) Even though\n【用語】even though + 子句 (conj.phr.)：即使；雖然（讓步）\n【中譯】雖然在下雨，艾瑞克還是去跑步了。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1067, "question": "Here is how to make a paper boat. ______, fold the paper in half, and then fold down the top corners.", "options": ["Finally", "In short", "First", "Albeit"], "answer": 2, "answerLabel": "C", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(C) First\n【用語】first / second / third (adv.)：第一／第二／第三（順序）\n【中譯】這是摺紙船的方法。首先，把紙對摺，然後把上面的兩個角往下摺。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1068, "question": "Our teacher told us to eat fruit, drink water, sleep early, and play sports. ______, she wants us to stay healthy.", "options": ["On the contrary", "To summarize", "Later", "Even so"], "answer": 1, "answerLabel": "B", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(B) To summarize\n【用語】to summarize (adv.phr.)：總結（總結）\n【中譯】老師要我們吃水果、喝水、早點睡覺和運動。總結來說，她希望我們保持健康。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1069, "question": "Swimming is good for your body. ______, it is a lot of fun.", "options": ["Conversely", "In addition", "Meanwhile", "Initially"], "answer": 1, "answerLabel": "B", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(B) In addition\n【用語】in addition (adv.phr.)：此外；另外（補充）\n【中譯】游泳對身體有益。此外，它也非常好玩。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1070, "question": "My dad never drives to work. ______, he takes the MRT every day.", "options": ["Initially", "Instead", "Similarly", "Besides"], "answer": 1, "answerLabel": "B", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(B) Instead\n【用語】instead (adv.)：反而；取而代之（替代）\n【中譯】我爸爸從不開車上班。取而代之的是，他每天搭捷運。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1071, "question": "Ben is a vegetarian. ______, he doesn't eat any meat.", "options": ["Next", "In other words", "Chiefly", "All things considered"], "answer": 1, "answerLabel": "B", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(B) In other words\n【用語】in other words (adv.phr.)：換句話說（解釋／總結）\n【中譯】Ben 是素食者。換句話說，他完全不吃肉。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1072, "question": "Today the park is full of trees and flowers. ______, it was an empty parking lot.", "options": ["Therefore", "To illustrate", "Previously", "In any event"], "answer": 2, "answerLabel": "C", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(C) Previously\n【用語】previously (adv.)：先前；以前（時間）\n【中譯】現在這座公園種滿了樹和花。以前，它是一個空蕩蕩的停車場。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1073, "question": "Lucy stayed up late to watch TV last night. ______, she was very sleepy in class this morning.", "options": ["For this reason", "Now", "In contrast", "As an example"], "answer": 0, "answerLabel": "A", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(A) For this reason\n【用語】for this reason (adv.phr.)：因為這個原因；因此（原因）\n【中譯】Lucy 昨晚熬夜看電視。因為這個原因，她今天早上上課時很想睡覺。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1074, "question": "There are many ways to get to school. ______, you can walk, ride a bike, or take a bus.", "options": ["However", "In the meantime", "Particularly", "For example"], "answer": 3, "answerLabel": "D", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(D) For example\n【用語】for example (adv.phr.)：例如；舉例來說（舉例）\n【中譯】上學的方法有很多種。例如，你可以走路、騎腳踏車或搭公車。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1075, "question": "Mr. Chen teaches math at our school now. ______, he worked at a bank for ten years.", "options": ["On the whole", "A different view is", "Previously", "Thus"], "answer": 2, "answerLabel": "C", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(C) Previously\n【用語】previously (adv.)：先前；以前（時間）（正式用語）\n【中譯】陳老師現在在我們學校教數學。先前，他在銀行工作了十年。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1076, "question": "This bike is too expensive for me. ______, it is too big for me to ride.", "options": ["At length", "Accordingly", "Instead", "Further"], "answer": 3, "answerLabel": "D", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(D) Further\n【用語】further (adv.)：此外；再者（補充）（正式用語）\n【中譯】這台腳踏車對我來說太貴了。此外，它也太大，我騎不了。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1077, "question": "That is all I want to say about my trip to Japan. ______, thank you all for listening.", "options": ["Likewise", "Finally", "Meanwhile", "For instance"], "answer": 1, "answerLabel": "B", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(B) Finally\n【用語】finally (adv.)：最後（總結）\n【中譯】以上就是我想分享的日本之旅。最後，謝謝大家聆聽。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1078, "question": "Plants need sunlight to grow. ______, children need good food to grow up healthy.", "options": ["Before", "Otherwise", "In the same way", "As a result"], "answer": 2, "answerLabel": "C", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(C) In the same way\n【用語】in the same way (adv.phr.)：同樣地（比較）\n【中譯】植物需要陽光才能生長。同樣地，孩子需要好的食物才能健康長大。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1079, "question": "Tom's twin brother loves basketball. ______ his brother, Tom never plays it.", "options": ["Together with", "Differing from", "Coupled with", "Illustrated by"], "answer": 1, "answerLabel": "B", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(B) Differing from\n【用語】differing from + N (prep.phr.)：與……不同（對比）\n【中譯】Tom 的雙胞胎哥哥很愛打籃球。和他哥哥不同，Tom 從來不打籃球。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1080, "question": "Our school trip had good food, fun games, and great weather. ______, it was a wonderful day.", "options": ["For instance", "To sum up", "However", "Subsequently"], "answer": 1, "answerLabel": "B", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(B) To sum up\n【用語】to sum up (adv.phr.)：總而言之（總結）\n【中譯】我們的校外教學有好吃的食物、好玩的遊戲和很棒的天氣。總而言之，那是很美好的一天。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1081, "question": "My brother is good at drawing. ______, my sister draws beautiful pictures.", "options": ["Similarly", "As well as", "Indeed", "Consequently"], "answer": 0, "answerLabel": "A", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(A) Similarly\n【用語】similarly (adv.)：同樣地；相似地（比較）\n【中譯】我哥哥很會畫畫。同樣地，我姊姊也畫出很漂亮的圖。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1082, "question": "Eating healthy food is important for your body. ______, you need to get enough sleep.", "options": ["Equally important", "At that time", "Otherwise", "Overall"], "answer": 0, "answerLabel": "A", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(A) Equally important\n【用語】equally important (adj.phr.)：同樣重要的是（補充）\n【中譯】吃健康的食物對身體很重要。同樣重要的是，你需要有充足的睡眠。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}, {"id": 1083, "question": "Yesterday I finished my homework at seven. ______, I watched TV with my family.", "options": ["Then", "At present", "On the other hand", "In other words"], "answer": 0, "answerLabel": "A", "source": "轉折詞 Transition Words｜轉折詞 Transition Words", "explanation": "【答案】(A) Then\n【用語】then (adv.)：然後（順序）\n【中譯】昨天我七點寫完功課。然後，我和家人一起看電視。", "explanationSource": "supplemental", "section": "轉折詞 Transition Words"}]};